      - "${ARCHIVE_ROOT}/romm/assets:/romm/assets:rw"
      - "${ARCHIVE_ROOT}/romm/config:/romm/config:rw"
      - "${ARCHIVE_ROOT}/romm/resources:/romm/resources:rw"
      - "/var/lib/pc-game-archive/romm/redis-data:/redis-data:rw"
    depends_on:
      romm-db:
        condition: service_healthy
        restart: true
    restart: unless-stopped

  romm-db:
    image: mariadb:11
    container_name: romm-db
    env_file:
      - /etc/pc-game-archive/romm.env
    volumes:
      - "/var/lib/pc-game-archive/romm/mariadb:/var/lib/mysql:rw"
    healthcheck:
      test: ["CMD", "healthcheck.sh", "--connect", "--innodb_initialized"]
      start_period: 30s
      interval: 10s
      timeout: 5s
      retries: 10
    restart: unless-stopped
COMPOSE_ROMM
  ROMM_CONFIG_CREATED=1
else
  rm -f "$STACK_DIR/compose.romm.yml"
fi

# Optical ingest is limited to the configured drive allow-list. The dispatcher
# identifies media first; ARM receives only video/audio while data discs use the
# preservation backend and then enter classification.
ARM_CONFIG_CREATED=0
install -d -m 0755 /etc/pc-game-archive
: > /etc/pc-game-archive/media-drives
for dev in "${MEDIA_DRIVES[@]}"; do
  printf '%s\n' "$dev" >> /etc/pc-game-archive/media-drives
done
chmod 0644 /etc/pc-game-archive/media-drives

# Informational drive capabilities are kept separate from the allow-list. Every
# configured lane enters the same media-identification dispatcher; the physical
# drive capability only constrains what media it can read.
printf '# device\trole\tauto_ingest\n' > /etc/pc-game-archive/optical-drive-roles.tsv
for dev in "${MEDIA_DRIVES[@]}"; do
  if is_bluray_drive "$dev"; then
    role=bluray
  elif udevadm info --query=property --name="$dev" 2>/dev/null | grep -q '^ID_CDROM_DVD=1$'; then
    role=dvd-cd
  else
    role=cd
  fi
  printf '%s\t%s\tyes\n' "$dev" "$role" >> /etc/pc-game-archive/optical-drive-roles.tsv
done
chmod 0644 /etc/pc-game-archive/optical-drive-roles.tsv
install -d -m 0755 /var/lib/pc-game-archive/optical-health
printf '%s\n' "$ARCHIVE_ROOT" > /etc/pc-game-archive/archive-root
chmod 0644 /etc/pc-game-archive/archive-root

# ARM's Docker image starts its own udev daemon and ships a 51-docker-arm.rules
# rule that launches ARM for every srN drive. PCGA already owns the optical
# trigger on the host so leaving the in-container rule enabled creates two
# independent ingestion paths and can start unintended drives (for example sr0
# while the configured media drive is sr1). Shadow ARM's rule source with a
# comment-only file; /lib/udev/rules.d/51-docker-arm.rules is a symlink to it
# in the upstream image.
cat > /etc/pc-game-archive/51-docker-arm.rules <<'PCGA_ARM_UDEV_DISABLED'
# Disabled by PC Game Archive: host systemd/udev owns optical-media triggering.
PCGA_ARM_UDEV_DISABLED
chmod 0644 /etc/pc-game-archive/51-docker-arm.rules

if [[ $ENABLE_MEDIA_RIPPER -eq 1 && ${#MEDIA_DRIVES[@]} -gt 0 ]]; then
  cat > "$STACK_DIR/compose.arm.yml" <<COMPOSE_ARM_HEAD
services:
  arm-rippers:
    image: ${ARM_IMAGE}
    container_name: arm-rippers
    ports:
      - "${ARM_PORT}:8080/tcp"
    environment:
      ARM_UID: "${ADMIN_UID}"
      ARM_GID: "${ADMIN_GID}"
      TZ: "${TZ_VALUE}"
    volumes:
      - "${ARCHIVE_ROOT}/media/arm/home:/home/arm:rw"
      - "${ARCHIVE_ROOT}/media/arm/music:/home/arm/music:rw"
      - "${ARCHIVE_ROOT}/media/arm/logs:/home/arm/logs:rw"
      - "${ARCHIVE_ROOT}/media/arm/work:/home/arm/media:rw"
      - "${ARCHIVE_ROOT}/media/arm/config:/etc/arm/config:rw"
      # Disable ARM's internal all-drives udev auto-trigger. PCGA's host-side
      # pcga-arm-rip@.service is the sole ingestion trigger and enforces the
      # configured media-drive allowlist.
      - "/etc/pc-game-archive/51-docker-arm.rules:/opt/arm/setup/51-docker-arm.rules:rw"
    devices:
COMPOSE_ARM_HEAD
  for dev in "${MEDIA_DRIVES[@]}"; do
    printf '      - "%s:%s"\n' "$dev" "$dev" >> "$STACK_DIR/compose.arm.yml"
    sgdev="$(sg_for_sr "$dev")"
    if [[ -n "$sgdev" && -e "$sgdev" ]]; then
      printf '      - "%s:%s"\n' "$sgdev" "$sgdev" >> "$STACK_DIR/compose.arm.yml"
    else
      warn "No matching /dev/sgN found for $dev; ARM can run, but MakeMKV may have reduced drive access."
    fi
    mkdir -p "/mnt/dev/$(basename "$dev")"
  done
  cat >> "$STACK_DIR/compose.arm.yml" <<'COMPOSE_ARM_TAIL'
    # Video metadata is handled asynchronously by PCGA after ripping. Disable
    # ARM's legacy DVD CRC web lookup so an external service cannot stall the drive.
    extra_hosts:
      - "1337server.pythonanywhere.com:127.0.0.1"
    privileged: true
    restart: unless-stopped
COMPOSE_ARM_TAIL
  ARM_CONFIG_CREATED=1
else
  rm -f "$STACK_DIR/compose.arm.yml"
fi

# ----- Read-only pipeline status sidecar ------------------------------------
# Run the status web UI as a separate, read-only Docker service rather than
# injecting another daemon into ARM. It shares ARM's PID namespace so it can
# observe MakeMKV/ARM/HandBrake processes without the Docker socket.
install -d -m 0755 "$STACK_DIR/status"
cat > "$STACK_DIR/status/server.py" <<'PCGA_STATUS_SERVER'
#!/usr/bin/env python3
"""PC Game Archive pipeline status and manual-classification portal.

Runs as a hardened read-only sidecar. Manual classification is exposed through
portal-owned JSON endpoints backed by pcga-manual-review, so the container retains
no archive write access and the browser never receives the review service token.
Only the Python standard library is required.
"""

from __future__ import annotations

import argparse
import base64
import datetime as dt
import html
import http.client
import json
import mimetypes
import os
import re
from pathlib import Path
import shutil
import socket
import ssl
import sqlite3
import subprocess
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, quote, urlencode, parse_qs, unquote
import urllib.error
import urllib.request

VERSION = "0.17.53"
ARM_DB = Path("/home/arm/db/arm.db")
ARM_LOGS = Path("/home/arm/logs")
PROGRESS_DIR = ARM_LOGS / "progress"
RAW = Path("/home/arm/media/raw")
TRANSCODE = Path("/home/arm/media/transcode")
COMPLETED = Path("/home/arm/media/completed")
MUSIC = Path("/home/arm/music")
STATUS_ROOT = Path("/pcga/status")
PENDING = STATUS_ROOT / "metadata-pending"
QUAR_UNIDENTIFIED = STATUS_ROOT / "quarantine" / "unidentified"
LIBRARY = STATUS_ROOT / "library"
PHOTOS = LIBRARY / "photos"
PHOTO_EXTS = {".jpg", ".jpeg", ".png", ".webp", ".gif", ".avif", ".bmp"}
INGEST = STATUS_ROOT / "ingest"
DRIVES_FILE = STATUS_ROOT / "media-drives"
ROLES_FILE = STATUS_ROOT / "optical-drive-roles.tsv"
OPTICAL_HEALTH_DIR = STATUS_ROOT / "optical-health"
OPTICAL_DISPATCH_DIR = STATUS_ROOT / "optical-dispatch"
CONFIG_FILE = Path("/etc/arm/config/arm.yaml")

def _container_default_gateway() -> str:
    """Return this container network namespace's IPv4 default gateway.

    host.docker.internal normally resolves to docker0 on Linux, which is wrong
    when pcga-status is attached to a user-defined Compose bridge. Reading the
    kernel route table makes the portal resilient even when older compose files
    are missing the explicit PCGA_*_UPSTREAM environment entries.
    """
    try:
        rows = Path("/proc/net/route").read_text(encoding="utf-8", errors="replace").splitlines()[1:]
        for row in rows:
            fields = row.split()
            if len(fields) < 3 or fields[1] != "00000000":
                continue
            raw = bytes.fromhex(fields[2])
            if len(raw) == 4:
                return socket.inet_ntoa(raw[::-1])
    except Exception:
        pass
    return "host.docker.internal"

