.now-playing-modal{position:fixed;right:clamp(20px,3vw,52px);top:clamp(20px,3vw,44px);z-index:28;width:min(560px,44vw);padding:16px 18px;border:1px solid var(--line);border-radius:24px;background:rgba(34,20,12,.88);backdrop-filter:blur(20px) saturate(135%);box-shadow:0 18px 45px rgba(0,0,0,.42);display:grid;grid-template-columns:86px minmax(0,1fr);gap:16px;align-items:center;opacity:0;transform:translateY(-12px);pointer-events:none;transition:.18s opacity,.18s transform}.now-playing-modal.show{opacity:1;transform:none;pointer-events:auto}.cover{width:86px;height:86px;border-radius:16px;object-fit:cover;background:rgba(255,255,255,.07);border:1px solid var(--line)}.cover-placeholder{width:86px;height:86px;border-radius:16px;background:linear-gradient(145deg,rgba(232,161,94,.20),rgba(255,244,230,.04));display:grid;place-items:center;font-size:36px;border:1px solid var(--line)}.track{min-width:0}.now-label{text-transform:uppercase;letter-spacing:.12em;font-size:.60em;color:var(--blue);font-weight:850}.track-title{font-size:clamp(22px,1.8vw,31px);font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.track-meta{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;font-size:.78em}.progress-line{display:flex;align-items:center;gap:10px;margin-top:9px}.progress{height:6px;background:rgba(255,255,255,.10);border-radius:999px;overflow:hidden;flex:1}.progress>div{height:100%;width:0;background:var(--blue);border-radius:999px}.time{color:var(--muted);font-size:.60em;min-width:72px;text-align:right}.music-device{color:var(--muted);font-size:.58em;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.controls{grid-column:1/-1;display:flex;gap:9px;align-items:center;justify-content:flex-end;margin-top:2px}.ctl{width:54px;height:54px;border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.065);color:var(--text);font-size:23px;font-weight:900;display:grid;place-items:c