.music-browser{position:fixed;inset:0;z-index:42;display:none;place-items:center;padding:clamp(18px,4vw,54px);background:rgba(13,8,5,.70);backdrop-filter:blur(16px)}.music-browser.show{display:grid}.music-panel{width:min(980px,92vw);max-height:min(820px,88vh);display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--line);border-radius:28px;background:rgba(34,20,12,.97);box-shadow:0 28px 80px rgba(0,0,0,.58)}.music-browser-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 22px 14px}.music-browser-title{font-size:clamp(27px,2.4vw,40px);font-weight:950}.music-browser-sub{color:var(--muted);font-size:.68em;margin-top:3px}.music-close{width:54px;height:54px;border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);font-size:25px}.music-search{display:flex;gap:10px;padding:0 22px 16px}.music-search input{flex:1;min-width:0;height:56px;border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.055);color:var(--text);padding:0 16px;font:inherit}.music-search button{height:56px;border-radius:16px;border:1px solid var(--line);background:rgba(232,161,94,.16);color:var(--text);padding:0 20px;font-weight:900}.music-list{overflow:auto;padding:0 16px 18px;display:grid;gap:8px}.music-item{display:grid;grid-template-columns:58px minmax(0,1fr) auto;align-items:center;gap:14px;width:100%;min-height:72px;padding:7px 12px;border-radius:17px;border:1px solid transparent;background:rgba(255,255,255,.035);color:var(--text);text-align:left;cursor:pointer}.music-item:hover{background:rgba(255,255,255,.065)}.music-art{width:58px;height:58px;border-radius:12px;object-fit:cover;background:rgba(255,255,255,.07)}.music-art-placeholder{width:58px;height:58px;border-radius:12px;display:grid;place-items:center;background:rgba(232,161,94,.13);font-size:25px}.music-item-title{font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.music-item-meta{color:var(--muted);font