.photo-browser{position:fixed;inset:0;z-index:46;display:none;place-items:center;padding:clamp(18px,3vw,46px);background:rgba(13,8,5,.72);backdrop-filter:blur(16px)}.photo-browser.show{display:grid}.photo-panel{width:min(1240px,95vw);max-height:min(900px,91vh);display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--line);background:var(--panel-solid);box-shadow:0 28px 80px rgba(0,0,0,.58)}.photo-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 22px 14px}.photo-title{font-size:clamp(27px,2.4vw,40px);font-weight:950}.photo-sub{color:var(--muted);font-size:.68em;margin-top:3px}.photo-close{width:54px;height:54px;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);font-size:25px}.photo-search{display:flex;gap:10px;padding:0 22px 14px}.photo-search input{flex:1;min-width:0;height:56px;border:1px solid var(--line);background:rgba(255,255,255,.055);color:var(--text);padding:0 16px;font:inherit}.photo-search button,.photo-action{min-height:48px;border:1px solid var(--line);background:var(--accent-soft);color:var(--text);padding:0 16px;font-weight:900}.photo-grid{overflow:auto;padding:0 18px 20px;display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}.photo-card{display:flex;flex-direction:column;min-width:0;padding:8px;border:1px solid var(--line);background:rgba(255,255,255,.035);color:var(--text);text-align:left}.photo-card img{width:100%;aspect-ratio:4/3;object-fit:cover;background:rgba(255,255,255,.05);display:block}.photo-card-name{font-weight:850;font-size:.64em;margin-top:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.photo-card-actions{display:flex;gap:6px;margin-top:8px}.photo-card-actions button{flex:1;min-height:40px;padding:0 8px;font-size:.56em}.photo-viewer{position:fixed;inset:0;z-index:55;display:none;place-items:center;padding:20px;background:rgba(0,0,0,.9)}.photo-viewer.show{display:grid}.photo-viewer-inner{max-width:96vw;max-heigh