.library-browser{position:fixed;inset:0;z-index:44;display:none;place-items:center;padding:clamp(18px,3vw,46px);background:rgba(13,8,5,.72);backdrop-filter:blur(16px)}.library-browser.show{display:grid}.pc-game-stream{position:fixed;inset:0;z-index:1200;background:#050505;display:none;flex-direction:column}.pc-game-stream.show{display:flex}.pc-game-stream-bar{min-height:52px;padding:8px 12px;display:flex;align-items:center;justify-content:space-between;gap:14px;background:rgba(18,20,23,.96);border-bottom:1px solid rgba(255,255,255,.14)}.pc-game-stream-bar>div:first-child{display:flex;align-items:baseline;gap:12px;min-width:0}.pc-game-stream-bar strong{font-size:18px}.pc-game-stream-bar span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pc-game-stream-actions{display:flex;gap:8px}.pc-game-stream-actions button{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 12px}.pc-game-stream iframe{width:100%;height:calc(100vh - 53px);border:0;background:#000;flex:1}.library-panel{width:min(1180px,94vw);max-height:min(880px,90vh);display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--line);border-radius:28px;background:rgba(34,20,12,.97);box-shadow:0 28px 80px rgba(0,0,0,.58)}.review-browser{z-index:58}.review-panel{width:min(1380px,96vw)}.review-layout{display:grid;grid-template-columns:minmax(250px,330px) minmax(0,1fr);min-height:0;overflow:hidden;border-top:1px solid var(--line)}.review-queue{overflow:auto;padding:12px;border-right:1px solid var(--line);background:rgba(0,0,0,.12)}.review-queue-item{width:100%;display:block;text-align:left;padding:13px 14px;margin-bottom:8px;border:1px solid var(--line);background:rgba(255,255,255,.035);color:var(--text);cursor:pointer}.review-queue-item.selected{border-color:var(--accent);background:var(--accent-soft)}.review-queue-title{font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.review-queue-me