#!/usr/bin/env bash
set -Eeuo pipefail
install -d -m 0700 /etc/pc-game-archive
provider="${1:-}"
if [[ "$provider" == "--clear" ]]; then
  rm -f /etc/pc-game-archive/arm-omdb-key /etc/pc-game-archive/arm-tmdb-key
  echo omdb > /etc/pc-game-archive/arm-metadata-provider
  chmod 0600 /etc/pc-game-archive/arm-metadata-provider
  systemctl try-restart pcga-metadata-classify.service >/dev/null 2>&1 || true
  echo "Managed asynchronous metadata keys cleared. ARM was not restarted."
  exit 0
fi
if [[ -z "$provider" ]]; then
  read -r -p 'Metadata provider [omdb/tmdb] (default omdb): ' provider
  provider="${provider:-omdb}"
fi
provider="${provider,,}"
case "$provider" in omdb|tmdb) ;; *) echo "provider must be omdb or tmdb" >&2; exit 2 ;; esac
read -r -s -p "${provider^^} API key: " key; echo
[[ -n "$key" ]] || { echo "API key cannot be empty" >&2; exit 2; }
printf '%s\n' "$provider" > /etc/pc-game-archive/arm-metadata-provider
chmod 0600 /etc/pc-game-archive/arm-metadata-provider
if [[ "$provider" == omdb ]]; then
  printf '%s\n' "$key" > /etc/pc-game-archive/arm-omdb-key
  chmod 0600 /etc/pc-game-archive/arm-omdb-key
else
  printf '%s\n' "$key" > /etc/pc-game-archive/arm-tmdb-key
  chmod 0600 /etc/pc-game-archive/arm-tmdb-key
fi
systemctl try-restart pcga-metadata-classify.service >/dev/null 2>&1 || true
echo "Asynchronous metadata provider configured as $provider. ARM rip path remains API-independent; ARM was not restarted."
ARM_METADATA
chmod 0755 /usr/local/sbin/pcga-arm-metadata-configure

