cat > /usr/local/sbin/pcga-arm-reconcile <<'ARM_RECONCILE'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"
[[ -n "$name" ]] || { echo "Usage: pcga-arm-reconcile srN" >&2; exit 2; }
dev="/dev/$name"

[[ "$(docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null || true)" == true ]] || {
  echo "ARM container is not running" >&2
  exit 75
}

# Serialize only this short database reconciliation transaction. This is NOT a
# global rip lock: sr0/sr1 remain free to rip concurrently.
exec 8>/run/pcga-arm-db-reconcile.lock
flock -w 15 8 || {
  echo "Timed out waiting for ARM reconciliation DB lock" >&2
  exit 75
}

docker exec -i --user arm --workdir /opt/arm arm-rippers python3 - "$dev" <<'PY'
from datetime import datetime
import sys
import psutil
from arm.ui import app, db
from arm.models.job import JobState
from arm.models.system_drives import SystemDrives

dev = sys.argv[1]


def job_process_alive(job):
    """True only when THIS job's original ARM process is still alive."""
    if job is None or not getattr(job, "pid", None):
        return False
    try:
        proc = psutil.Process(int(job.pid))
        if not proc.is_running() or proc.status() == psutil.STATUS_ZOMBIE:
            return False
        saved_hash = getattr(job, "pid_hash", None)
        if saved_hash is not None and hash(proc) != int(saved_hash):
            # PID has been reused by a different process.
            return False
        cmdline = " ".join(proc.cmdline())
        if "arm/ripper/main.py" not in cmdline:
            return False
        return True
    except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied, ValueError, TypeError):
        return False


with app.app_context():
    drive = SystemDrives.query.filter_by(mount=dev).first()
    if drive is None:
        print(f"No ARM drive DB record for {dev}; nothing to reconcile")
        raise SystemExit(0)

    if drive.job_id_current is None:
        print(f"{dev}: no current ARM job")
        raise SystemExit(0)

    job = drive.job_current
    jid = drive.job_id_current

    if job is None:
        print(f"{dev}: releasing dangling current job id {jid}")
    elif job.status in {JobState.SUCCESS.value, JobState.FAILURE.value}:
        print(f"{dev}: releasing already-finished job {jid} ({job.status})")
    elif job_process_alive(job):
        print(
            f"{dev}: ARM job {jid} is genuinely alive "
            f"(pid={job.pid}, status={job.status}); refusing same-drive reconciliation",
            file=sys.stderr,
        )
        raise SystemExit(75)
    else:
        old = job.status
        job.status = JobState.FAILURE.value
        job.stop_time = datetime.now()
        marker = (
            "PCGA stale-job reconciliation: this drive had a current DB job "
            "but that job's recorded ARM process is no longer alive."
        )
        prior = str(job.errors or "").strip()
        job.errors = (prior + "\n" + marker).strip()
        print(f"{dev}: marked stale job {jid} {old!r} -> {job.status!r}")

    drive.release_current_job()
    db.session.commit()
    print(f"{dev}: current={drive.job_id_current!r} previous={drive.job_id_previous!r}")
PY
ARM_RECONCILE
chmod 0755 /usr/local/sbin/pcga-arm-reconcile

cat > /usr/local/sbin/pcga-makemkv-sdf-sync <<'MAKEMKV_SDF_SYNC'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"
[[ -n "$name" ]] || { echo "Usage: pcga-makemkv-sdf-sync srN [SDF_ID]" >&2; exit 64; }
dev="/dev/$name"
explicit="${2:-}"
ROOT_FILE=/etc/pc-game-archive/archive-root
[[ -r "$ROOT_FILE" ]] || { echo "missing $ROOT_FILE" >&2; exit 1; }
ROOT="$(cat "$ROOT_FILE")"
SETTINGS="$ROOT/media/arm/home/.MakeMKV/settings.conf"
[[ -b "$dev" ]] || { echo "$dev is not a block device" >&2; exit 1; }
[[ "$(docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null || true)" == true ]] || {
  echo "ARM container is not running" >&2; exit 75;
}

serial="$(udevadm info --query=property --name="$dev" 2>/dev/null | sed -n 's/^ID_SERIAL_SHORT=//p' | head -n1)"
model="$(udevadm info --query=property --name="$dev" 2>/dev/null | sed -n 's/^ID_MODEL=//p' | head -n1)"

ident="$explicit"
if [[ -z "$ident" ]]; then
  ident="$(docker exec --user arm arm-rippers python3 - "$serial" "$model" <<'PY'
from pathlib import Path
import re, sys
serial=(sys.argv[1] or '').strip()
model=(sys.argv[2] or '').strip().replace(' ','_')
p=Path('/home/arm/MakeMKV_log.txt')
try:
    lines=p.read_text(errors='replace').splitlines()
except OSError:
    lines=[]
rx=re.compile(r'(?:No\s+)?SDF(?:\s+(?:auto|id))?\s+v[^:]*:\s*(\S+)\s*$', re.I)
candidates=[]
for line in lines:
    m=rx.search(line.strip())
    if m:
        candidates.append(m.group(1))
if serial:
    hits=[x for x in candidates if serial in x]
    if hits:
        print(hits[-1]); raise SystemExit(0)
if model:
    hits=[x for x in candidates if model.lower() in x.lower()]
    if len(set(hits)) == 1:
        print(hits[-1]); raise SystemExit(0)
raise SystemExit(1)
PY
  )" || true
fi

if [[ -z "$ident" ]]; then
  echo "No unambiguous MakeMKV SDF identifier found for $dev" >&2
  exit 69
fi

install -d -m 0755 "$(dirname "$SETTINGS")"
touch "$SETTINGS"
python3 - "$SETTINGS" "$ident" <<'PY'
from pathlib import Path
import re, shutil, sys, time
p=Path(sys.argv[1]); ident=sys.argv[2].strip()
s=p.read_text(errors='replace') if p.exists() else ''
pat=re.compile(r'(?m)^\s*sdf_Stop\s*=\s*"([^"]*)"\s*$')
m=pat.search(s)
existing=m.group(1).split() if m else []
merged=[]
for x in existing+[ident]:
    if x and x not in merged:
        merged.append(x)
line='sdf_Stop = "'+' '.join(merged)+'"'
if m and m.group(0).strip()==line:
    print(line)
    raise SystemExit(0)
if p.exists() and p.stat().st_size:
    backup=p.with_name(p.name+'.pre-pcga-sdf.'+time.strftime('%Y%m%d-%H%M%S'))
    shutil.copy2(p, backup)
if m:
    s=s[:m.start()]+line+s[m.end():]
else:
    s=(s.rstrip()+"\n" if s.strip() else '')+line+"\n"
p.write_text(s)
print(line)
PY
owner="$(stat -c '%u:%g' "$ROOT/media/arm/home" 2>/dev/null || true)"
[[ -n "$owner" ]] && chown "$owner" "$SETTINGS" || true
chmod 0600 "$SETTINGS" 2>/dev/null || true
echo "PCGA_SDF_ID=$ident"
MAKEMKV_SDF_SYNC
chmod 0755 /usr/local/sbin/pcga-makemkv-sdf-sync

cat > /usr/local/sbin/pcga-makemkv-preflight <<'MAKEMKV_PREFLIGHT'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"
[[ -n "$name" ]] || { echo "Usage: pcga-makemkv-preflight srN" >&2; exit 64; }
dev="/dev/$name"
ROOT_FILE=/etc/pc-game-archive/archive-root
[[ -r "$ROOT_FILE" ]] || { echo "missing $ROOT_FILE" >&2; exit 1; }
ROOT="$(cat "$ROOT_FILE")"
SETTINGS="$ROOT/media/arm/home/.MakeMKV/settings.conf"
STATE_DIR=/var/lib/pc-game-archive/makemkv-preflight
STATE="$STATE_DIR/$name.state"
mkdir -p "$STATE_DIR"
[[ -b "$dev" ]] || { echo "$dev is not a block device" >&2; exit 1; }
[[ "$(docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null || true)" == true ]] || { echo "ARM container is not running" >&2; exit 75; }

image="$(docker inspect -f '{{.Image}}' arm-rippers 2>/dev/null || true)"
udev_sig="$(udevadm info --query=property --name="$dev" 2>/dev/null | grep -E '^(ID_VENDOR|ID_MODEL|ID_REVISION|ID_SERIAL|ID_SERIAL_SHORT)=' | sort || true)"
signature="$(printf '%s\n%s\n' "$image" "$udev_sig" | sha256sum | awk '{print $1}')"
if [[ -r "$STATE" ]] && grep -qx 'format=2' "$STATE" 2>/dev/null; then
  old_sig="$(awk -F= '$1=="signature"{print $2}' "$STATE" | tail -n1)"
  old_id="$(sed -n 's/^sdf_id=//p' "$STATE" | tail -n1)"
  if [[ "$old_sig" == "$signature" ]]; then
    if [[ -z "$old_id" ]] || python3 - "$SETTINGS" "$old_id" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1]); ident=sys.argv[2]
s=p.read_text(errors='replace') if p.exists() else ''
m=re.search(r'(?m)^\s*sdf_Stop\s*=\s*"([^"]*)"\s*$',s)
raise SystemExit(0 if m and ident in m.group(1).split() else 1)
PY
    then
      echo "MakeMKV preflight already passed for $dev with this drive/container image"
      exit 0
    fi
  fi
fi

probe() {
  local out="$1"
  set +e
  docker exec -i --user arm --workdir /home/arm arm-rippers python3 - "$dev" >"$out" 2>&1 <<'PY'
import subprocess,sys
cmd=[
    'makemkvcon','--debug=-stdout','--robot','--messages=-stdout','--progress=-stdout',
    '--cache=1','--minlength=120','info',f'dev:{sys.argv[1]}'
]
try:
    p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=150)
    print(p.stdout or '',end='')
    raise SystemExit(p.returncode)
except subprocess.TimeoutExpired as exc:
    out=exc.stdout or ''
    if isinstance(out,bytes): out=out.decode(errors='replace')
    print(out,end='')
    print('\nPCGA_PREFLIGHT_TIMEOUT')
    raise SystemExit(124)
PY
  local rc=$?
  set -e
  return "$rc"
}

tmp="$(mktemp)"
trap 'rm -f "$tmp" "${tmp}.retry"' EXIT
set +e
probe "$tmp"; rc=$?
set -e
if [[ $rc -eq 0 ]]; then
  printf 'format=2\nsignature=%s\nsdf_id=\n' "$signature" > "$STATE"
  echo "MakeMKV info preflight passed for $dev"
  exit 0
fi
if [[ $rc -ne 124 ]]; then
  echo "WARNING: MakeMKV preflight returned exit $rc; ARM will perform its normal disc handling." >&2
  tail -n 30 "$tmp" >&2 || true
  exit 0
fi

echo "MakeMKV device scan timed out for $dev; attempting multi-drive-safe SDF suppression" >&2
set +e
sdf_line="$(/usr/local/sbin/pcga-makemkv-sdf-sync "$name" 2>&1)"; sync_rc=$?
set -e
if [[ $sync_rc -ne 0 ]]; then
  echo "$sdf_line" >&2
  echo "Could not derive an SDF identifier for $dev; refusing an unattended rip that may hang indefinitely." >&2
  exit 70
fi
echo "$sdf_line"
sdf_id="$(printf '%s\n' "$sdf_line" | sed -n 's/^PCGA_SDF_ID=//p' | tail -n1)"
[[ -n "$sdf_id" ]] || { echo "SDF sync succeeded but did not report a target identifier" >&2; exit 70; }

echo "Retesting MakeMKV after SDF update"
set +e
probe "${tmp}.retry"; rc=$?
set -e
if [[ $rc -eq 0 ]]; then
  printf 'format=2\nsignature=%s\nsdf_id=%s\n' "$signature" "$sdf_id" > "$STATE"
  echo "MakeMKV preflight passed after SDF suppression"
  exit 0
fi
echo "MakeMKV still failed preflight after SDF suppression (exit $rc)." >&2
tail -n 50 "${tmp}.retry" >&2 || true
exit 70
MAKEMKV_PREFLIGHT
chmod 0755 /usr/local/sbin/pcga-makemkv-preflight

cat > /usr/local/sbin/pcga-raw-recover <<'RAW_RECOVER'
#!/usr/bin/env python3
"""Recover a successful MakeMKV raw rip after ARM aborts downstream.

The tool deliberately does not move/delete ARM staging. It probes raw MKVs with
ffprobe inside the ARM container and hard-links a selected candidate into the
metadata-pending queue for the normal classifier/manual-review workflow.
"""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
from datetime import datetime, timezone

CONTAINER_RAW = "/home/arm/media/raw"
CONTAINER = "arm-rippers"
MIN_SAFE_SECONDS = 120.0


def die(msg: str, code: int = 1) -> None:
    print(f"pcga-raw-recover: ERROR: {msg}", file=sys.stderr)
    raise SystemExit(code)


def archive_root() -> Path:
    override = os.environ.get("PCGA_ROOT_OVERRIDE")
    if override:
        return Path(override)
    root_file = Path("/etc/pc-game-archive/archive-root")
    try:
        return Path(root_file.read_text().strip())
    except OSError as exc:
        die(f"cannot read {root_file}: {exc}")


def arm_is_active() -> bool:
    if os.environ.get("PCGA_IGNORE_ARM_BUSY") == "1":
        return False
    try:
        p = subprocess.run(
            ["systemctl", "list-units", "--all", "--state=active,activating", "--plain", "--no-legend", "pcga-arm-rip@*.service"],
            text=True, capture_output=True, check=False,
        )
        if "pcga-arm-rip@" in p.stdout:
            return True
    except OSError:
        pass
    try:
        p = subprocess.run(
            ["docker", "exec", CONTAINER, "sh", "-lc", "ps -eo args | grep -Eq '[p]ython3 /opt/arm/arm/ripper/main.py|[m]akemkvcon|[H]andBrakeCLI'"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
        )
        return p.returncode == 0
    except OSError:
        return False


def scan_raw(disc_filter: str | None = None) -> list[dict]:
    script = r'''
import glob, json, os, subprocess
for f in glob.glob("/home/arm/media/raw/**/*.mkv", recursive=True):
    p = subprocess.run([
        "ffprobe", "-v", "error",
        "-show_entries", "format=duration,size:stream=codec_type,codec_name,channels:stream_tags=language",
        "-of", "json", f
    ], capture_output=True, text=True)
    if p.returncode != 0:
        print(json.dumps({"path": f, "error": (p.stderr or "ffprobe failed").strip()}))
        continue
    try:
        d = json.loads(p.stdout)
        fmt = d.get("format", {})
        streams = d.get("streams", [])
        audios = [s for s in streams if s.get("codec_type") == "audio"]
        videos = [s for s in streams if s.get("codec_type") == "video"]
        audio_desc = []
        for a in audios:
            tags = a.get("tags") or {}
            audio_desc.append({
                "language": tags.get("language", "?"),
                "codec": a.get("codec_name", "?"),
                "channels": a.get("channels"),
            })
        print(json.dumps({
            "path": f,
            "duration": float(fmt.get("duration", 0) or 0),
            "size": int(fmt.get("size", 0) or 0),
            "audio_count": len(audios),
            "video_count": len(videos),
            "audio": audio_desc,
        }))
    except Exception as exc:
        print(json.dumps({"path": f, "error": str(exc)}))
'''
    try:
        p = subprocess.run(
            ["docker", "exec", "-i", "--user", "arm", "--workdir", "/home/arm", CONTAINER, "python3", "-c", script],
            text=True, capture_output=True, check=False,
        )
    except FileNotFoundError:
        die("docker is not installed")
    if p.returncode != 0:
        die(f"could not probe ARM raw staging: {(p.stderr or p.stdout).strip()}")

    root = archive_root()
    host_raw = root / "media" / "arm" / "work" / "raw"
    rows: list[dict] = []
    for line in p.stdout.splitlines():
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        cpath = row.get("path", "")
        prefix = CONTAINER_RAW + "/"
        if not cpath.startswith(prefix):
            continue
        rel = cpath[len(prefix):]
        if disc_filter and disc_filter.lower() not in rel.lower():
            continue
        row["relative"] = rel
        row["host_path"] = str(host_raw / rel)
        rows.append(row)
    rows.sort(key=lambda x: (float(x.get("duration", 0) or 0), int(x.get("size", 0) or 0)), reverse=True)
    return rows


def hms(seconds: float) -> str:
    seconds = max(0, int(round(seconds)))
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    return f"{h:02d}:{m:02d}:{s:02d}"


def print_rows(rows: list[dict]) -> None:
    if not rows:
        print("No raw MKV files found.")
        return
    print(f"{'#':>3}  {'duration':>8}  {'GiB':>7}  {'V':>1}  {'A':>2}  {'safe':>4}  file")
    print("-" * 100)
    for i, row in enumerate(rows, 1):
        if row.get("error"):
            print(f"{i:3d}  {'ERROR':>8}  {'-':>7}  -  -   no   {row['relative']}  ({row['error']})")
            continue
        dur = float(row.get("duration", 0) or 0)
        size = int(row.get("size", 0) or 0)
        ac = int(row.get("audio_count", 0) or 0)
        vc = int(row.get("video_count", 0) or 0)
        safe = dur >= MIN_SAFE_SECONDS and ac > 0 and vc > 0
        print(f"{i:3d}  {hms(dur):>8}  {size/(1024**3):7.2f}  {vc:1d}  {ac:2d}  {'yes' if safe else 'no ':>4}  {row['relative']}")


def default_label(row: dict) -> str:
    rel = Path(row["relative"])
    first = rel.parts[0] if len(rel.parts) > 1 else rel.stem
    label = first.strip(" -_") or "Recovered media"
    return label


def queue_row(row: dict, label: str | None, force: bool) -> Path:
    if arm_is_active():
        die("ARM is actively ripping/transcoding; raw recovery refuses to modify queues until it finishes", 75)
    if row.get("error"):
        die(f"selected file could not be probed: {row['error']}")
    dur = float(row.get("duration", 0) or 0)
    ac = int(row.get("audio_count", 0) or 0)
    vc = int(row.get("video_count", 0) or 0)
    if not force and (dur < MIN_SAFE_SECONDS or ac < 1 or vc < 1):
        die(f"selected candidate is unsafe by default (duration={hms(dur)}, video={vc}, audio={ac}); use --force only after inspecting it")

    src = Path(row["host_path"])
    if not src.is_file():
        die(f"raw source disappeared: {src}")
    root = archive_root()
    label = (label or default_label(row)).strip() or "Recovered media"
    # Keep the queue label filesystem-safe without trying to infer a final Jellyfin title.
    label = label.replace("/", "-").replace("\x00", "")
    qdir = root / "media" / "metadata-pending" / label
    qdir.mkdir(parents=True, exist_ok=True)
    dest = qdir / src.name

    if dest.exists():
        try:
            if os.path.samefile(src, dest):
                print(f"Already queued: {dest}")
                return dest
        except OSError:
            pass
        die(f"destination already exists and is not the same file: {dest}")

    try:
        os.link(src, dest)
        method = "hard-link"
    except OSError:
        # Cross-filesystem archive layouts still work, but may consume extra space.
        shutil.copy2(src, dest)
        method = "copy"

    manifest = {
        "tool": "pcga-raw-recover",
        "version": "0.10.0",
        "queued_utc": datetime.now(timezone.utc).isoformat(),
        "method": method,
        "source": str(src),
        "destination": str(dest),
        "duration_seconds": dur,
        "size_bytes": int(row.get("size", 0) or 0),
        "video_streams": vc,
        "audio_streams": ac,
        "audio": row.get("audio", []),
    }
    (qdir / ".pcga-raw-recovery.json").write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Queued via {method}: {dest}")
    print(f"Duration {hms(dur)}, {int(row.get('size',0))/(1024**3):.2f} GiB, audio streams: {ac}")
    try:
        subprocess.run(["systemctl", "--no-block", "start", "pcga-metadata-classify.service"], check=False,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except OSError:
        pass
    return dest


def choose_interactive(rows: list[dict], label: str | None, force: bool) -> None:
    if not rows:
        die("no raw MKV files found")
    print_rows(rows)
    print()
    if not force:
        print(f"Candidates marked 'safe' have >= {int(MIN_SAFE_SECONDS)} seconds, video, and at least one audio stream.")
    raw = input("Select title number to queue (blank to cancel): ").strip()
    if not raw:
        print("Cancelled.")
        return
    try:
        idx = int(raw)
    except ValueError:
        die("selection must be a number")
    if idx < 1 or idx > len(rows):
        die("selection is out of range")
    chosen = rows[idx - 1]
    qlabel = label
    if qlabel is None:
        default = default_label(chosen)
        entered = input(f"Review label [{default}]: ").strip()
        qlabel = entered or default
    queue_row(chosen, qlabel, force)
    print("Next: game-archive classification-status  (local-first classification runs automatically)")


def main() -> None:
    ap = argparse.ArgumentParser(description="Inspect/recover MakeMKV raw output without modifying ARM staging")
    sub = ap.add_subparsers(dest="cmd", required=True)

    p_list = sub.add_parser("list", help="list raw MKVs with duration/audio metadata")
    p_list.add_argument("disc", nargs="?", help="optional case-insensitive path/disc filter")

    p_int = sub.add_parser("interactive", help="interactively select a raw MKV to queue for review")
    p_int.add_argument("disc", nargs="?", help="optional case-insensitive path/disc filter")
    p_int.add_argument("--label")
    p_int.add_argument("--force", action="store_true", help="allow short/no-audio candidates")

    p_q = sub.add_parser("queue", help="queue a numbered candidate from the current scan")
    p_q.add_argument("index", type=int)
    p_q.add_argument("--disc", help="optional case-insensitive path/disc filter")
    p_q.add_argument("--label")
    p_q.add_argument("--force", action="store_true", help="allow short/no-audio candidates")

    args = ap.parse_args()
    if args.cmd == "list":
        print_rows(scan_raw(args.disc))
        return
    if args.cmd == "interactive":
        choose_interactive(scan_raw(args.disc), args.label, args.force)
        return
    if args.cmd == "queue":
        rows = scan_raw(args.disc)
        if args.index < 1 or args.index > len(rows):
            die(f"index {args.index} is out of range; run list first")
        queue_row(rows[args.index - 1], args.label, args.force)
        return


if __name__ == "__main__":
    main()
