            try:
                d=json.loads(p.read_text())
                ids=d.get('game_set_ids') if isinstance(d.get('game_set_ids'),list) else [d.get('game_set_id')]
                if sid in ids and d.get('fingerprint')!=fp:sibling_discs.append(d)
            except Exception:pass
    if disc_no is None and sibling_discs:
        used={int(x['disc_number']) for x in sibling_discs if isinstance(x.get('disc_number'),int)};n=1
        while n in used:n+=1
        disc_no=n
    role=None
    for word,val in ROLE_WORDS.items():
        if re.search(r'(?i)\b'+re.escape(word)+r'\b',label):role=val;break
    if not role:role='installer' if any(x in names for x in ('setup.exe','install.exe')) else 'data'
    layout='multi-disc-game' if disc_no is not None or disc_count is not None or sibling_discs else 'single-game'
    content={'game_set_id':sid,'title':set_rec['title'],'source_path':'.','role':'included-game','confidence':1.0 if pinned_id else (0.98 if exact else 0.65),'status':'provisional','installer':detect_installer(files),'engines':engines}
    meta={'schema':2,'fingerprint':fp,'device':dev,'layout':layout,'collection_id':None,'collection_title':None,'game_set_id':sid,'game_set_ids':[sid],'contents':[content],'title':set_rec['title'],'series':set_rec.get('series'),'edition':set_rec.get('edition'),'disc_number':disc_no,'disc_count':disc_count,'disc_role':role,'volume_label':label,'filesystem_type':fs.get('type'),'content_guess':probe.get('content_guess'),'content_confidence':probe.get('content_confidence'),'installer':detect_installer(files),'engines':engines,'autorun':autorun,'root_entries':roots[:160],'source_file_count':len(files),'metadata_status':'provisional','metadata_sources':['filesystem','volume-label']+(['autorun'] if autorun else []),'match':{'method':'existing-disc-assignment' if pinned_id and set_rec else ('normalized-title-exact' if exact else 'new-provisional-set'),'confidence':1.0 if pinned_id and set_rec else (0.98 if exact else 0.65),'candidate_set_ids':[x.get('id') for x in exact[:5]]},'created_at':old_disc.get('created_at') or now,'updated_at':now}
    if old_disc.get('metadata_status')=='confirmed':
        for key in ('layout','collection_id','collection_title','game_set_id','game_set_ids','contents','disc_number','disc_count','disc_role','title'):
            if key in old_disc:meta[key]=old_disc[key]
