#!/usr/bin/env python3
from __future__ import annotations
import argparse, datetime as dt, json, os, re, uuid
from pathlib import Path

STATE=Path('/var/lib/pc-game-archive/game-intake')
SETS=STATE/'sets'; DISCS=STATE/'discs'; COLLECTIONS=STATE/'collections'


def load(p:Path):
    try:
        d=json.loads(p.read_text()); return d if isinstance(d,dict) else {}
    except Exception:return {}

def save(p:Path,d):
    p.parent.mkdir(parents=True,exist_ok=True)
    t=p.with_suffix(p.suffix+'.tmp'); t.write_text(json.dumps(d,indent=2,sort_keys=True)+'\n'); os.replace(t,p)

def all_json(path:Path):
    out=[]
    if path.exists():
        for p in sorted(path.glob('*.json')):
            d=load(p)
            if d:out.append(d)
    return out

def now(): return dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')
def norm(v): return ' '.join(re.sub(r'[^a-z0-9]+',' ',str(v or '').casefold()).split())

def set_snapshot(d:dict)->dict:
    return {'game_set_id':d.get('id'),'title':d.get('title'),'series':d.get('series'),'edition':d.get('edition')}

def migrate_disc(d:dict)->dict:
    if not d:return d
    if not isinstance(d.get('contents'),list):
        d['contents']=[]
        sid=str(d.get('game_set_id') or '')
        if sid:
            d['contents'].append({'game_set_id':sid,'title':d.get('title'),'source_path':'.','role':'included-game','confidence':1.0 if d.get('metadata_status')=='confirmed' else 0.9,'status':d.get('metadata_status','provisional')})
    ids=[]
    for item in d.get('contents') or []:
        sid=str((item or {}).get('game_set_id') or '')
        if sid and sid not in ids:ids.append(sid)
    d['game_set_ids']=ids
    if len(ids)==1 and not d.get('game_set_id'):d['game_set_id']=ids[0]
    if len(ids)>1:d['game_set_id']=None
    if not d.get('layout'):
        d['layout']='compilation' if len(ids)>1 else ('multi-disc-game' if d.get('disc_count') or d.get('disc_number') else 'single-game')
    return d

def sync_collection_members(collection_id:str, disc:dict):
    if not collection_id:return
    p=COLLECTIONS/f'{collection_id}.json'; c=load(p)
    if not c:return
    ids=list(c.get('game_set_ids') or [])
    for sid in disc.get('game_set_ids') or []:
        if sid and sid not in ids:ids.append(sid)
    c['game_set_ids']=ids;c['updated_at']=now();save(p,c)

def require_set(sid:str)->dict:
    d=load(SETS/f'{sid}.json')
    if not d:raise SystemExit('game set not found')
    return d

def main():
    ap=argparse.ArgumentParser(description='Manage PCGA pre-rip PC game, compilation and physical-disc metadata')
    sp=ap.add_subparsers(dest='cmd',required=True)
    sp.add_parser('list-sets'); sp.add_parser('list-discs'); sp.add_parser('list-collections')
    sh=sp.add_parser('show-set'); sh.add_argument('set_id')
    dh=sp.add_parser('show-disc'); dh.add_argument('fingerprint')
    ch=sp.add_parser('show-collection'); ch.add_argument('collection_id')

    cs=sp.add_parser('create-set'); cs.add_argument('--title',required=True)
    for x in ('sort-title','series','edition','publisher','developer','operating-system','language','region'):cs.add_argument('--'+x)
    cs.add_argument('--release-year',type=int);cs.add_argument('--confirm',action='store_true')

    cc=sp.add_parser('create-collection');cc.add_argument('--title',required=True)
    for x in ('sort-title','edition','publisher','developer','language','region'):cc.add_argument('--'+x)
    cc.add_argument('--release-year',type=int);cc.add_argument('--confirm',action='store_true')

    us=sp.add_parser('update-set'); us.add_argument('set_id')
    for x in ('title','sort-title','series','edition','publisher','developer','operating-system','language','region'):us.add_argument('--'+x)
    us.add_argument('--release-year',type=int); us.add_argument('--confirm',action='store_true')

    uc=sp.add_parser('update-collection');uc.add_argument('collection_id')
    for x in ('title','sort-title','edition','publisher','developer','language','region'):uc.add_argument('--'+x)
    uc.add_argument('--release-year',type=int);uc.add_argument('--confirm',action='store_true')

    ad=sp.add_parser('assign-disc'); ad.add_argument('fingerprint'); ad.add_argument('set_id'); ad.add_argument('--number',type=int); ad.add_argument('--count',type=int); ad.add_argument('--role'); ad.add_argument('--confirm',action='store_true');ad.add_argument('--replace-compilation',action='store_true')
    ac=sp.add_parser('assign-collection');ac.add_argument('fingerprint');ac.add_argument('collection_id');ac.add_argument('--number',type=int);ac.add_argument('--count',type=int);ac.add_argument('--confirm',action='store_true')
    sl=sp.add_parser('set-disc-layout');sl.add_argument('fingerprint');sl.add_argument('layout',choices=('single-game','multi-disc-game','compilation','unknown'));sl.add_argument('--confirm',action='store_true')
    ag=sp.add_parser('add-game-to-disc');ag.add_argument('fingerprint');ag.add_argument('set_id');ag.add_argument('--source-path',default='.');ag.add_argument('--role',default='included-game');ag.add_argument('--confirm',action='store_true')
    rg=sp.add_parser('remove-game-from-disc');rg.add_argument('fingerprint');rg.add_argument('set_id');rg.add_argument('--source-path')

    ns=ap.parse_args()
    if ns.cmd=='list-sets': print(json.dumps({'sets':all_json(SETS)},indent=2)); return
    if ns.cmd=='list-discs': print(json.dumps({'discs':[migrate_disc(x) for x in all_json(DISCS)]},indent=2)); return
    if ns.cmd=='list-collections': print(json.dumps({'collections':all_json(COLLECTIONS)},indent=2)); return
    if ns.cmd=='show-set':
        d=load(SETS/f'{ns.set_id}.json');
        if not d:raise SystemExit('game set not found')
        print(json.dumps(d,indent=2));return
    if ns.cmd=='show-disc':
        d=migrate_disc(load(DISCS/f'{ns.fingerprint}.json'))
        if not d:raise SystemExit('disc not found')
        print(json.dumps(d,indent=2));return
    if ns.cmd=='show-collection':
        d=load(COLLECTIONS/f'{ns.collection_id}.json')
        if not d:raise SystemExit('collection not found')
        print(json.dumps(d,indent=2));return

    if ns.cmd=='create-set':
        sid=str(uuid.uuid4());ts=now();title=ns.title.strip()
        d={'schema':1,'id':sid,'title':title,'sort_title':ns.sort_title or title,'normalized_title':norm(title),'series':ns.series,'release_year':ns.release_year,'edition':ns.edition,'publisher':ns.publisher,'developer':ns.developer,'platform':'PC','operating_system':ns.operating_system,'language':ns.language,'region':ns.region,'external_ids':{},'provisional':not ns.confirm,'user_confirmed':bool(ns.confirm),'created_at':ts,'updated_at':ts}
        save(SETS/f'{sid}.json',d);print(json.dumps(d,indent=2));return
    if ns.cmd=='create-collection':
        cid=str(uuid.uuid4());ts=now();title=ns.title.strip()
        d={'schema':1,'id':cid,'title':title,'sort_title':ns.sort_title or title,'normalized_title':norm(title),'release_year':ns.release_year,'edition':ns.edition,'publisher':ns.publisher,'developer':ns.developer,'language':ns.language,'region':ns.region,'external_ids':{},'game_set_ids':[],'provisional':not ns.confirm,'user_confirmed':bool(ns.confirm),'created_at':ts,'updated_at':ts}
        save(COLLECTIONS/f'{cid}.json',d);print(json.dumps(d,indent=2));return

    if ns.cmd=='update-set':
        p=SETS/f'{ns.set_id}.json'; d=load(p)
        if not d:raise SystemExit('game set not found')
        mapping={'title':'title','sort_title':'sort_title','series':'series','edition':'edition','publisher':'publisher','developer':'developer','operating_system':'operating_system','language':'language','region':'region','release_year':'release_year'}
        for attr,key in mapping.items():
            v=getattr(ns,attr,None)
            if v is not None:d[key]=v
        if ns.title is not None:d['normalized_title']=norm(ns.title)
        if ns.confirm:
            d['provisional']=False; d['user_confirmed']=True
        d['updated_at']=now();save(p,d);print(json.dumps(d,indent=2));return
    if ns.cmd=='update-collection':
        p=COLLECTIONS/f'{ns.collection_id}.json';d=load(p)
        if not d:raise SystemExit('collection not found')
        mapping={'title':'title','sort_title':'sort_title','edition':'edition','publisher':'publisher','developer':'developer','language':'language','region':'region','release_year':'release_year'}
        for attr,key in mapping.items():
            v=getattr(ns,attr,None)
            if v is not None:d[key]=v
        if ns.title is not None:d['normalized_title']=norm(ns.title)
        if ns.confirm:
            d['provisional']=False; d['user_confirmed']=True
        d['updated_at']=now();save(p,d);print(json.dumps(d,indent=2));return

    p=DISCS/f'{getattr(ns,"fingerprint","")}.json';d=migrate_disc(load(p))
    if not d:raise SystemExit('disc not found')

    if ns.cmd=='assign-disc':
        target=require_set(ns.set_id)
        if d.get('layout')=='compilation' and len(d.get('contents') or [])>1 and not ns.replace_compilation:
            raise SystemExit('disc is a compilation; use add-game-to-disc, or pass --replace-compilation to intentionally replace its memberships')
        d.update(set_snapshot(target));d['game_set_ids']=[ns.set_id]
        d['contents']=[{'game_set_id':ns.set_id,'title':target.get('title'),'source_path':'.','role':'included-game','confidence':1.0,'status':'confirmed' if ns.confirm else 'provisional'}]
        d['layout']='multi-disc-game' if (ns.count or ns.number or d.get('disc_count') or d.get('disc_number')) else 'single-game'
        over=dict(d.get('user_overrides') or {})
        if ns.number is not None:d['disc_number']=ns.number;over['disc_number']=ns.number
        if ns.count is not None:d['disc_count']=ns.count;over['disc_count']=ns.count
        if ns.role is not None:d['disc_role']=ns.role;over['disc_role']=ns.role
        over['layout']=d['layout'];over['game_set_ids']=[ns.set_id];d['user_overrides']=over
        d['collection_id']=None;d['match']={'method':'user-assigned','confidence':1.0,'candidate_set_ids':[ns.set_id]};d['updated_at']=now()
        if ns.confirm:d['metadata_status']='confirmed'
        save(p,d);print(json.dumps(d,indent=2));return

    if ns.cmd=='assign-collection':
        c=load(COLLECTIONS/f'{ns.collection_id}.json')
        if not c:raise SystemExit('collection not found')
        d['collection_id']=ns.collection_id;d['collection_title']=c.get('title');d['layout']='compilation'
        if ns.number is not None:d['disc_number']=ns.number
        if ns.count is not None:d['disc_count']=ns.count
        over=dict(d.get('user_overrides') or {});over['collection_id']=ns.collection_id;over['layout']='compilation';d['user_overrides']=over
        if ns.confirm:d['metadata_status']='confirmed'
        d['updated_at']=now();save(p,d);sync_collection_members(ns.collection_id,d);print(json.dumps(d,indent=2));return

    if ns.cmd=='set-disc-layout':
        d['layout']=ns.layout;over=dict(d.get('user_overrides') or {});over['layout']=ns.layout;d['user_overrides']=over
        if ns.confirm:d['metadata_status']='confirmed'
        d['updated_at']=now();save(p,d);print(json.dumps(d,indent=2));return

    if ns.cmd=='add-game-to-disc':
        target=require_set(ns.set_id);items=list(d.get('contents') or []);src=str(ns.source_path or '.').strip() or '.'
        found=None
        for item in items:
            if str(item.get('game_set_id') or '')==ns.set_id and str(item.get('source_path') or '.')==src:found=item;break
        if found is None:
            found={'game_set_id':ns.set_id,'title':target.get('title'),'source_path':src,'role':ns.role,'confidence':1.0,'status':'confirmed' if ns.confirm else 'provisional'};items.append(found)
        else:
            found.update({'title':target.get('title'),'role':ns.role,'confidence':1.0});
            if ns.confirm:found['status']='confirmed'
        d['contents']=items;d['layout']='compilation' if len({str(x.get('game_set_id') or '') for x in items if x.get('game_set_id')})>1 else d.get('layout','single-game')
        ids=[]
        for item in items:
            sid=str(item.get('game_set_id') or '')
            if sid and sid not in ids:ids.append(sid)
        d['game_set_ids']=ids;d['game_set_id']=ids[0] if len(ids)==1 else None
        if len(ids)>1:d['title']=d.get('collection_title') or d.get('volume_label') or 'PC Game Compilation'
        if ns.confirm:d['metadata_status']='confirmed'
        d['updated_at']=now();save(p,d);sync_collection_members(str(d.get('collection_id') or ''),d);print(json.dumps(d,indent=2));return

    if ns.cmd=='remove-game-from-disc':
        items=[]
        for item in d.get('contents') or []:
            same=str(item.get('game_set_id') or '')==ns.set_id
            if ns.source_path is not None:same=same and str(item.get('source_path') or '.')==ns.source_path
            if not same:items.append(item)
        d['contents']=items;ids=[]
        for item in items:
            sid=str(item.get('game_set_id') or '')
            if sid and sid not in ids:ids.append(sid)
        d['game_set_ids']=ids;d['game_set_id']=ids[0] if len(ids)==1 else None
        if len(ids)<=1 and d.get('layout')=='compilation' and not d.get('collection_id'):d['layout']='single-game'
        d['updated_at']=now();save(p,d);print(json.dumps(d,indent=2));return

if __name__=='__main__':main()
PCGA_GAME_INTAKE
chmod 0755 /usr/local/sbin/pcga-game-intake

cat > /usr/local/sbin/pcga-optical-dispatch <<'PCGA_OPTICAL_DISPATCH'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"; dev="/dev/$name"
allowed=/etc/pc-game-archive/media-drives
run_dir=/run/pcga-optical-dispatch
state_dir=/var/lib/pc-game-archive/optical-dispatch
mkdir -p "$run_dir" "$state_dir"
[[ -r "$allowed" ]] || exit 0
grep -Fxq "$dev" "$allowed" || exit 0
[[ -b "$dev" ]] || exit 0
exec 9>"$run_dir/${name}.lock"; flock -n 9 || exit 0
finger="$run_dir/${name}.fingerprint"
state="$state_dir/${name}.json"
if ! /usr/local/sbin/pcga-optical-media-present "$dev" >/dev/null 2>&1; then
  rm -f "$finger"
  printf '{"device":"%s","present":false,"updated_at":"%s"}\n' "$dev" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$state"
  exit 0
fi
auto_rip=true
if [[ -r /etc/pc-game-archive/appliance.json ]] && ! python3 - <<'PY_AUTORIP' >/dev/null 2>&1
import json
try:
    d=json.load(open('/etc/pc-game-archive/appliance.json'))
    raise SystemExit(0 if bool((d.get('ingest') or {}).get('auto_rip',True)) else 1)
except Exception:
    raise SystemExit(0)
PY_AUTORIP
then
  auto_rip=false
fi
# Identification is a core optical capability and remains active even when
# automatic ingest is disabled. The Control Center toggle gates only backend
# execution, not media classification/status reporting.
probe="$(mktemp)"; trap 'rm -f "$probe"' EXIT
if ! /usr/local/sbin/pcga-optical-identify "$dev" >"$probe"; then
  logger -t PCGA-OPTICAL "Could not identify inserted media in $dev"
  exit 75
fi
route="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("route","unsupported"))' "$probe")"
kind="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("kind","unknown"))' "$probe")"
fp="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("fingerprint",""))' "$probe")"
python3 - "$probe" "$state" "$auto_rip" <<'PY'
import json,sys,datetime
p=json.load(open(sys.argv[1]))
p['present']=True
p['auto_ingest_enabled']=(sys.argv[3]=='true')
p['dispatch_status']='identified' if p['auto_ingest_enabled'] else 'held-auto-ingest-disabled'
p['updated_at']=datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='seconds')
open(sys.argv[2],'w').write(json.dumps(p,indent=2,sort_keys=True)+'\n')
PY
# For PC/data media, collect a game/disc identity record before imaging begins.
# The record is keyed by the optical fingerprint, so metadata edits can happen
# while the rip is running and still follow the resulting preservation artifact.
if [[ "$route" == pc-data || "$route" == pc-mixed ]]; then
  meta_tmp="$(mktemp)"
  if /usr/local/sbin/pcga-game-disc-metadata --record --probe "$probe" "$dev" >"$meta_tmp" 2>/dev/null; then
    python3 - "$state" "$meta_tmp" <<'PY_META'
import json,sys
state=json.load(open(sys.argv[1])); meta=json.load(open(sys.argv[2]))
state['game_metadata']={k:meta.get(k) for k in ('layout','collection_id','collection_title','game_set_id','game_set_ids','title','series','edition','disc_number','disc_count','disc_role','metadata_status','match')}
state['game_metadata']['content_count']=len(meta.get('contents') or [])
state['game_metadata_file']=f"/var/lib/pc-game-archive/game-intake/discs/{meta.get('fingerprint','')}.json"
open(sys.argv[1],'w').write(json.dumps(state,indent=2,sort_keys=True)+'\n')
PY_META
  else
    logger -t PCGA-OPTICAL "Game metadata collection failed for $dev; preservation may continue with optical metadata only"
  fi
  rm -f "$meta_tmp"
fi
if [[ "$auto_rip" != true ]]; then
  logger -t PCGA-OPTICAL "Identified $kind in $dev as route=$route; automatic ingest is disabled, so no backend was started"
  exit 0
fi
if [[ -n "$fp" && -r "$finger" && "$(cat "$finger" 2>/dev/null)" == "$fp" ]]; then exit 0; fi
[[ -n "$fp" ]] && printf '%s\n' "$fp" > "$finger"
case "$route" in
  arm-video|arm-audio)
    logger -t PCGA-OPTICAL "Detected $kind in $dev; dispatching to ARM"
    systemctl --no-block start "pcga-arm-rip@${name}.service"
    ;;
  pc-data|pc-mixed)
    logger -t PCGA-OPTICAL "Detected $kind in $dev; dispatching to PC/data-disc preservation"
    systemctl --no-block start "pcga-pc-disc-rip@${name}.service"
    ;;
  *)
    logger -t PCGA-OPTICAL "Inserted media in $dev is $kind; no unattended backend selected"
    ;;
esac
PCGA_OPTICAL_DISPATCH
chmod 0755 /usr/local/sbin/pcga-optical-dispatch

cat > /usr/local/sbin/pcga-pc-disc-rip <<'PCGA_PC_DISC_RIP'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"; dev="/dev/$name"
allowed=/etc/pc-game-archive/media-drives
state="/var/lib/pc-game-archive/optical-dispatch/${name}.json"
[[ -r "$allowed" ]] || exit 0
grep -Fxq "$dev" "$allowed" || exit 0
[[ -b "$dev" ]] || exit 0
exec 9>"/run/pcga-optical-${name}.lock"; flock -n 9 || exit 0
for _ in $(seq 1 60); do /usr/local/sbin/pcga-optical-media-present "$dev" && break; sleep 1; done
/usr/local/sbin/pcga-optical-media-present "$dev" || exit 75
probe="$(mktemp)"; trap 'rm -f "$probe"; [[ -n "${mnt:-}" ]] && umount "$mnt" >/dev/null 2>&1 || true; [[ -n "${mnt:-}" ]] && rmdir "$mnt" >/dev/null 2>&1 || true' EXIT
/usr/local/sbin/pcga-optical-identify "$dev" > "$probe" || exit 75
route="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("route",""))' "$probe")"
[[ "$route" == pc-data || "$route" == pc-mixed ]] || { logger -t PCGA-PCDISC "Refusing $dev because dispatcher classified route=$route"; exit 0; }
/usr/local/sbin/pcga-optical-health --host-only --quiet "$dev" || exit 74
ROOT="$(cat /etc/pc-game-archive/archive-root)"; [[ -n "$ROOT" && "$ROOT" = /* ]] || exit 70
stamp="$(date +%Y%m%d-%H%M%S)"
label="$(python3 -c 'import json,sys; print((json.load(open(sys.argv[1])).get("filesystem") or {}).get("label") or "PC-Data-Disc")' "$probe")"
safe="$(printf '%s' "$label" | sed -E 's#[/\\]#-#g;s/[^[:alnum:]. _()+-]+/_/g;s/^ +| +$//g')"; [[ -n "$safe" ]] || safe="PC-Data-Disc"
work="$ROOT/ingest/optical-work/${stamp}-${name}-${safe}"; final="$ROOT/media/metadata-pending/${stamp}-${safe}"
mkdir -p "$work" "$(dirname "$final")"
cp "$probe" "$work/.pcga-optical.json"; printf '%s\n' 'optical-data-disc' > "$work/.pcga-source-hint"
fp="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("fingerprint",""))' "$probe")"
meta="/var/lib/pc-game-archive/game-intake/discs/${fp}.json"
[[ -n "$fp" && -r "$meta" ]] && cp "$meta" "$work/.pcga-game.json"
expected="$(blockdev --getsize64 "$dev" 2>/dev/null || echo 0)"
state_update(){
  local status="$1" operation="$2" out="${3:-}" final_path="${4:-}"
  python3 - "$state" "$status" "$operation" "$out" "$expected" "$work" "$final_path" <<'PY'
import datetime,json,os,sys
p=sys.argv[1]
try:d=json.load(open(p))
except Exception:d={}
status,op,out,expected,work,final=sys.argv[2:8]
try:expected=int(expected)
except:expected=0
size=0
if out:
    try:size=os.path.getsize(out)
    except OSError:pass
pct=None
if expected>0 and size>=0:pct=max(0.0,min(99.9 if status in {'ripping','retrying'} else 100.0,100.0*size/expected))
phase={
    'ripping':'pc-disc-imaging',
    'retrying':'pc-disc-imaging',
    'verifying':'pc-disc-verifying',
    'complete':'preserved',
    'failed':'failed',
}.get(status,'pc-disc-processing')
d.update({'present':True,'dispatch_status':status,'phase':phase,'operation':op,'expected_bytes':expected,'output_bytes':size,'progress_percent':pct,'work_path':work,'updated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='seconds')})
if final:d['final_path']=final
if status=='ripping' and not d.get('started_at'):d['started_at']=d['updated_at']
if status=='complete':
    d['completed_at']=d['updated_at'];d['preserved_at']=d['updated_at'];d['progress_percent']=100.0
open(p,'w').write(json.dumps(d,indent=2,sort_keys=True)+'\n')
PY
}
run_monitored(){
  local output="$1" operation="$2"; shift 2
  "$@" & local pid=$!
  while kill -0 "$pid" 2>/dev/null; do state_update ripping "$operation" "$output"; sleep 2; done
  wait "$pid"
}
state_update ripping "Preparing PC/data-disc preservation"
if [[ "$route" == pc-mixed ]]; then
  command -v cdrdao >/dev/null 2>&1 || { logger -t PCGA-PCDISC 'cdrdao missing'; exit 75; }
  logger -t PCGA-PCDISC "Preserving mixed-mode PC/data CD from $dev as raw BIN/TOC"
  run_monitored "$work/disc.bin" "Reading mixed-mode disc as BIN/TOC" cdrdao read-cd --read-raw --device "$dev" --datafile "$work/disc.bin" "$work/disc.toc"
  command -v toc2cue >/dev/null 2>&1 && toc2cue "$work/disc.toc" "$work/disc.cue" >/dev/null 2>&1 || true
else
  command -v ddrescue >/dev/null 2>&1 || { logger -t PCGA-PCDISC 'GNU ddrescue missing'; exit 75; }
  bytes="$expected"; free="$(df -B1 --output=avail "$ROOT/ingest/optical-work" | tail -n1 | tr -d '[:space:]')"; reserve=$((2*1024*1024*1024))
  if [[ "$bytes" =~ ^[0-9]+$ && "$free" =~ ^[0-9]+$ && $bytes -gt 0 && $free -lt $((bytes+reserve)) ]]; then logger -t PCGA-PCDISC "Insufficient free space for $dev"; exit 73; fi
  logger -t PCGA-PCDISC "Preserving data disc from $dev as lossless ISO image"
  set +e
  run_monitored "$work/disc.iso" "Creating lossless ISO image" ddrescue -b 2048 -f -n "$dev" "$work/disc.iso" "$work/disc.map"; first_rc=$?
  state_update retrying "Retrying unreadable sectors" "$work/disc.iso"
  run_monitored "$work/disc.iso" "Retrying unreadable sectors" ddrescue -b 2048 -f -r2 "$dev" "$work/disc.iso" "$work/disc.map"; retry_rc=$?
  set -e
  if [[ $retry_rc -ne 0 ]]; then
    state_update failed "Disc imaging ended with unreadable sectors" "$work/disc.iso"
    logger -t PCGA-PCDISC "ddrescue could not complete $dev after retries (first=$first_rc final=$retry_rc); partial image retained in $work"
    exit 74
  fi
fi
state_update verifying "Verifying preservation checksums" "${work}/disc.iso"
(
  cd "$work"
  find . -maxdepth 1 -type f ! -name SHA256SUMS ! -name '*.map' -print0 | sort -z | xargs -0 -r sha256sum > SHA256SUMS
)
# Preserve a bounded directory index for classification/diagnostics without duplicating the disc payload.
mnt="$(mktemp -d /run/pcga-pcdisc-mount.XXXXXX)"
if mount -o ro,nosuid,nodev,noexec "$dev" "$mnt" 2>/dev/null; then
  python3 - "$mnt" "$work/.pcga-file-index.json" <<'PY'
import json,os,sys
from pathlib import Path
root=Path(sys.argv[1]); rows=[]
for base,dirs,files in os.walk(root):
    p=Path(base)
    try: depth=len(p.relative_to(root).parts)
    except ValueError: continue
    if depth>=4: dirs[:]=[]
    for name in files:
        q=p/name
        try: rows.append({'path':q.relative_to(root).as_posix(),'size':q.stat().st_size})
        except OSError: pass
        if len(rows)>=2000: break
    if len(rows)>=2000: break
Path(sys.argv[2]).write_text(json.dumps({'schema':1,'files':rows},indent=2)+'\n')
PY
  umount "$mnt" || true; rmdir "$mnt" || true; mnt=""
fi
# Re-copy the fingerprint-keyed record at commit time so any metadata correction
# made while the image was being read follows the preservation artifact.
[[ -n "$fp" && -r "$meta" ]] && cp "$meta" "$work/.pcga-game.json"
n=0; dest="$final"; while [[ -e "$dest" ]]; do n=$((n+1)); dest="${final}-${n}"; done
mv "$work" "$dest"
state_update complete "PC/data disc preserved and queued for classification" "" "$dest"
logger -t PCGA-PCDISC "PC/data disc preserved from $dev -> $dest; queued for classification"
systemctl --no-block start pcga-metadata-classify.service >/dev/null 2>&1 || true
PCGA_PC_DISC_RIP
chmod 0755 /usr/local/sbin/pcga-pc-disc-rip

cat > /usr/local/sbin/pcga-optical-watch <<'PCGA_OPTICAL_WATCH'
#!/usr/bin/env bash
set -Eeuo pipefail
ALLOWED=/etc/pc-game-archive/media-drives
STATE_DIR=/run/pcga-optical-watch
DISPATCH_DIR=/run/pcga-optical-dispatch
mkdir -p "$STATE_DIR" "$DISPATCH_DIR"
# A service restart (including re-enabling Auto ingest) must re-evaluate media
# already sitting in a drive. The dispatcher fingerprint still prevents a
# duplicate backend launch for a job that was already dispatched.
rm -f "$STATE_DIR"/*.present 2>/dev/null || true
retry_target() {
  local name="$1" route target active status retry now last
  route="$(python3 - "/var/lib/pc-game-archive/optical-dispatch/${name}.json" <<'PY' 2>/dev/null || true
import json,sys
try: print(json.load(open(sys.argv[1])).get('route',''))
except Exception: pass
PY
)"
  case "$route" in arm-video|arm-audio) target="pcga-arm-rip@${name}.service";; pc-data|pc-mixed) target="pcga-pc-disc-rip@${name}.service";; *) return 1;; esac
  active="$(systemctl show "$target" -p ActiveState --value 2>/dev/null || true)"; [[ "$active" == failed ]] || return 1
  status="$(systemctl show "$target" -p ExecMainStatus --value 2>/dev/null || true)"; [[ "$status" == 75 ]] || return 1
  retry="$STATE_DIR/${name}.retry"; now="$(date +%s)"; last=0; [[ -r "$retry" ]] && read -r last < "$retry" || true; [[ "$last" =~ ^[0-9]+$ ]] || last=0
  (( now-last >= 30 )) || return 0
  printf '%s\n' "$now" > "$retry"; rm -f "$DISPATCH_DIR/${name}.fingerprint"
  systemctl reset-failed "$target" >/dev/null 2>&1 || true
  logger -t PCGA-OPTICAL "Retrying temporary optical ingest failure for /dev/$name"
  systemctl --no-block start "pcga-optical-dispatch@${name}.service" >/dev/null 2>&1 || true
}
while sleep 3; do
  [[ -r "$ALLOWED" ]] || continue
  while IFS= read -r dev; do
    [[ -b "$dev" ]] || continue
    name="${dev#/dev/}"; state="$STATE_DIR/${name}.present"
    if /usr/local/sbin/pcga-optical-media-present "$dev"; then
      if [[ ! -e "$state" ]]; then
        : > "$state"; rm -f "$STATE_DIR/${name}.retry"
        logger -t PCGA-OPTICAL "Detected readable media in $dev; requesting classification/dispatch"
        systemctl --no-block start "pcga-optical-dispatch@${name}.service" >/dev/null 2>&1 || true
      else retry_target "$name" || true; fi
    else
      if [[ -e "$state" ]]; then logger -t PCGA-OPTICAL "Detected media removal from $dev"; fi
      rm -f "$state" "$STATE_DIR/${name}.retry" "$DISPATCH_DIR/${name}.fingerprint"
      systemctl --no-block start "pcga-optical-dispatch@${name}.service" >/dev/null 2>&1 || true
    fi
  done < "$ALLOWED"
done
PCGA_OPTICAL_WATCH
chmod 0755 /usr/local/sbin/pcga-optical-watch

cat > /usr/local/sbin/pcga-arm-rip <<'ARM_TRIGGER'
#!/usr/bin/env bash
set -Eeuo pipefail
name="${1#/dev/}"
dev="/dev/$name"
allowed=/etc/pc-game-archive/media-drives
[[ -r "$allowed" ]] || exit 0
grep -Fxq "$dev" "$allowed" || exit 0
[[ -b "$dev" ]] || exit 0

exec 9>"/run/pcga-optical-${name}.lock"
flock -n 9 || exit 0

stopping=0
cleanup_on_signal() {
  local sig="$1"
  [[ $stopping -eq 0 ]] || exit 143
  stopping=1
  logger -t PCGA-ARM "Received $sig while ingesting $dev; terminating only this drive's ARM process tree"
  /usr/local/sbin/pcga-arm-stop "$name" || true
  exit 143
}
trap 'cleanup_on_signal TERM' TERM
trap 'cleanup_on_signal INT' INT

ready=0
for _ in $(seq 1 60); do
  if /usr/local/sbin/pcga-optical-media-present "$dev"; then ready=1; break; fi
  sleep 1
done
if [[ $ready -ne 1 ]]; then logger -t PCGA-ARM "Disc in $dev never became ready; not starting ARM"; exit 0; fi
route="$(/usr/local/sbin/pcga-optical-identify --field route "$dev" 2>/dev/null || true)"
case "$route" in
  arm-video|arm-audio) ;;
  *) logger -t PCGA-ARM "Refusing $dev because optical dispatcher classified route=${route:-unknown}; ARM only accepts video/audio media"; exit 0 ;;
esac
if [[ "$(docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null || true)" != true ]]; then
  logger -t PCGA-ARM "ARM container is not running; ignoring $dev"; exit 0
fi
if ! /usr/local/sbin/pcga-optical-health --quiet "$dev"; then
  logger -t PCGA-ARM "Optical hardware preflight failed for $dev; refusing ingest"; exit 74
fi
set +e
/usr/local/sbin/pcga-arm-reconcile "$name"; rc=$?
set -e
if [[ $rc -ne 0 ]]; then
  logger -t PCGA-ARM "ARM stale-job reconciliation refused/failed for $dev (exit $rc); not starting a competing ingest"; exit "$rc"
fi
set +e
/usr/local/sbin/pcga-makemkv-preflight "$name"; rc=$?
set -e
if [[ $rc -ne 0 ]]; then logger -t PCGA-ARM "MakeMKV preflight failed for $dev (exit $rc); refusing an unattended rip that may hang"; exit "$rc"; fi
ROOT="$(cat /etc/pc-game-archive/archive-root 2>/dev/null || true)"
disc_bytes="$(blockdev --getsize64 "$dev" 2>/dev/null || printf '0')"
free_bytes="$(df -B1 --output=avail "$ROOT/media/arm/work/raw" 2>/dev/null | tail -n1 | tr -d '[:space:]' || printf '0')"
reserve=$((5 * 1024 * 1024 * 1024))
if [[ "$disc_bytes" =~ ^[0-9]+$ && "$free_bytes" =~ ^[0-9]+$ && $disc_bytes -gt 0 && $free_bytes -lt $((disc_bytes + reserve)) ]]; then
  logger -t PCGA-ARM "Insufficient free space for $dev: disc=${disc_bytes}B free=${free_bytes}B reserve=${reserve}B"; exit 73
fi
logger -t PCGA-ARM "Starting automatic ARM ingest for $dev (original MakeMKV output; transcoding disabled)"
set +e
docker exec --user arm --workdir /home/arm arm-rippers python3 /opt/arm/arm/ripper/main.py -d "$name"
rc=$?
set -e
# Always kick the post-rip sorter. On a successful ARM handoff it consumes
# completed staging; on a failed final move it can recover retained raw MKVs
# once they satisfy the settle window.
systemctl --no-block start pcga-media-sort.service >/dev/null 2>&1 || true
if [[ $rc -ne 0 ]]; then
  logger -t PCGA-ARM "ARM ingest failed for $dev (exit $rc); raw MakeMKV output is retained and PCGA recovery will inspect it automatically. Manual inspection: game-archive raw-review"
  exit "$rc"
fi
logger -t PCGA-ARM "ARM ingest process completed for $dev; PCGA classification/promotion has been triggered"
# Apply any ingest-setting change that was deferred while this rip was active.
# pcga-arm-configure --ensure is idempotent and does not rewrite an already
# aligned arm.yaml. Never mutate ARM configuration immediately before a rip.
PCGA_CONFIG_DURING_TRIGGER=1 /usr/local/sbin/pcga-arm-configure --ensure >/dev/null 2>&1 || logger -t PCGA-ARM "WARNING: deferred ARM ingest settings could not be reconciled"
ARM_TRIGGER
chmod 0755 /usr/local/sbin/pcga-arm-rip

