cat > /usr/local/sbin/pcga-media-audit <<'MEDIA_AUDIT'
#!/usr/bin/env bash
set -Eeuo pipefail
IFS=$'\n\t'
ROOT_FILE=/etc/pc-game-archive/archive-root
[[ -r "$ROOT_FILE" ]] || { echo "missing $ROOT_FILE" >&2; exit 1; }
ROOT="$(cat "$ROOT_FILE")"
CFG="$ROOT/media/arm/config/arm.yaml"
ABC="$ROOT/media/arm/config/abcde.conf"
LIB="$ROOT/media/library"
STAGE="$ROOT/media/arm/work/completed"
MUSIC_STAGE="$ROOT/media/arm/music"
QUAR="$ROOT/media/quarantine"
warns=0
warn(){ printf 'WARNING: %s\n' "$*"; ((warns+=1)); }
ok(){ printf 'OK: %s\n' "$*"; }

echo '== ARM output configuration =='
echo 'Video metadata architecture: asynchronous; ARM rip path does not call OMDb/TMDb.'
if [[ -r "$CFG" ]]; then
  grep -E '^(ARM_CHECK_UDF|GET_VIDEO_TITLE|VIDEOTYPE|METADATA_PROVIDER|GET_AUDIO_TITLE|SKIP_TRANSCODE|DELRAWFILES|MAINFEATURE|MINLENGTH|PREVENT_99|EXTRAS_SUB|RAW_PATH|TRANSCODE_PATH|COMPLETED_PATH):' "$CFG" || true
  sync_provider="$(awk -F': *' '$1=="METADATA_PROVIDER"{gsub(/["[:space:]]/,"",$2);print tolower($2); exit}' "$CFG")"
  [[ "$sync_provider" == "none" ]] && ok 'ARM synchronous video metadata is disabled' || warn "ARM synchronous METADATA_PROVIDER is '$sync_provider' (expected none)"
  skip_transcode="$(awk -F': *' '$1=="SKIP_TRANSCODE"{gsub(/["[:space:]]/,"",$2);print tolower($2); exit}' "$CFG")"
  get_video_title="$(awk -F': *' '$1=="GET_VIDEO_TITLE"{gsub(/["[:space:]]/,"",$2);print tolower($2); exit}' "$CFG")"
  delraw="$(awk -F': *' '$1=="DELRAWFILES"{gsub(/["[:space:]]/,"",$2);print tolower($2); exit}' "$CFG")"
  minlength="$(awk -F': *' '$1=="MINLENGTH"{gsub(/["[:space:]]/,"",$2);print $2; exit}' "$CFG")"
  prevent99="$(awk -F': *' '$1=="PREVENT_99"{gsub(/["[:space:]]/,"",$2);print tolower($2); exit}' "$CFG")"
  [[ "$skip_transcode" == "true" ]] && ok 'ARM preserves original MakeMKV quality (SKIP_TRANSCODE=true)' || warn "SKIP_TRANSCODE is '$skip_transcode' (expected true)"
  [[ "$get_video_title" == "false" ]] && ok 'ARM synchronous video-title lookup is disabled' || warn "GET_VIDEO_TITLE is '$get_video_title' (expected false)"
  [[ "$delraw" == "false" ]] && ok 'ARM raw deletion is disabled until PCGA confirms handoff' || warn "DELRAWFILES is '$delraw' (expected false)"
  [[ "$minlength" == "120" ]] && ok 'ARM minimum title length is 120 seconds' || warn "MINLENGTH is '$minlength' (expected 120)"
  [[ "$prevent99" == "true" ]] && ok 'DVD track-99 protection guard is enabled' || warn "PREVENT_99 is '$prevent99' (expected true)"
  provider="$(cat /etc/pc-game-archive/arm-metadata-provider 2>/dev/null | tr -d '\r\n[:space:]' | tr '[:upper:]' '[:lower:]')"
  provider="${provider:-omdb}"
  case "$provider" in
    omdb) [[ -s /etc/pc-game-archive/arm-omdb-key ]] && ok 'Async OMDb key is configured' || warn 'Async OMDb key is missing; pending video will wait for metadata' ;;
    tmdb) [[ -s /etc/pc-game-archive/arm-tmdb-key ]] && ok 'Async TMDb key is configured' || warn 'Async TMDb key is missing; pending video will wait for metadata' ;;
    *) warn "Unknown asynchronous metadata provider: $provider" ;;
  esac
else
  warn "ARM config missing: $CFG"
fi

echo
echo '== Audio-CD output configuration =='
if [[ -r "$ABC" ]]; then
  grep -E '^(OUTPUTDIR|OUTPUTFORMAT|VAOUTPUTFORMAT)=' "$ABC" || true
  outdir="$(awk -F= '$1=="OUTPUTDIR" {gsub(/[\"\047[:space:]]/,"",$2); print $2; exit}' "$ABC")"
  [[ "${outdir%/}" == "/home/arm/music" ]] && ok 'abcde output points to /home/arm/music' || warn 'abcde OUTPUTDIR is not /home/arm/music'
else
  warn "abcde config missing: $ABC"
fi

echo
echo '== Staging =='
printf 'ARM completed entries: %s\n' "$(find "$STAGE" -mindepth 1 -maxdepth 2 2>/dev/null | wc -l)"
printf 'ARM music entries:     %s\n' "$(find "$MUSIC_STAGE" -mindepth 1 -maxdepth 2 2>/dev/null | wc -l)"
find "$STAGE" -mindepth 1 -maxdepth 2 -printf '  %P\n' 2>/dev/null | head -n 40 || true

echo
echo '== Jellyfin library filesystem =='
for d in movies tv music home-videos; do
  if [[ -d "$LIB/$d" ]]; then
    printf '%-12s %8s files  %s\n' "$d" "$(find "$LIB/$d" -type f 2>/dev/null | wc -l)" "$(du -sh "$LIB/$d" 2>/dev/null | awk '{print $1}')"
  else
    warn "Missing library directory $LIB/$d"
  fi
done

# Movies should not have loose files at the library root.
while IFS= read -r -d '' f; do warn "Loose file in Movies root: $f"; done < <(find "$LIB/movies" -maxdepth 1 -type f -print0 2>/dev/null)
# Disc images should never be promoted into a Jellyfin live library by the sorter.
while IFS= read -r -d '' f; do warn "Disc image present in live Jellyfin library: $f"; done < <(find "$LIB" -type f \( -iname '*.iso' -o -iname '*.bin' -o -iname '*.cue' \) -print0 2>/dev/null)
# TV files without SxxEyy are not necessarily wrong, but Jellyfin identification may be poor.
unnamed_tv=0
while IFS= read -r -d '' f; do
  b="$(basename "$f")"
  if [[ ! "$b" =~ [Ss][0-9]{1,2}[Ee][0-9]{1,3} ]]; then ((unnamed_tv+=1)); fi
done < <(find "$LIB/tv" -type f \( -iname '*.mkv' -o -iname '*.mp4' -o -iname '*.m4v' -o -iname '*.avi' -o -iname '*.ts' -o -iname '*.m2ts' \) -print0 2>/dev/null)
(( unnamed_tv == 0 )) && ok 'TV video filenames have recognizable SxxEyy numbering (or library is empty)' || warn "$unnamed_tv TV video file(s) lack SxxEyy naming; they are in the TV folder but may need episode naming"
# Music should not have loose audio files at its root.
while IFS= read -r -d '' f; do warn "Loose audio file in Music root: $f"; done < <(find "$LIB/music" -maxdepth 1 -type f \( -iname '*.flac' -o -iname '*.mp3' -o -iname '*.m4a' -o -iname '*.ogg' -o -iname '*.opus' \) -print0 2>/dev/null)

echo
echo '== Metadata pending =='
printf 'Pending entries: %s\n' "$(find "$ROOT/media/metadata-pending" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l)"
systemctl is-active pcga-metadata-classify.path pcga-metadata-classify.timer 2>/dev/null || true
journalctl -t PCGA-META -n 20 --no-pager 2>/dev/null || true
echo
echo '== Quarantine =='
for d in unidentified duplicates invalid; do
  printf '%-12s %8s files\n' "$d" "$(find "$QUAR/$d" -type f 2>/dev/null | wc -l)"
done

echo
echo '== Sorter automation =='
systemctl is-enabled pcga-media-sort.path pcga-media-sort.timer 2>/dev/null || true
systemctl is-active pcga-media-sort.path pcga-media-sort.timer 2>/dev/null || true
journalctl -t PCGA-SORT -n 20 --no-pager 2>/dev/null || true

echo
echo '== Jellyfin mounts =='
for p in /media/movies /media/tv /media/music /media/home-videos; do
  if docker exec jellyfin test -d "$p" 2>/dev/null; then ok "Jellyfin can see $p"; else warn "Jellyfin cannot see $p"; fi
done

echo
if (( warns == 0 )); then
  echo 'MEDIA AUDIT: PASS'
else
  echo "MEDIA AUDIT: completed with $warns warning(s)"
fi
MEDIA_AUDIT
chmod 0755 /usr/local/sbin/pcga-media-audit

