# ----- Jellyfin library-path synchronizer ------------------------------------
# Jellyfin library membership lives in Jellyfin's managed data model. Do not
# edit jellyfin.db/XML directly; use the supported HTTP API instead.

# PCGA-owned first-run provisioning for game-library services.
cat > /usr/local/sbin/pcga-appliance-credentials <<'PCGA_APPLIANCE_CREDS'
#!/usr/bin/env bash
set -Eeuo pipefail
SECRETS=/etc/pc-game-archive/secrets
CREDS="$SECRETS/appliance-admin.env"
ROMM_LEGACY="$SECRETS/romm-bootstrap.env"
LAN_LEGACY="$SECRETS/lancommander-bootstrap.env"
install -d -m 0700 "$SECRETS"

valid_file(){ [[ -s "$1" ]] && grep -q '^PCGA_APPLIANCE_ADMIN_USER=' "$1" && grep -q '^PCGA_APPLIANCE_ADMIN_PASSWORD=' "$1"; }

if ! valid_file "$CREDS"; then
  user=pcga-admin
  email=pcga-admin@pcga.invalid
  pass=''
  # Preserve the already-managed RomM password during the v0.17.10 shared-credential migration
  # migration so RomM does not need a password reset merely to unify services.
  if [[ -s "$ROMM_LEGACY" ]]; then
    # shellcheck disable=SC1090
    . "$ROMM_LEGACY" || true
    if [[ "${PCGA_ROMM_ADMIN_USER:-}" == pcga-admin && -n "${PCGA_ROMM_ADMIN_PASSWORD:-}" ]]; then
      pass="$PCGA_ROMM_ADMIN_PASSWORD"
    fi
  fi
  if [[ -z "$pass" && -s "$LAN_LEGACY" ]]; then
    # shellcheck disable=SC1090
    . "$LAN_LEGACY" || true
    if [[ "${PCGA_LANCOMMANDER_ADMIN_USER:-}" == pcga-admin && -n "${PCGA_LANCOMMANDER_ADMIN_PASSWORD:-}" ]]; then
      pass="$PCGA_LANCOMMANDER_ADMIN_PASSWORD"
    fi
  fi
  if [[ -z "$pass" ]]; then
    pass="$(python3 - <<'PY'
import secrets,string
alphabet=string.ascii_letters+string.digits+'_-'
print(''.join(secrets.choice(alphabet) for _ in range(40)))
PY
)"
  fi
  umask 077
  cat >"$CREDS" <<EOF_CREDS
PCGA_APPLIANCE_ADMIN_USER=$user
PCGA_APPLIANCE_ADMIN_EMAIL=$email
PCGA_APPLIANCE_ADMIN_PASSWORD=$pass
EOF_CREDS
  chmod 0600 "$CREDS"
  chown root:root "$CREDS" 2>/dev/null || true
fi

# shellcheck disable=SC1090
. "$CREDS"
: "${PCGA_APPLIANCE_ADMIN_USER:?missing appliance username}"
: "${PCGA_APPLIANCE_ADMIN_EMAIL:?missing appliance email}"
: "${PCGA_APPLIANCE_ADMIN_PASSWORD:?missing appliance password}"

# Keep the legacy per-service files as generated compatibility mirrors. They are
# not independent credentials anymore; appliance-admin.env is the source of truth.
umask 077
cat >"$ROMM_LEGACY" <<EOF_ROMM
PCGA_ROMM_ADMIN_USER=$PCGA_APPLIANCE_ADMIN_USER
PCGA_ROMM_ADMIN_PASSWORD=$PCGA_APPLIANCE_ADMIN_PASSWORD
EOF_ROMM
cat >"$LAN_LEGACY" <<EOF_LAN
PCGA_LANCOMMANDER_ADMIN_USER=$PCGA_APPLIANCE_ADMIN_USER
PCGA_LANCOMMANDER_ADMIN_PASSWORD=$PCGA_APPLIANCE_ADMIN_PASSWORD
EOF_LAN
chmod 0600 "$ROMM_LEGACY" "$LAN_LEGACY"
chown root:root "$ROMM_LEGACY" "$LAN_LEGACY" 2>/dev/null || true
PCGA_APPLIANCE_CREDS
chmod 0755 /usr/local/sbin/pcga-appliance-credentials
cat > /usr/local/sbin/pcga-immich-bootstrap <<'PCGA_IMMICH_BOOTSTRAP'
#!/usr/bin/env bash
set -Eeuo pipefail
STATE_DIR=/var/lib/pc-game-archive/bootstrap
STATE_FILE="$STATE_DIR/immich.state"
CREDS=/etc/pc-game-archive/secrets/appliance-admin.env
STACK_ENV=/opt/pc-game-archive/.env
install -d -m 0755 "$STATE_DIR"
state(){ printf '%s\n' "$1" >"$STATE_FILE"; chmod 0644 "$STATE_FILE"; }
[[ -x /usr/local/sbin/pcga-appliance-credentials ]] && /usr/local/sbin/pcga-appliance-credentials
[[ -r "$CREDS" ]] || { state failed; echo 'PCGA appliance credentials missing' >&2; exit 1; }
# shellcheck disable=SC1090
. "$CREDS"
port="${PCGA_IMMICH_PORT:-}"
if [[ -z "$port" && -r "$STACK_ENV" ]]; then port="$(awk -F= '$1=="IMMICH_PORT"{print $2}' "$STACK_ENV" | tail -n1)"; fi
port="${port:-2283}"
base="http://127.0.0.1:${port}"
for _ in $(seq 1 90); do curl -fsS --max-time 2 "$base/api/server/ping" >/dev/null 2>&1 && break; sleep 2; done
curl -fsS --max-time 3 "$base/api/server/ping" >/dev/null 2>&1 || { state failed; echo 'Immich unavailable' >&2; exit 1; }
login(){
  local out code
  out="$(mktemp)"
  code="$(curl -sS --max-time 8 -o "$out" -w '%{http_code}' -H 'Content-Type: application/json' \
    -d "$(python3 - "$PCGA_APPLIANCE_ADMIN_EMAIL" "$PCGA_APPLIANCE_ADMIN_PASSWORD" <<'PY'
import json,sys
print(json.dumps({'email':sys.argv[1],'password':sys.argv[2]}))
PY
)" "$base/api/auth/login" || true)"
  rm -f "$out"
  [[ "$code" == 200 || "$code" == 201 ]]
}
if login; then state ready; exit 0; fi
payload="$(python3 - "$PCGA_APPLIANCE_ADMIN_EMAIL" "$PCGA_APPLIANCE_ADMIN_PASSWORD" "$PCGA_APPLIANCE_ADMIN_USER" <<'PY'
import json,sys
print(json.dumps({'email':sys.argv[1],'password':sys.argv[2],'name':sys.argv[3]}))
PY
)"
out="$(mktemp)"
code="$(curl -sS --max-time 10 -o "$out" -w '%{http_code}' -H 'Content-Type: application/json' -d "$payload" "$base/api/auth/admin-sign-up" || true)"
if [[ "$code" == 200 || "$code" == 201 ]]; then
  rm -f "$out"
  login || { state failed; echo 'Immich appliance admin created but login failed' >&2; exit 1; }
  state ready
  exit 0
fi
# If signup is closed because an administrator already exists, preserve it. A
# non-PCGA preexisting Immich instance must never have accounts overwritten.
if [[ "$code" == 400 || "$code" == 401 || "$code" == 403 || "$code" == 409 ]]; then
  state external
  rm -f "$out"
  exit 0
fi
state failed
echo "Immich bootstrap failed (HTTP $code): $(cat "$out" 2>/dev/null)" >&2
rm -f "$out"
exit 1
PCGA_IMMICH_BOOTSTRAP
chmod 0755 /usr/local/sbin/pcga-immich-bootstrap
cat > /usr/local/sbin/pcga-jellyfin-appliance-user <<'PCGA_JELLYFIN_APPLIANCE'
#!/usr/bin/env bash
set -Eeuo pipefail
STACK_DIR=/opt/pc-game-archive
CREDS=/etc/pc-game-archive/secrets/appliance-admin.env
TOKEN_FILE=/etc/pc-game-archive/jellyfin-api-key
STATE_DIR=/var/lib/pc-game-archive/bootstrap
STATE_FILE="$STATE_DIR/jellyfin.state"
install -d -m 0755 "$STATE_DIR"
state(){ printf '%s\n' "$1" >"$STATE_FILE"; chmod 0644 "$STATE_FILE"; }
[[ -x /usr/local/sbin/pcga-appliance-credentials ]] && /usr/local/sbin/pcga-appliance-credentials
[[ -r "$CREDS" ]] || { echo 'PCGA appliance credentials missing' >&2; exit 1; }
# shellcheck disable=SC1090
. "$CREDS"
port=8096
if [[ -r "$STACK_DIR/.env" ]]; then p="$(awk -F= '$1=="JELLYFIN_PORT"{print $2}' "$STACK_DIR/.env" | tail -n1)"; [[ -n "$p" ]] && port="$p"; fi
base="http://127.0.0.1:${port}"
CLIENT='MediaBrowser Client="PCGameArchive", Device="PCGameArchiveServer", DeviceId="pcga-local", Version="0.17.53"'
authenticate(){
  local response
  response="$(curl -fsS --max-time 12 -H "Authorization: $CLIENT" -H 'Content-Type: application/json' \
    -d "$(python3 - "$PCGA_APPLIANCE_ADMIN_USER" "$PCGA_APPLIANCE_ADMIN_PASSWORD" <<'PY'
import json,sys
print(json.dumps({'Username':sys.argv[1],'Pw':sys.argv[2]}))
PY
)" "$base/Users/AuthenticateByName")" || return 1
  token="$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("AccessToken", ""))' <<<"$response")"
  [[ -n "$token" ]] || return 1
  umask 077; printf '%s\n' "$token" >"$TOKEN_FILE"; chmod 0600 "$TOKEN_FILE"
}
if authenticate; then state ready; exit 0; fi
[[ -s "$TOKEN_FILE" ]] || { state failed; echo 'No authenticated Jellyfin admin session is available to create the PCGA account' >&2; exit 1; }
token="$(tr -d '\r\n' <"$TOKEN_FILE")"
headers=(-H "Authorization: ${CLIENT}, Token=\"${token}\"" -H 'Accept: application/json')
users="$(curl -fsS --max-time 12 "${headers[@]}" "$base/Users")" || exit 1
uid="$(python3 -c 'import json,sys; name=sys.argv[1].lower(); data=json.load(sys.stdin); print(next((u.get("Id","") for u in data if str(u.get("Name","")).lower()==name), ""))' "$PCGA_APPLIANCE_ADMIN_USER" <<<"$users")"
if [[ -z "$uid" ]]; then
  created="$(curl -fsS --max-time 12 -X POST "${headers[@]}" -H 'Content-Type: application/json' \
    -d "$(python3 - "$PCGA_APPLIANCE_ADMIN_USER" "$PCGA_APPLIANCE_ADMIN_PASSWORD" <<'PY'
import json,sys
print(json.dumps({'Name':sys.argv[1],'Password':sys.argv[2]}))
PY
)" "$base/Users/New")"
  uid="$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("Id", ""))' <<<"$created")"
  [[ -n "$uid" ]] || { echo 'Jellyfin did not return an id for the PCGA appliance account' >&2; exit 1; }
else
  # Converge a PCGA-owned account back to the shared password. This uses an
  # authenticated administrator session and does not touch unrelated users.
  curl -fsS --max-time 12 -X POST "${headers[@]}" -H 'Content-Type: application/json' \
    -d "$(python3 - "$PCGA_APPLIANCE_ADMIN_PASSWORD" <<'PY'
import json,sys
print(json.dumps({'NewPw':sys.argv[1],'ResetPassword':False}))
PY
)" "$base/Users/$uid/Password" >/dev/null || true
fi
# Preserve Jellyfin's complete policy object and only assert administrator +
# LAN-appliance defaults so required policy fields remain intact.
user="$(curl -fsS --max-time 12 "${headers[@]}" "$base/Users/$uid")"
policy="$(python3 -c 'import json,sys; u=json.load(sys.stdin); p=dict(u.get("Policy") or {}); p["IsAdministrator"]=True; p["IsDisabled"]=False; p["EnableRemoteAccess"]=False; print(json.dumps(p,separators=(",",":")))' <<<"$user")"
curl -fsS --max-time 12 -X POST "${headers[@]}" -H 'Content-Type: application/json' -d "$policy" "$base/Users/$uid/Policy" >/dev/null
# End with a token belonging to the common PCGA account.
if authenticate; then state ready; else state failed; exit 1; fi
PCGA_JELLYFIN_APPLIANCE
chmod 0755 /usr/local/sbin/pcga-jellyfin-appliance-user
cat > /usr/local/sbin/pcga-game-stack-start <<'PCGA_GAME_STACK_START'
#!/usr/bin/env bash
set -Eeuo pipefail

STACK_DIR=/opt/pc-game-archive
STATE_DIR=/var/lib/pc-game-archive/bootstrap
STATE_FILE="$STATE_DIR/game-stack.state"

log(){ printf '[pcga-game-stack] %s\n' "$*"; }

PCGA_GAME_STACK_LOCK="${PCGA_GAME_STACK_LOCK:-/run/pcga-game-stack-start.lock}"
pcga_acquire_game_stack_lock(){
  [[ "${PCGA_GAME_STACK_LOCK_HELD:-0}" == 1 ]] && return 0
  exec 9>"$PCGA_GAME_STACK_LOCK"
  if ! flock -w "${PCGA_GAME_STACK_LOCK_TIMEOUT:-180}" 9; then
    printf '[pcga-lock] Timed out waiting for game-stack reconciliation lock: %s\n' "$PCGA_GAME_STACK_LOCK" >&2
    return 75
  fi
  export PCGA_GAME_STACK_LOCK_HELD=1
}
state(){ install -d -m 0755 "$STATE_DIR"; printf '%s\n' "$1" >"$STATE_FILE"; chmod 0644 "$STATE_FILE"; }

[[ $EUID -eq 0 ]] || exec sudo -E bash "$0" "$@"
[[ -d "$STACK_DIR" ]] || { log "Stack directory missing: $STACK_DIR"; state failed; exit 1; }

# Only one boot/reconciliation path may manipulate the game containers at once.
pcga_acquire_game_stack_lock || exit $?

cd "$STACK_DIR"
FILES=(-f compose.yml)
[[ -f compose.jellyfin-gpu.yml ]] && FILES+=(-f compose.jellyfin-gpu.yml)
[[ -f compose.immich.yml ]] && FILES+=(-f compose.immich.yml)
[[ -f compose.romm.yml ]] && FILES+=(-f compose.romm.yml)
[[ -f compose.arm.yml ]] && FILES+=(-f compose.arm.yml)
[[ -f compose.status.yml ]] && FILES+=(-f compose.status.yml)
[[ -f compose.wolf.yml ]] && FILES+=(-f compose.wolf.yml)
[[ -f compose.moonlight-web.yml ]] && FILES+=(-f compose.moonlight-web.yml)
DC=(docker compose "${FILES[@]}")

compose_up_retry(){
  local out rc attempt
  for attempt in 1 2 3 4 5 6; do
    out="$(mktemp)"
    if "${DC[@]}" up "$@" >"$out" 2>&1; then
      rm -f "$out"; return 0
    else
      rc=$?
    fi
    if grep -Fq 'removal of container' "$out" && grep -Fq 'already in progress' "$out"; then
      log "Docker is still finishing a prior container removal; retrying Compose (${attempt}/6)"
      rm -f "$out"
      sleep $((attempt * 2))
      continue
    fi
    cat "$out" >&2; rm -f "$out"; return "$rc"
  done
  log 'Docker did not finish the prior container removal after bounded retries'
  return 1
}


repair_wolf_x264_pipeline(){
  local cfg=/etc/wolf/cfg/config.toml
  [[ -f "$cfg" ]] || { printf 'unchanged\n'; return 0; }
  python3 - "$cfg" <<'PYWOLFX264'
from pathlib import Path
import sys, tomllib
p=Path(sys.argv[1])
s=p.read_text()
needle="    [[gstreamer.video.h264_encoders]]\n    check_elements = [ 'x264enc' ]"
start=s.find(needle)
if start < 0:
    print('unchanged')
    raise SystemExit(0)
end=s.find('    [[gstreamer.video.hevc_encoders]]', start)
if end < 0:
    end=len(s)
block=s[start:end]
if 'video_params =' in block:
    print('unchanged')
    raise SystemExit(0)
plugin="    plugin_name = 'x264'\n"
if plugin not in block:
    raise SystemExit('x264 encoder block is missing plugin_name')
addition=(
    "    plugin_name = 'x264'\n"
    "    video_params = '''videoconvertscale !\n"
    "videorate !\n"
    "video/x-raw, width={width}, height={height}, framerate={fps}/1, format=I420,\n"
    "chroma-site={color_range}, colorimetry={color_space}'''\n"
    "    video_params_zero_copy = '''videoconvertscale !\n"
    "videorate !\n"
    "video/x-raw, width={width}, height={height}, framerate={fps}/1, format=I420,\n"
    "chroma-site={color_range}, colorimetry={color_space}'''\n"
)
block=block.replace(plugin, addition, 1)
candidate=s[:start] + block + s[end:]
tomllib.loads(candidate)
p.write_text(candidate)
print('changed')
PYWOLFX264
}

# Docker can be active before it is actually ready to accept compose work during
# host boot. Bound the wait so systemd can retry rather than hanging forever.
docker_ready=0
for _ in $(seq 1 30); do
  if docker info >/dev/null 2>&1; then docker_ready=1; break; fi
  sleep 2
done
if [[ $docker_ready -ne 1 ]]; then
  log 'Docker daemon did not become ready'
  state failed
  exit 1
fi
"${DC[@]}" config >/dev/null

romm_enabled=true
if [[ -r /etc/pc-game-archive/appliance.json ]]; then
  romm_enabled="$(python3 - <<'PY'
import json
try:
    with open('/etc/pc-game-archive/appliance.json', encoding='utf-8') as f:
        d=json.load(f)
    print('true' if d.get('games',{}).get('romm_enabled', True) else 'false')
except Exception:
    print('true')
PY
)"
fi

wait_http(){
  local url="$1" label="$2" tries="${3:-60}"
  for _ in $(seq 1 "$tries"); do
    code="$(curl -sS -L --max-time 3 -o /dev/null -w '%{http_code}' "$url" 2>/dev/null || true)"
    case "$code" in 200|301|302|303|307|308) return 0;; esac
    sleep 2
  done
  log "$label did not become HTTP-ready at $url"
  return 1
}

# LANCommander is a baseline PCGA service. `docker compose up -d` is used
# deliberately instead of relying only on restart:unless-stopped: an interrupted
# first-user bootstrap may have left the container explicitly stopped.
log 'Ensuring LANCommander is running'
if ! compose_up_retry -d lancommander; then
  log 'Unable to start LANCommander with Docker Compose'
  state failed
  exit 1
fi
if ! wait_http 'http://127.0.0.1:1337/' 'LANCommander' 60; then
  "${DC[@]}" logs --tail=80 lancommander >&2 || true
  state failed
  exit 1
fi

lan_state="$(cat "$STATE_DIR/lancommander.state" 2>/dev/null || true)"
if [[ "$lan_state" != ready ]]; then
  log 'Completing LANCommander appliance bootstrap'
  if ! /usr/local/sbin/pcga-lancommander-bootstrap; then
    log 'LANCommander bootstrap is not complete'
    state failed
    exit 1
  fi
  wait_http 'http://127.0.0.1:1337/' 'LANCommander after bootstrap' 60 || { state failed; exit 1; }
fi

if [[ "$romm_enabled" == true && -f compose.romm.yml ]]; then
  romm_port="$(awk -F= '$1=="ROMM_PORT"{print $2}' .env 2>/dev/null | tail -n1)"
  romm_port="${romm_port:-8082}"
  log 'Ensuring RomM database and application are running'
  if ! compose_up_retry -d romm-db romm; then
    log 'Unable to start RomM with Docker Compose'
    state failed
    exit 1
  fi
  if ! wait_http "http://127.0.0.1:${romm_port}/api/heartbeat" 'RomM' 90; then
    "${DC[@]}" logs --tail=100 romm-db romm >&2 || true
    state failed
    exit 1
  fi

  romm_state="$(cat "$STATE_DIR/romm.state" 2>/dev/null || true)"
  if [[ "$romm_state" != ready ]]; then
    log 'Completing RomM appliance bootstrap'
    if /usr/local/sbin/pcga-romm-bootstrap; then
      # Bootstrap can change RomM environment values such as setup-wizard state.
      # Recreate only on this first/recovery bootstrap, never on normal boots.
      compose_up_retry -d --no-deps --force-recreate romm
      wait_http "http://127.0.0.1:${romm_port}/api/heartbeat" 'RomM after bootstrap' 90 || { state failed; exit 1; }
    else
      log 'RomM bootstrap is not complete'
      state failed
      exit 1
    fi
  fi
else
  # The portal control is authoritative. Do not resurrect RomM when the user has
  # intentionally disabled the emulator backend.
  if docker inspect romm >/dev/null 2>&1; then docker stop romm >/dev/null 2>&1 || true; fi
  if docker inspect romm-db >/dev/null 2>&1; then docker stop romm-db >/dev/null 2>&1 || true; fi
  log 'RomM is disabled in PCGA settings'
fi

if [[ -f compose.wolf.yml && -f compose.moonlight-web.yml ]]; then
  moon_port="$(awk -F= '$1=="PCGA_MOONLIGHT_WEB_PORT"{print $2}' .env 2>/dev/null | tail -n1)"
  moon_port="${moon_port:-8101}"
  ca_cert=/etc/pc-game-archive/tls/pcga-ca.crt
  log 'Reconciling the PCGA secure browser context'
  /usr/local/sbin/pcga-secure-context-bootstrap || { log 'Secure-context bootstrap failed'; state failed; exit 1; }
  log 'Ensuring Wolf and the PCGA browser streaming client are running'
  if ! compose_up_retry -d wolf wolf-den moonlight-web; then
    log 'Unable to start Wolf/Moonlight Web streaming services'
    state failed
    exit 1
  fi
  # Wolf stable can persist an x264 fallback entry without the software
  # videoconvert/videorate stage. That renders a consumer pipeline containing
  # a bare `! !` and causes an immediate GStreamer parse failure.
  wolf_x264_repair="$(repair_wolf_x264_pipeline)"
  if [[ "$wolf_x264_repair" == changed ]]; then
    log 'Repaired Wolf software x264 video conversion pipeline'
    docker restart wolf >/dev/null || { log 'Unable to restart Wolf after x264 pipeline repair'; state failed; exit 1; }
    sleep 2
  fi
  if ! curl --cacert "$ca_cert" -fsS --retry 30 --retry-delay 2 --retry-connrefused --max-time 4 "https://127.0.0.1:${moon_port}/" >/dev/null 2>&1; then
    "${DC[@]}" logs --tail=100 moonlight-web >&2 || true
    state failed
    exit 1
  fi
  moon_network="$(docker inspect -f '{{.HostConfig.NetworkMode}}' pcga-moonlight-web 2>/dev/null || true)"
  if [[ "$moon_network" != host ]]; then
    log "Moonlight Web is using '$moon_network' networking; v0.17.53 requires host networking for browser streaming"
    state failed
    exit 1
  fi
  read -r moon_state moon_state_network < <(python3 - "$STATE_DIR/moonlight-web.json" <<'PY'
import json,sys
try: d=json.load(open(sys.argv[1]))
except Exception: d={}
print(d.get('state',''), d.get('network_mode',''))
PY
)
  if [[ "$moon_state" != ready || "$moon_state_network" != host ]]; then
    /usr/local/sbin/pcga-moonlight-web-bootstrap || { log 'Moonlight Web appliance bootstrap failed'; state failed; exit 1; }
  fi
fi

state ready
log 'Game services are running and reconciled'
PCGA_GAME_STACK_START
chmod 0755 /usr/local/sbin/pcga-game-stack-start
cat > /etc/systemd/system/pcga-game-stack.service <<'PCGA_GAME_STACK_UNIT'
[Unit]
Description=PC Game Archive game-service startup and reconciliation
After=docker.service network-online.target
Wants=docker.service network-online.target
Before=pcga-service-auth.service

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/pcga-game-stack-start
TimeoutStartSec=8min
Restart=on-failure
RestartSec=20s

[Install]
WantedBy=multi-user.target
PCGA_GAME_STACK_UNIT
cat > /usr/local/sbin/pcga-service-auth <<'PCGA_SERVICE_AUTH'
#!/usr/bin/env bash
set -u
log(){ printf '[pcga-auth] %s\n' "$*"; }

PCGA_GAME_STACK_LOCK="${PCGA_GAME_STACK_LOCK:-/run/pcga-game-stack-start.lock}"
pcga_acquire_game_stack_lock(){
  [[ "${PCGA_GAME_STACK_LOCK_HELD:-0}" == 1 ]] && return 0
  exec 9>"$PCGA_GAME_STACK_LOCK"
  if ! flock -w "${PCGA_GAME_STACK_LOCK_TIMEOUT:-180}" 9; then
    printf '[pcga-lock] Timed out waiting for game-stack reconciliation lock: %s\n' "$PCGA_GAME_STACK_LOCK" >&2
    return 75
  fi
  export PCGA_GAME_STACK_LOCK_HELD=1
}
pcga_acquire_game_stack_lock || exit $?
failed=0
/usr/local/sbin/pcga-appliance-credentials || exit 1
/usr/local/sbin/pcga-game-stack-start --ensure || { log 'Game-stack reconciliation failed; timer will retry'; failed=1; }
romm_present=0
if docker inspect -f '{{.State.Running}}' romm 2>/dev/null | grep -qx true; then
  romm_present=1
  romm_state="$(cat /var/lib/pc-game-archive/bootstrap/romm.state 2>/dev/null || true)"
  if [[ "$romm_state" != ready ]]; then
    /usr/local/sbin/pcga-romm-bootstrap || { log 'RomM reconciliation failed; timer will retry'; failed=1; }
  fi
fi
if docker inspect -f '{{.State.Running}}' lancommander 2>/dev/null | grep -qx true; then
  lan_state="$(cat /var/lib/pc-game-archive/bootstrap/lancommander.state 2>/dev/null || true)"
  if [[ "$lan_state" != ready ]]; then
    /usr/local/sbin/pcga-lancommander-bootstrap || { log 'LANCommander reconciliation failed; timer will retry'; failed=1; }
  fi
fi
if docker inspect -f '{{.State.Running}}' immich_server 2>/dev/null | grep -qx true; then
  immich_state="$(cat /var/lib/pc-game-archive/bootstrap/immich.state 2>/dev/null || true)"
  if [[ "$immich_state" != ready && "$immich_state" != external ]]; then
    /usr/local/sbin/pcga-immich-bootstrap || { log 'Immich reconciliation failed; timer will retry'; failed=1; }
  fi
fi
if docker inspect -f '{{.State.Running}}' jellyfin 2>/dev/null | grep -qx true; then
  jellyfin_state="$(cat /var/lib/pc-game-archive/bootstrap/jellyfin.state 2>/dev/null || true)"
  if [[ "$jellyfin_state" != ready ]]; then
    /usr/local/sbin/pcga-jellyfin-appliance-user >/dev/null 2>&1 || { log 'Jellyfin common-account reconciliation failed; timer will retry'; failed=1; }
  fi
fi
# Warm the portal's scoped RomM bearer-token cache. This is best-effort because
# pcga-status may still be starting when the boot service runs.
status_port=8098
if [[ -r /opt/pc-game-archive/.env ]]; then p="$(awk -F= '$1=="STATUS_PORT"{print $2}' /opt/pc-game-archive/.env | tail -n1)"; [[ -n "$p" ]] && status_port="$p"; fi
if [[ "$romm_present" -eq 1 ]]; then
  if ! curl -fsS --max-time 8 "http://127.0.0.1:${status_port}/api/games/health" | python3 -c 'import json,sys; raise SystemExit(0 if json.load(sys.stdin).get("available") is True else 1)' >/dev/null 2>&1; then
    log 'RomM portal authentication warm-up is not healthy yet; timer will retry'
    failed=1
  fi
fi
exit "$failed"
PCGA_SERVICE_AUTH
chmod 0755 /usr/local/sbin/pcga-service-auth
cat > /etc/systemd/system/pcga-service-auth.service <<'PCGA_SERVICE_AUTH_UNIT'
[Unit]
Description=PC Game Archive appliance service authentication reconciliation
After=docker.service network-online.target pcga-game-stack.service
Wants=docker.service network-online.target pcga-game-stack.service

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/pcga-service-auth
PCGA_SERVICE_AUTH_UNIT
cat > /etc/systemd/system/pcga-service-auth.timer <<'PCGA_SERVICE_AUTH_TIMER'
[Unit]
Description=Retry PC Game Archive appliance service authentication

[Timer]
OnBootSec=45s
OnUnitActiveSec=5min
RandomizedDelaySec=15s
Persistent=true

[Install]
WantedBy=timers.target
PCGA_SERVICE_AUTH_TIMER
/usr/local/sbin/pcga-appliance-credentials

cat > /usr/local/sbin/pcga-romm-bootstrap <<'PCGA_ROMM_BOOTSTRAP'
#!/usr/bin/env bash
set -Eeuo pipefail

PCGA_GAME_STACK_LOCK="${PCGA_GAME_STACK_LOCK:-/run/pcga-game-stack-start.lock}"
pcga_acquire_game_stack_lock(){
  [[ "${PCGA_GAME_STACK_LOCK_HELD:-0}" == 1 ]] && return 0
  exec 9>"$PCGA_GAME_STACK_LOCK"
  if ! flock -w "${PCGA_GAME_STACK_LOCK_TIMEOUT:-180}" 9; then
    printf '[pcga-lock] Timed out waiting for game-stack reconciliation lock: %s\n' "$PCGA_GAME_STACK_LOCK" >&2
    return 75
  fi
  export PCGA_GAME_STACK_LOCK_HELD=1
}
pcga_acquire_game_stack_lock || exit $?
STATE_DIR=/var/lib/pc-game-archive/bootstrap
STATE_FILE="$STATE_DIR/romm.state"
SECRETS=/etc/pc-game-archive/secrets
CREDS="$SECRETS/romm-bootstrap.env"
ROMM_ENV=/etc/pc-game-archive/romm.env
STACK_ENV=/opt/pc-game-archive/.env
install -d -m 0755 "$STATE_DIR"
install -d -m 0700 "$SECRETS"
[[ -x /usr/local/sbin/pcga-appliance-credentials ]] && /usr/local/sbin/pcga-appliance-credentials
state(){ printf '%s\n' "$1" >"$STATE_FILE"; chmod 0644 "$STATE_FILE"; }
port="${PCGA_ROMM_PORT:-}"
if [[ -z "$port" && -r "$STACK_ENV" ]]; then port="$(awk -F= '$1=="ROMM_PORT"{print $2}' "$STACK_ENV" | tail -n1)"; fi
port="${port:-8082}"
base="http://127.0.0.1:${port}"
for _ in $(seq 1 90); do curl -fsS --max-time 2 "$base/api/heartbeat" >/dev/null 2>&1 && break; sleep 2; done
curl -fsS --max-time 3 "$base/api/heartbeat" >/dev/null 2>&1 || { state failed; echo 'RomM heartbeat unavailable' >&2; exit 1; }
set_env(){ python3 - "$ROMM_ENV" "$1" "$2" <<'PYENV'
from pathlib import Path
import sys
p=Path(sys.argv[1]); k=sys.argv[2]; v=sys.argv[3]
lines=p.read_text().splitlines() if p.exists() else []
for i,line in enumerate(lines):
    if line.startswith(k+'='): lines[i]=f'{k}={v}'; break
else: lines.append(f'{k}={v}')
p.write_text('\n'.join(lines)+'\n')
PYENV
chmod 0600 "$ROMM_ENV"; }
verify(){
  local u="$1" p="$2"
  curl -fsS --max-time 8 \
    -H 'Content-Type: application/x-www-form-urlencoded' \
    --data-urlencode 'grant_type=password' \
    --data-urlencode "username=$u" \
    --data-urlencode "password=$p" \
    --data-urlencode 'scope=roms.read platforms.read assets.read firmware.read tasks.run' \
    "$base/api/token" | python3 -c 'import json,sys; d=json.load(sys.stdin); assert d.get("access_token")' >/dev/null 2>&1
}
persist_ready(){
  local u="$1" p="$2"
  umask 077
  cat >"$CREDS" <<EOF_CREDS
PCGA_ROMM_ADMIN_USER=$u
PCGA_ROMM_ADMIN_PASSWORD=$p
EOF_CREDS
  chmod 0600 "$CREDS"
  chown root:root "$CREDS" 2>/dev/null || true
  set_env DISABLE_SETUP_WIZARD true
  state ready
}
reconcile_reserved_identity(){
  local u="$1" email="$2" p="$3"
  # RomM intentionally closes unauthenticated admin creation after the first
  # administrator exists. PCGA still owns this appliance's RomM container and
  # database, so reconcile only the reserved PCGA identity through RomM's own
  # ORM/auth handlers. Existing non-PCGA users and administrators are untouched.
  docker exec \
    -e PCGA_BOOTSTRAP_USER="$u" \
    -e PCGA_BOOTSTRAP_EMAIL="$email" \
    -e PCGA_BOOTSTRAP_PASSWORD="$p" \
    -i romm python3 - <<'PYROMM'
import os
from handler.auth import auth_handler
from handler.database import db_user_handler
from models.user import Role, User

username = os.environ["PCGA_BOOTSTRAP_USER"].strip().lower()
email = os.environ.get("PCGA_BOOTSTRAP_EMAIL", "").strip().lower()
password = os.environ["PCGA_BOOTSTRAP_PASSWORD"]

existing = db_user_handler.get_user_by_username(username)
email_owner = db_user_handler.get_user_by_email(email) if email else None
safe_email = email if (not email_owner or (existing and email_owner.id == existing.id)) else None
hashed = auth_handler.get_password_hash(password)

if existing:
    updates = {
        "hashed_password": hashed,
        "enabled": True,
        "role": Role.ADMIN,
    }
    # Preserve an existing address. Only attach the appliance address when it
    # is unused, so a pre-existing administrator is never modified indirectly.
    if not existing.email and safe_email:
        updates["email"] = safe_email
    db_user_handler.update_user(existing.id, updates)
    print("updated")
else:
    db_user_handler.add_user(
        User(
            username=username,
            hashed_password=hashed,
            email=safe_email,
            enabled=True,
            role=Role.ADMIN,
        )
    )
    print("created")
PYROMM
}
enable_emulation(){
  set_env DISABLE_EMULATOR_JS false
  set_env DISABLE_RUFFLE_RS false
}
enable_emulation
if [[ -s "$CREDS" ]]; then
  # shellcheck disable=SC1090
  . "$CREDS"
  if verify "$PCGA_ROMM_ADMIN_USER" "$PCGA_ROMM_ADMIN_PASSWORD"; then
    set_env DISABLE_SETUP_WIZARD true
    state ready
    exit 0
  fi
fi
# New PCGA-managed RomM accounts always use the common appliance identity.
. /etc/pc-game-archive/secrets/appliance-admin.env
user="$PCGA_APPLIANCE_ADMIN_USER"
email="$PCGA_APPLIANCE_ADMIN_EMAIL"
pass="$PCGA_APPLIANCE_ADMIN_PASSWORD"
payload="$(python3 - "$user" "$email" "$pass" <<'PYJSON'
import json,sys
print(json.dumps({'username':sys.argv[1],'email':sys.argv[2],'password':sys.argv[3],'role':'ADMIN'}))
PYJSON
)"
out="$(mktemp)"
trap 'rm -f "$out"' EXIT
code="$(curl -sS --max-time 8 -o "$out" -w '%{http_code}' -H 'Content-Type: application/json' -d "$payload" "$base/api/users" || true)"
if [[ "$code" == 200 || "$code" == 201 ]]; then
  if ! verify "$user" "$pass"; then state failed; echo 'RomM admin was created but authentication verification failed' >&2; exit 1; fi
  persist_ready "$user" "$pass"
  exit 0
fi

# When RomM already has an administrator, /api/users correctly stops being a
# public bootstrap endpoint. That is not an "external administration" terminal
# state for a PCGA-owned service: add/reconcile the reserved appliance identity
# through RomM's own model/authentication layer, then verify it through OAuth.
case "$code" in
  400|401|403|409|422)
    if ! reconcile_reserved_identity "$user" "$email" "$pass"; then
      state failed
      echo "RomM already has users, but PCGA could not reconcile its reserved appliance identity (HTTP $code from first-user API)" >&2
      exit 1
    fi
    if ! verify "$user" "$pass"; then
      state failed
      echo 'RomM reserved appliance identity was reconciled but OAuth verification failed' >&2
      exit 1
    fi
    persist_ready "$user" "$pass"
    echo 'RomM already initialized; preserved existing users and reconciled the PCGA appliance identity.'
    ;;
  *)
    state failed
    echo "RomM bootstrap failed (HTTP $code): $(cat "$out" 2>/dev/null)" >&2
    exit 1
    ;;
esac
PCGA_ROMM_BOOTSTRAP
chmod 0755 /usr/local/sbin/pcga-romm-bootstrap
cat > /usr/local/sbin/pcga-lancommander-bootstrap <<'PCGA_LAN_BOOTSTRAP'
#!/usr/bin/env bash
set -Eeuo pipefail

PCGA_GAME_STACK_LOCK="${PCGA_GAME_STACK_LOCK:-/run/pcga-game-stack-start.lock}"
pcga_acquire_game_stack_lock(){
  [[ "${PCGA_GAME_STACK_LOCK_HELD:-0}" == 1 ]] && return 0
  exec 9>"$PCGA_GAME_STACK_LOCK"
  if ! flock -w "${PCGA_GAME_STACK_LOCK_TIMEOUT:-180}" 9; then
    printf '[pcga-lock] Timed out waiting for game-stack reconciliation lock: %s\n' "$PCGA_GAME_STACK_LOCK" >&2
    return 75
  fi
  export PCGA_GAME_STACK_LOCK_HELD=1
}
pcga_acquire_game_stack_lock || exit $?

STATE_DIR=/var/lib/pc-game-archive/bootstrap
STATE_FILE="$STATE_DIR/lancommander.state"
CATALOG_PTR="$STATE_DIR/lancommander.catalog-db"
SECRETS=/etc/pc-game-archive/secrets
CREDS="$SECRETS/lancommander-bootstrap.env"
ROOT="$(cat /etc/pc-game-archive/archive-root 2>/dev/null || echo /srv/pc-game-archive)"
DATA="$ROOT/lancommander"
port="${PCGA_LANCOMMANDER_PORT:-1337}"

install -d -m 0755 "$STATE_DIR"
install -d -m 0700 "$SECRETS"
[[ -x /usr/local/sbin/pcga-appliance-credentials ]] && /usr/local/sbin/pcga-appliance-credentials
state(){ printf '%s\n' "$1" >"$STATE_FILE"; chmod 0644 "$STATE_FILE"; }
fail(){ state failed; printf '[pcga-lancommander-bootstrap:error] %s\n' "$*" >&2; exit 1; }

probe_setup(){
  local out url
  out="$(mktemp)"
  url="$(curl -LsS --max-time 5 -o "$out" -w '%{url_effective}' "http://127.0.0.1:${port}/" 2>/dev/null || true)"
  if grep -Eqi 'FirstTimeSetup|Create Administrator User|Initial Server Setup' "$out" || [[ "$url" == *FirstTimeSetup* ]]; then
    rm -f "$out"; return 0
  fi
  rm -f "$out"; return 1
}

wait_http(){
  local code
  for _ in $(seq 1 60); do
    code="$(curl -sS -L --max-time 3 -o /dev/null -w '%{http_code}' "http://127.0.0.1:${port}/" 2>/dev/null || true)"
    case "$code" in 200|301|302|303|307|308) return 0;; esac
    sleep 2
  done
  return 1
}

# LANCommander 2.1.x creates its initial Identity administrator through the
# first-time Blazor flow. PCGA's appliance deployment is intentionally pinned to
# v2.1.16 + SQLite, so reconcile only the reserved PCGA identity while the
# container is stopped. Existing users/admins are never deleted or repurposed.
wait_http || fail "LANCommander did not become HTTP-ready before bootstrap"

docker stop lancommander >/dev/null || fail "Unable to stop LANCommander for guarded identity reconciliation"
restart_on_exit=1
trap 'if [[ ${restart_on_exit:-0} -eq 1 ]]; then docker start lancommander >/dev/null 2>&1 || true; fi' EXIT

db="$(python3 - "$DATA" <<'PYIDENTITY'
from pathlib import Path
import os, sqlite3, sys
root=Path(sys.argv[1]).resolve(strict=False)
pruned={'uploads','media','saves','steam','archives','files','cache','downloads'}
suffixes={'.db','.sqlite','.sqlite3'}

def is_sqlite(p):
    try:
        with p.open('rb') as f: return f.read(16) == b'SQLite format 3\x00'
    except OSError: return False

candidates=[]
try:
    for current, dirs, files in os.walk(root):
        cur=Path(current)
        try: depth=len(cur.relative_to(root).parts)
        except ValueError: continue
        dirs[:] = [d for d in dirs if d.lower() not in pruned and depth < 4]
        if depth > 4:
            dirs[:] = []
            continue
        for name in files:
            p=cur/name
            if p.suffix.lower() in suffixes or is_sqlite(p): candidates.append(p)
except OSError:
    pass
for p in sorted(candidates, key=lambda q:(len(q.parts), str(q))):
    try:
        c=sqlite3.connect(f'file:{p}?mode=ro', uri=True, timeout=.5)
        try: tables={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        finally: c.close()
    except sqlite3.Error:
        continue
    if {'Users','Roles','UserRoles'} <= tables:
        print(p); break
PYIDENTITY
)"
[[ -n "$db" ]] || fail "Supported LANCommander SQLite identity database was not found; existing/custom database was not modified"

# appliance-admin.env is the source of truth; pcga-appliance-credentials keeps
# this compatibility file synchronized for older components.
# shellcheck disable=SC1090
. "$CREDS"
[[ -n "${PCGA_LANCOMMANDER_ADMIN_USER:-}" && -n "${PCGA_LANCOMMANDER_ADMIN_PASSWORD:-}" ]] || fail "LANCommander appliance credential is missing"

stamp="$(date +%Y%m%d-%H%M%S)"
backup="${db}.pcga-prebootstrap-${stamp}.bak"
cp -a "$db" "$backup"

set +e
python3 - "$db" "$PCGA_LANCOMMANDER_ADMIN_USER" "$PCGA_LANCOMMANDER_ADMIN_PASSWORD" <<'PYDB'
import base64, datetime, hashlib, hmac, os, sqlite3, struct, sys, uuid

path, username, password = sys.argv[1:]
con = sqlite3.connect(path)
con.execute('PRAGMA foreign_keys=ON')
con.row_factory = sqlite3.Row

def columns(table):
    return {r[1]: r for r in con.execute(f'PRAGMA table_info("{table}")')}

def required_without_db_default(cols):
    return {name for name, row in cols.items() if row[3] and row[4] is None}

def identity_hash(pw):
    # ASP.NET Core Identity V3 PasswordHasher format.
    salt = os.urandom(16)
    iterations = 100000
    subkey = hashlib.pbkdf2_hmac('sha512', pw.encode(), salt, iterations, 32)
    return base64.b64encode(b'\x01' + struct.pack('>III', 2, iterations, len(salt)) + salt + subkey).decode()

def identity_verify(encoded, pw):
    try:
        raw = base64.b64decode(encoded)
        if len(raw) < 13 or raw[0] != 1:
            return False
        prf, iterations, salt_len = struct.unpack('>III', raw[1:13])
        if prf != 2 or iterations < 1 or salt_len < 8 or len(raw) <= 13 + salt_len:
            return False
        salt = raw[13:13+salt_len]
        expected = raw[13+salt_len:]
        actual = hashlib.pbkdf2_hmac('sha512', pw.encode(), salt, iterations, len(expected))
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def filtered(values, cols, *, include_none=False):
    return {k: v for k, v in values.items() if k in cols and (include_none or v is not None)}

def verify_required(table, cols, values, recognized):
    req = required_without_db_default(cols)
    unknown = sorted(req - recognized)
    if unknown:
        raise ValueError(f'Unsupported required {table} columns: ' + ','.join(unknown))
    missing = sorted(name for name in req if name not in values or values[name] is None)
    if missing:
        raise ValueError(f'No safe bootstrap value for required {table} columns: ' + ','.join(missing))

uc, rc, urc = columns('Users'), columns('Roles'), columns('UserRoles')
required_user = {'Id','UserName','NormalizedUserName','PasswordHash','SecurityStamp','ConcurrencyStamp','Approved','ApprovedOn'}
required_role = {'Id','Name','NormalizedName','ConcurrencyStamp'}
required_userrole = {'UserId','RoleId'}
if not required_user <= set(uc) or not required_role <= set(rc) or not required_userrole <= set(urc):
    print('LANCommander identity schema differs from pinned 2.1.x contract; refusing mutation', file=sys.stderr)
    raise SystemExit(31)

known_user = required_user | {
    'AccessFailedCount','Email','NormalizedEmail','EmailConfirmed','PhoneNumber',
    'PhoneNumberConfirmed','TwoFactorEnabled','LockoutEnd','LockoutEnabled','Alias',
    'RefreshToken','RefreshTokenExpiration','CreatedById','CreatedOn','UpdatedById','UpdatedOn'
}
known_role = required_role | {'CreatedById','CreatedOn','UpdatedById','UpdatedOn'}
known_userrole = required_userrole | {'CreatedById','CreatedOn','UpdatedById','UpdatedOn'}

now = datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None).strftime('%Y-%m-%d %H:%M:%S.%f')
expired_refresh = '0001-01-01 00:00:00.000000'
normalized = username.upper()

# Use the canonical Administrator role when present; create it only if absent.
role_row = con.execute("SELECT * FROM Roles WHERE upper(COALESCE(NULLIF(NormalizedName,''),Name))=? LIMIT 1", ('ADMINISTRATOR',)).fetchone()
rid = str(role_row['Id']) if role_row else str(uuid.uuid4())
role_values = {
    'Id': rid, 'Name': 'Administrator', 'NormalizedName': 'ADMINISTRATOR',
    'ConcurrencyStamp': str(uuid.uuid4()), 'CreatedById': None, 'CreatedOn': now,
    'UpdatedById': None, 'UpdatedOn': now,
}

# Reserved identity lookup is by normalized username only. This intentionally
# does not borrow an arbitrary existing administrator's credential.
user_row = con.execute("SELECT * FROM Users WHERE upper(COALESCE(NULLIF(NormalizedUserName,''),UserName))=? LIMIT 1", (normalized,)).fetchone()
uid = str(user_row['Id']) if user_row else str(uuid.uuid4())

# Avoid taking an email already owned by another account. Identity's Email is
# nullable on the pinned schema; if it ever becomes required, schema validation
# will fail closed instead of inventing a destructive migration.
email = f'{username}@pcga.invalid'
email_owner = None
if 'NormalizedEmail' in uc:
    email_owner = con.execute('SELECT Id FROM Users WHERE upper(COALESCE(NormalizedEmail,\'\'))=? AND Id<>? LIMIT 1', (email.upper(), uid)).fetchone()
chosen_email = None if email_owner else email

user_values = {
    'Id': uid,
    'UserName': username,
    'NormalizedUserName': normalized,
    'PasswordHash': identity_hash(password),
    'SecurityStamp': str(uuid.uuid4()),
    'ConcurrencyStamp': str(uuid.uuid4()),
    'Approved': 1,
    'ApprovedOn': now,
    'AccessFailedCount': 0,
    'Email': chosen_email,
    'NormalizedEmail': chosen_email.upper() if chosen_email else None,
    'EmailConfirmed': 0,
    'PhoneNumber': None,
    'PhoneNumberConfirmed': 0,
    'TwoFactorEnabled': 0,
    'LockoutEnd': None,
    'LockoutEnabled': 1,
    'Alias': 'PCGA Appliance',
    'RefreshToken': '',
    'RefreshTokenExpiration': expired_refresh,
    'CreatedById': None,
    'CreatedOn': now,
    'UpdatedById': None,
    'UpdatedOn': now,
}
userrole_values = {
    'UserId': uid, 'RoleId': rid, 'CreatedById': None, 'CreatedOn': now,
    'UpdatedById': None, 'UpdatedOn': now,
}

try:
    verify_required('Users', uc, user_values, known_user)
    verify_required('Roles', rc, role_values, known_role)
    verify_required('UserRoles', urc, userrole_values, known_userrole)
except ValueError as exc:
    con.close(); print(f'LANCommander bootstrap schema validation failed: {exc}', file=sys.stderr); raise SystemExit(32)

try:
    con.execute('BEGIN IMMEDIATE')
    if not role_row:
        vals = filtered(role_values, rc)
        keys = list(vals)
        con.execute(f'INSERT INTO Roles ({",".join(keys)}) VALUES ({",".join("?" for _ in keys)})', [vals[k] for k in keys])
    elif 'NormalizedName' in rc and not (role_row['NormalizedName'] or ''):
        con.execute('UPDATE Roles SET NormalizedName=? WHERE Id=?', ('ADMINISTRATOR', rid))

    if user_row:
        # Reconcile only the reserved account. Preserve unrelated profile fields,
        # but repair everything required for deterministic local authentication.
        updates = {
            'UserName': username,
            'NormalizedUserName': normalized,
            'PasswordHash': user_values['PasswordHash'],
            'SecurityStamp': user_values['SecurityStamp'],
            'ConcurrencyStamp': user_values['ConcurrencyStamp'],
            'Approved': 1,
            'ApprovedOn': user_row['ApprovedOn'] if 'ApprovedOn' in uc and user_row['ApprovedOn'] else now,
            'AccessFailedCount': 0,
            'LockoutEnd': None,
            'UpdatedOn': now,
        }
        if 'Alias' in uc and not (user_row['Alias'] if 'Alias' in user_row.keys() else None):
            updates['Alias'] = 'PCGA Appliance'
        if chosen_email and 'Email' in uc and not (user_row['Email'] if 'Email' in user_row.keys() else None):
            updates['Email'] = chosen_email
            if 'NormalizedEmail' in uc: updates['NormalizedEmail'] = chosen_email.upper()
        vals = filtered(updates, uc, include_none=True)
        con.execute('UPDATE Users SET ' + ','.join(f'"{k}"=?' for k in vals) + ' WHERE Id=?', [*vals.values(), uid])
    else:
        vals = filtered(user_values, uc)
        keys = list(vals)
        con.execute(f'INSERT INTO Users ({",".join(keys)}) VALUES ({",".join("?" for _ in keys)})', [vals[k] for k in keys])

    membership = con.execute('SELECT 1 FROM UserRoles WHERE UserId=? AND RoleId=? LIMIT 1', (uid, rid)).fetchone()
    if not membership:
        vals = filtered(userrole_values, urc)
        keys = list(vals)
        con.execute(f'INSERT INTO UserRoles ({",".join(keys)}) VALUES ({",".join("?" for _ in keys)})', [vals[k] for k in keys])
    con.commit()
except (sqlite3.Error, ValueError) as exc:
    con.rollback(); con.close(); print(f'LANCommander bootstrap transaction failed: {exc}', file=sys.stderr); raise SystemExit(33)

# Verify the exact postcondition before letting LANCommander reopen the DB.
row = con.execute(
    'SELECT u.PasswordHash,u.Approved FROM Users u JOIN UserRoles ur ON ur.UserId=u.Id '
    'JOIN Roles r ON r.Id=ur.RoleId WHERE upper(u.NormalizedUserName)=? '
    'AND upper(r.NormalizedName)=? LIMIT 1', (normalized, 'ADMINISTRATOR')
).fetchone()
if not row or int(row['Approved'] or 0) != 1 or not identity_verify(str(row['PasswordHash'] or ''), password):
    con.close(); print('LANCommander reserved identity verification failed after transaction', file=sys.stderr); raise SystemExit(34)
con.close()
print('reconciled')
PYDB
rc=$?
set -e

if [[ $rc -ne 0 ]]; then
  cp -a "$backup" "$db"
  fail "LANCommander reserved identity reconciliation failed (exit $rc); database restored from $backup"
fi

# Restart and require both application readiness and the absence of onboarding.
docker start lancommander >/dev/null || fail "Unable to restart LANCommander after bootstrap"
restart_on_exit=0
trap - EXIT
wait_http || fail "LANCommander did not become HTTP-ready after identity reconciliation"
if probe_setup; then
  fail "LANCommander still reports first-time setup after PCGA identity reconciliation; backup retained at $backup"
fi

# Read-only second-pass verification catches a database path mismatch or an app
# migration that replaced/rewrote the identity schema during startup.
if ! python3 - "$db" "$PCGA_LANCOMMANDER_ADMIN_USER" <<'PYVERIFY'
import sqlite3,sys
p,u=sys.argv[1:]
c=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
r=c.execute(
 'SELECT 1 FROM Users u JOIN UserRoles ur ON ur.UserId=u.Id JOIN Roles r ON r.Id=ur.RoleId '
 'WHERE upper(u.NormalizedUserName)=? AND upper(r.NormalizedName)=? AND u.Approved=1 LIMIT 1',
 (u.upper(),'ADMINISTRATOR')).fetchone()
c.close(); raise SystemExit(0 if r else 1)
PYVERIFY
then
  fail "LANCommander restarted but the verified PCGA administrator identity is no longer present"
fi

# Publish the catalog DB path for the read-only portal sidecar.  Identity and
# catalog data normally live in the same SQLite database, but discovering by
# schema instead of filename keeps this robust across LANCommander layouts.
# The pointer is relative to /app/Data so it remains valid in pcga-status where
# the same host directory is mounted at /pcga/lancommander.
catalog_rel="$(python3 - "$DATA" "$db" <<'PYCATALOG'
from pathlib import Path
import os, sqlite3, sys
root=Path(sys.argv[1]).resolve(strict=False)
identity=Path(sys.argv[2]).resolve(strict=False)
pruned={'uploads','media','saves','steam','archives','files','cache','downloads'}

def is_sqlite(p):
    try:
        with p.open('rb') as f:
            return f.read(16) == b'SQLite format 3\x00'
    except OSError:
        return False

def tables(p):
    try:
        c=sqlite3.connect(f'file:{p}?mode=ro', uri=True, timeout=.5)
        try: return {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        finally: c.close()
    except sqlite3.Error:
        return set()

candidates=[]
if identity.is_file(): candidates.append(identity)
try:
    for current, dirs, files in os.walk(root):
        cur=Path(current)
        try: depth=len(cur.relative_to(root).parts)
        except ValueError: continue
        dirs[:] = [d for d in dirs if d.lower() not in pruned and depth < 4]
        if depth > 4:
            dirs[:] = []
            continue
        for name in files:
            q=cur/name
            if q not in candidates and (q.suffix.lower() in {'.db','.sqlite','.sqlite3'} or is_sqlite(q)):
                candidates.append(q)
except OSError:
    pass

best=None; best_score=-1
for q in candidates:
    ts=tables(q)
    if 'Games' not in ts:
        continue
    score=100 + 10*('Archives' in ts) + 10*('StorageLocations' in ts) + 2*('Media' in ts) + ('Users' in ts)
    if score > best_score:
        best, best_score=q, score
if best is not None:
    try: print(best.relative_to(root).as_posix())
    except ValueError: pass
PYCATALOG
)"
if [[ -n "$catalog_rel" ]]; then
  printf '%s\n' "$catalog_rel" >"$CATALOG_PTR"
  chmod 0644 "$CATALOG_PTR"
  printf '[pcga-lancommander-bootstrap] Published LANCommander catalog path: %s\n' "$catalog_rel"
else
  rm -f "$CATALOG_PTR"
  printf '[pcga-lancommander-bootstrap:warn] LANCommander identity is ready but no SQLite Games catalog was discoverable yet; portal diagnostics will retry dynamically.\n' >&2
fi

state ready
printf '[pcga-lancommander-bootstrap] LANCommander appliance identity is ready; existing users were preserved.\n'

PCGA_LAN_BOOTSTRAP
chmod 0755 /usr/local/sbin/pcga-lancommander-bootstrap

cat > /usr/local/sbin/pcga-jellyfin-configure <<'JELLYFIN_HELPER'
#!/usr/bin/env bash
# Configure PC Game Archive-managed Jellyfin libraries through Jellyfin's HTTP API.
# This intentionally does not edit Jellyfin's database or XML files directly.
set -Eeuo pipefail
IFS=$'\n\t'

VERSION="0.10.0"
STACK_DIR="/opt/pc-game-archive"
TOKEN_FILE="/etc/pc-game-archive/jellyfin-api-key"
BASE_URL=""
USERNAME=""
PASSWORD=""
PASSWORD_STDIN=0
NON_INTERACTIVE=0
SAVE_TOKEN=1
RESTART_JELLYFIN=1
AUDIT_ONLY=0
REPAIR_ADMIN=0
RESET_FRESH=0
EXACT_PATHS=1
APPLIANCE_CREDS=/etc/pc-game-archive/secrets/appliance-admin.env
if [[ -x /usr/local/sbin/pcga-appliance-credentials ]]; then /usr/local/sbin/pcga-appliance-credentials >/dev/null; fi
if [[ -r "$APPLIANCE_CREDS" ]]; then
  # shellcheck disable=SC1090
  . "$APPLIANCE_CREDS"
fi
DEFAULT_ADMIN_USER="${PCGA_JELLYFIN_ADMIN_USER:-${PCGA_APPLIANCE_ADMIN_USER:-pcga-admin}}"
DEFAULT_ADMIN_PASSWORD="${PCGA_JELLYFIN_ADMIN_PASSWORD:-${PCGA_APPLIANCE_ADMIN_PASSWORD:-}}"

log()  { printf '[jellyfin-config] %s\n' "$*"; }
warn() { printf '[jellyfin-config] WARNING: %s\n' "$*" >&2; }
die()  { printf '[jellyfin-config] ERROR: %s\n' "$*" >&2; exit 1; }

usage() {
  cat <<'USAGE'
Usage: sudo pcga-jellyfin-configure [options]

Ensures the PC Game Archive Jellyfin libraries use these container paths:
  Movies      -> /media/movies
  TV Shows    -> /media/tv
  Music       -> /media/music
  Home Videos -> /media/home-videos
  Photos      -> /media/photos

Options:
  --url URL             Jellyfin base URL (default: http://127.0.0.1:<configured-port>)
  --username USER       Jellyfin administrator username
  --password-stdin      Read Jellyfin administrator password from stdin
  --token-file PATH     Persistent token file (default: /etc/pc-game-archive/jellyfin-api-key)
  --no-save-token       Do not save a token obtained by username/password authentication
  --non-interactive     Never prompt for credentials
  --no-restart          Apply/verify paths without restarting the Jellyfin container
  --keep-extra-paths    Keep additional paths already attached to managed libraries
  --audit               Show current public info, mounts and library paths; do not change anything
  --repair-admin        Disabled legacy recovery path; use --reset-fresh instead
  --reset-fresh         Back up Jellyfin app state, recreate it fresh, then provision admin/pass
  -h, --help            Show this help

Authentication priority:
  1. JELLYFIN_API_KEY environment variable
  2. --token-file contents
  3. --username plus --password-stdin
  4. interactive username/password prompt

On a brand-new Jellyfin server, the helper automatically completes first-run setup
with the PCGA appliance administrator from /etc/pc-game-archive/secrets/appliance-admin.env
(overridable with PCGA_JELLYFIN_ADMIN_USER / PCGA_JELLYFIN_ADMIN_PASSWORD). Existing
initialized servers are never reset by this helper.
USAGE
}

while (($#)); do
  case "$1" in
    --url) [[ $# -ge 2 ]] || die "--url requires a value"; BASE_URL="$2"; shift 2 ;;
    --username) [[ $# -ge 2 ]] || die "--username requires a value"; USERNAME="$2"; shift 2 ;;
    --password-stdin) PASSWORD_STDIN=1; shift ;;
    --token-file) [[ $# -ge 2 ]] || die "--token-file requires a path"; TOKEN_FILE="$2"; shift 2 ;;
    --no-save-token) SAVE_TOKEN=0; shift ;;
    --non-interactive) NON_INTERACTIVE=1; shift ;;
    --no-restart) RESTART_JELLYFIN=0; shift ;;
    --keep-extra-paths) EXACT_PATHS=0; shift ;;
    --audit) AUDIT_ONLY=1; RESTART_JELLYFIN=0; shift ;;
    --repair-admin) REPAIR_ADMIN=1; shift ;;
    --reset-fresh) RESET_FRESH=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) die "Unknown option: $1" ;;
  esac
done

[[ $EUID -eq 0 ]] || die "Run as root (sudo)."
command -v curl >/dev/null || die "curl is required"
command -v jq >/dev/null || die "jq is required"
command -v docker >/dev/null || die "docker is required"

JELLYFIN_PORT="8096"
if [[ -r "$STACK_DIR/.env" ]]; then
  p="$(awk -F= '$1=="JELLYFIN_PORT" {print substr($0,index($0,"=")+1)}' "$STACK_DIR/.env" | tail -n1)"
  [[ -n "$p" ]] && JELLYFIN_PORT="$p"
fi
[[ -n "$BASE_URL" ]] || BASE_URL="http://127.0.0.1:${JELLYFIN_PORT}"
BASE_URL="${BASE_URL%/}"

CLIENT_AUTH='MediaBrowser Client="PCGameArchive", Device="PCGameArchiveServer", DeviceId="pcga-local", Version="0.10.0"'
TOKEN="${JELLYFIN_API_KEY:-}"
if [[ -z "$TOKEN" && -r "$TOKEN_FILE" ]]; then
  TOKEN="$(tr -d '\r\n' < "$TOKEN_FILE")"
fi

# Managed library name | Jellyfin collection type | in-container path
LIBRARIES=(
  $'Movies\tmovies\t/media/movies'
  $'TV Shows\ttvshows\t/media/tv'
  $'Music\tmusic\t/media/music'
  $'Home Videos\thomevideos\t/media/home-videos'
  $'Photos\tphotos\t/media/photos'
)

base_headers=(
  -H "Accept: application/json"
)

client_headers() {
  CLIENT_HEADERS=("${base_headers[@]}" -H "Authorization: $CLIENT_AUTH")
}

auth_headers() {
  if [[ -n "$TOKEN" ]]; then
    AUTH_HEADERS=("${base_headers[@]}" -H "Authorization: ${CLIENT_AUTH}, Token=\"${TOKEN}\"")
  else
    AUTH_HEADERS=("${base_headers[@]}" -H "Authorization: $CLIENT_AUTH")
  fi
  return 0
}

wait_for_jellyfin() {
  # Jellyfin can accept TCP/HTTP requests before its database-backed API is
  # fully ready.  /health is the server's supported readiness endpoint; require
  # several consecutive healthy responses plus PublicSystemInfo before
  # declaring startup complete.
  local tries=90 consecutive=0
  while (( tries-- > 0 )); do
    if curl -fsS --connect-timeout 2 --max-time 5 "${BASE_URL}/health" >/dev/null 2>&1 \
      && curl -fsS --connect-timeout 2 --max-time 5 "${BASE_URL}/System/Info/Public" >/dev/null 2>&1; then
      consecutive=$((consecutive + 1))
      if (( consecutive >= 3 )); then
        return 0
      fi
    else
      consecutive=0
    fi
    sleep 2
  done
  return 1
}

wait_for_authenticated_jellyfin() {
  # After a restart, do not merely wait for the public endpoint.  Make sure the
  # saved token can reach the library API as well; this prevents a refresh from
  # racing Jellyfin's database initialization/migrations.
  [[ -n "${TOKEN:-}" ]] || return 1
  local tries=90 consecutive=0
  while (( tries-- > 0 )); do
    auth_headers
    if curl -fsS --connect-timeout 2 --max-time 5 "${BASE_URL}/health" >/dev/null 2>&1 \
      && curl -fsS --connect-timeout 3 --max-time 10 "${AUTH_HEADERS[@]}" "${BASE_URL}/Library/VirtualFolders" >/dev/null 2>&1; then
      consecutive=$((consecutive + 1))
      if (( consecutive >= 3 )); then
        return 0
      fi
    else
      consecutive=0
    fi
    sleep 2
  done
  return 1
}

get_public_info() {
  curl -fsS --connect-timeout 3 --max-time 10 "${BASE_URL}/System/Info/Public"
}

startup_wizard_state() {
  local info
  info="$(get_public_info)" || { printf 'unknown\n'; return 0; }
  jq -r 'if has("StartupWizardCompleted") then (if .StartupWizardCompleted then "complete" else "incomplete" end) else "unknown" end' <<<"$info"
}

# Jellyfin 12.x's startup POST expects the initial user to already exist.
# GET /Startup/User calls IUserManager.InitializeAsync(), which creates/loads
# that first user on a genuinely fresh database.  Skipping this GET causes
# POST /Startup/User to return 404 Not Found.
initialize_startup_user() {
  local tmp code name tries=15
  tmp="$(mktemp)"
  while (( tries-- > 0 )); do
    code="$(curl -sS --connect-timeout 3 --max-time 20 \
      -o "$tmp" -w '%{http_code}' "${BASE_URL}/Startup/User" 2>/dev/null || true)"
    if [[ "$code" == "200" ]]; then
      name="$(jq -r '.Name // empty' "$tmp" 2>/dev/null || true)"
      rm -f "$tmp"
      if [[ -n "$name" ]]; then
        log "Initialized Jellyfin startup user (current name: $name)."
      else
        log "Initialized Jellyfin startup user."
      fi
      return 0
    fi
    sleep 1
  done
  rm -f "$tmp"
  return 1
}

save_token() {
  [[ $SAVE_TOKEN -eq 1 && -n "$TOKEN" ]] || return 0
  install -d -m 0700 "$(dirname "$TOKEN_FILE")"
  umask 077
  printf '%s\n' "$TOKEN" > "$TOKEN_FILE"
  chmod 0600 "$TOKEN_FILE"
  chown root:root "$TOKEN_FILE" 2>/dev/null || true
  log "Saved a root-only Jellyfin token at $TOKEN_FILE"
}

authenticate_credentials() {
  local user="$1" pass="$2" auth_json response
  auth_json="$(jq -nc --arg u "$user" --arg p "$pass" '{Username:$u,Pw:$p}')"
  client_headers
  response="$(curl -fsS --connect-timeout 3 --max-time 20 \
    -X POST "${CLIENT_HEADERS[@]}" -H 'Content-Type: application/json' \
    --data "$auth_json" "${BASE_URL}/Users/AuthenticateByName")" || return 1
  TOKEN="$(jq -r '.AccessToken // empty' <<<"$response")"
  [[ -n "$TOKEN" ]] || return 1
  USERNAME="$user"
  save_token
  return 0
}

provision_fresh_server() {
  local startup_state
  startup_state="$(startup_wizard_state)"
  case "$startup_state" in
    complete) return 0 ;;
    incomplete) ;;
    *) die "Could not safely determine Jellyfin startup-wizard state; refusing to modify administrator accounts." ;;
  esac

  log "Fresh Jellyfin installation detected; provisioning administrator '$DEFAULT_ADMIN_USER'"

  local user_json remote_json
  initialize_startup_user \
    || die "Jellyfin did not initialize its first startup user; refusing to POST startup credentials."
  user_json="$(jq -nc --arg n "$DEFAULT_ADMIN_USER" --arg p "$DEFAULT_ADMIN_PASSWORD" '{Name:$n,Password:$p}')"
  curl -fsS --connect-timeout 3 --max-time 20 \
    -X POST -H 'Content-Type: application/json' \
    --data "$user_json" "${BASE_URL}/Startup/User" >/dev/null \
    || die "Could not create Jellyfin's initial administrator account."

  # This appliance is intended to remain LAN-only. Disable Internet-facing
  # remote access and automatic UPnP port mapping during first-run setup.
  remote_json='{"EnableRemoteAccess":false,"EnableAutomaticPortMapping":false}'
  if ! curl -fsS --connect-timeout 3 --max-time 20 \
      -X POST -H 'Content-Type: application/json' \
      --data "$remote_json" "${BASE_URL}/Startup/RemoteAccess" >/dev/null; then
    warn "Could not set Jellyfin remote-access defaults; continuing with wizard completion."
  fi

  curl -fsS --connect-timeout 3 --max-time 20 \
    -X POST -H 'Content-Type: application/json' --data '{}' \
    "${BASE_URL}/Startup/Complete" >/dev/null \
    || die "Could not complete Jellyfin's startup wizard."

  # The server can take a moment to switch from startup mode to normal auth.
  sleep 2
  wait_for_jellyfin || die "Jellyfin did not return after first-run provisioning."
  [[ "$(startup_wizard_state)" == "complete" ]] || die "Jellyfin still reports its startup wizard as incomplete."

  authenticate_credentials "$DEFAULT_ADMIN_USER" "$DEFAULT_ADMIN_PASSWORD" \
    || die "Jellyfin was provisioned, but login with the configured administrator failed."
  log "Jellyfin first-run provisioning complete."
  warn "Jellyfin is using the requested default password 'pass'. Keep this service LAN-only and change the password when convenient."
}

jellyfin_config_source() {
  docker inspect jellyfin --format '{{range .Mounts}}{{if eq .Destination "/config"}}{{.Source}}{{end}}{{end}}' 2>/dev/null
}

repair_admin_account() {
  die "The old startup-mode repair path is disabled in v0.10.0 because Jellyfin 12 couples startup-wizard state to other initialization behavior. Use: sudo game-archive jellyfin-reset-fresh"
}

reset_fresh_instance() {
  local config_root archive_root ts backup_dir uid gid mode
  config_root="$(jellyfin_config_source)"
  [[ -n "$config_root" && -d "$config_root" ]] || die "Could not determine Jellyfin's host /config mount."
  archive_root="$(cat /etc/pc-game-archive/archive-root 2>/dev/null || printf '/srv/pc-game-archive')"
  ts="$(date +%Y%m%d-%H%M%S)"
  backup_dir="${archive_root}/backups/jellyfin-fresh-reset-${ts}"
  uid="$(stat -c %u "$config_root")"
  gid="$(stat -c %g "$config_root")"
  mode="$(stat -c %a "$config_root")"

  log "Stopping Jellyfin for a clean application-state backup"
  docker stop jellyfin >/dev/null 2>&1 || true
  install -d -m 0700 "$backup_dir/config"
  cp -a "$config_root/." "$backup_dir/config/"
  log "Backed up the entire Jellyfin /config tree to $backup_dir/config"

  rollback_reset() {
    warn "Fresh Jellyfin provisioning failed; restoring the previous Jellyfin /config tree."
    docker stop jellyfin >/dev/null 2>&1 || true
    find "$config_root" -mindepth 1 -maxdepth 1 -exec rm -rf -- {} +
    cp -a "$backup_dir/config/." "$config_root/"
    chown "$uid:$gid" "$config_root" 2>/dev/null || true
    chmod "$mode" "$config_root" 2>/dev/null || true
    docker start jellyfin >/dev/null 2>&1 || true
    wait_for_jellyfin >/dev/null 2>&1 || true
  }

  find "$config_root" -mindepth 1 -maxdepth 1 -exec rm -rf -- {} +
  chown "$uid:$gid" "$config_root"
  chmod "$mode" "$config_root"
  rm -f "$TOKEN_FILE"
  TOKEN=""

  if ! docker start jellyfin >/dev/null 2>&1; then
    rollback_reset
    die "Could not start Jellyfin with a fresh /config tree. Previous state was restored from $backup_dir/config"
  fi
  if ! wait_for_jellyfin; then
    rollback_reset
    die "Fresh Jellyfin did not become reachable. Previous state was restored from $backup_dir/config"
  fi
  if [[ "$(startup_wizard_state)" != "incomplete" ]]; then
    rollback_reset
    die "Fresh Jellyfin did not report startup mode. Previous state was restored from $backup_dir/config"
  fi

  local user_json remote_json
  if ! initialize_startup_user; then
    rollback_reset
    die "Fresh Jellyfin did not initialize its first startup user. Previous state was restored from $backup_dir/config"
  fi
  user_json="$(jq -nc --arg n "$DEFAULT_ADMIN_USER" --arg p "$DEFAULT_ADMIN_PASSWORD" '{Name:$n,Password:$p}')"
  if ! curl -fsS --connect-timeout 3 --max-time 20 -X POST -H 'Content-Type: application/json' \
      --data "$user_json" "${BASE_URL}/Startup/User" >/dev/null; then
    rollback_reset
    die "Jellyfin rejected fresh startup-user provisioning. Previous state was restored from $backup_dir/config"
  fi

  remote_json='{"EnableRemoteAccess":false,"EnableAutomaticPortMapping":false}'
  curl -fsS --connect-timeout 3 --max-time 20 -X POST -H 'Content-Type: application/json' \
      --data "$remote_json" "${BASE_URL}/Startup/RemoteAccess" >/dev/null || true

  if ! curl -fsS --connect-timeout 3 --max-time 20 -X POST -H 'Content-Type: application/json' \
      --data '{}' "${BASE_URL}/Startup/Complete" >/dev/null; then
    rollback_reset
    die "Jellyfin could not complete fresh setup. Previous state was restored from $backup_dir/config"
  fi

  sleep 2
  if ! wait_for_jellyfin || [[ "$(startup_wizard_state)" != "complete" ]]; then
    rollback_reset
    die "Jellyfin did not settle after fresh setup. Previous state was restored from $backup_dir/config"
  fi

  if ! authenticate_credentials "$DEFAULT_ADMIN_USER" "$DEFAULT_ADMIN_PASSWORD"; then
    rollback_reset
    die "Fresh setup completed but admin/pass did not authenticate. Previous state was restored from $backup_dir/config"
  fi

  log "Fresh Jellyfin application state created successfully."
  log "Administrator: $DEFAULT_ADMIN_USER"
  log "The previous Jellyfin application state remains backed up at: $backup_dir/config"
}

try_get_libraries() {
  local outfile="$1" code
  auth_headers
  code="$(curl -sS --connect-timeout 3 --max-time 15 \
    -o "$outfile" -w '%{http_code}' \
    "${AUTH_HEADERS[@]}" "${BASE_URL}/Library/VirtualFolders" || true)"
  [[ "$code" == "200" ]]
}

authenticate_if_needed() {
  local tmp
  tmp="$(mktemp)"

  if try_get_libraries "$tmp"; then
    rm -f "$tmp"
    return 0
  fi

  if [[ -n "$TOKEN" ]]; then
    warn "Saved/provided Jellyfin token was rejected; trying administrator authentication."
    TOKEN=""
  fi

  # On a completed appliance setup, prefer the requested default admin
  # credentials before prompting. This does NOT create/reset users on an
  # already-initialized Jellyfin server; it only attempts normal login.
  if [[ -z "$TOKEN" && -z "$USERNAME" && $PASSWORD_STDIN -eq 0 ]]; then
    if authenticate_credentials "$DEFAULT_ADMIN_USER" "$DEFAULT_ADMIN_PASSWORD"; then
      if try_get_libraries "$tmp"; then
        rm -f "$tmp"
        return 0
      fi
    fi
    TOKEN=""
  fi

  if [[ -z "$TOKEN" ]]; then
    if [[ $PASSWORD_STDIN -eq 1 ]]; then
      IFS= read -r PASSWORD
    elif [[ $NON_INTERACTIVE -eq 0 && -t 0 ]]; then
      [[ -n "$USERNAME" ]] || read -r -p 'Jellyfin admin username: ' USERNAME
      read -r -s -p 'Jellyfin admin password: ' PASSWORD
      printf '\n'
    fi

    if [[ -n "$USERNAME" ]]; then
      authenticate_credentials "$USERNAME" "$PASSWORD" \
        || die "Jellyfin authentication failed for user '$USERNAME'. If this is the new appliance with no data to preserve, run: sudo game-archive jellyfin-reset-fresh"
    fi
  fi

  if ! try_get_libraries "$tmp"; then
    rm -f "$tmp"
    if [[ $NON_INTERACTIVE -eq 1 ]]; then
      die "Jellyfin is already initialized and the saved/default credentials did not authenticate. Run 'sudo game-archive jellyfin-configure' interactively once."
    fi
    die "Unable to access Jellyfin's library-management API."
  fi
  rm -f "$tmp"
}

urlenc() { jq -nr --arg v "$1" '$v|@uri'; }

get_libraries() {
  auth_headers
  local tries=15
  while (( tries-- > 0 )); do
    if curl -fsS --connect-timeout 3 --max-time 20 "${AUTH_HEADERS[@]}" "${BASE_URL}/Library/VirtualFolders"; then
      return 0
    fi
    sleep 2
  done
  return 1
}

add_library() {
  local name="$1" ctype="$2" path="$3" url
  url="${BASE_URL}/Library/VirtualFolders?name=$(urlenc "$name")&collectionType=$(urlenc "$ctype")&paths=$(urlenc "$path")&refreshLibrary=false"
  auth_headers
  curl -fsS -X POST "${AUTH_HEADERS[@]}" "$url" >/dev/null
  log "Created library '$name' -> $path"
}

add_media_path() {
  local name="$1" path="$2" body
  body="$(jq -nc --arg n "$name" --arg p "$path" '{Name:$n,Path:$p}')"
  auth_headers
  curl -fsS -X POST "${AUTH_HEADERS[@]}" -H 'Content-Type: application/json' \
    --data "$body" "${BASE_URL}/Library/VirtualFolders/Paths?refreshLibrary=false" >/dev/null
  log "Added '$path' to '$name'"
}

remove_media_path() {
  local name="$1" path="$2" url
  url="${BASE_URL}/Library/VirtualFolders/Paths?name=$(urlenc "$name")&path=$(urlenc "$path")&refreshLibrary=false"
  auth_headers
  curl -fsS -X DELETE "${AUTH_HEADERS[@]}" "$url" >/dev/null
  log "Removed stale path '$path' from '$name'"
}

refresh_library() {
  auth_headers
  local tries=15
  while (( tries-- > 0 )); do
    if curl -fsS --connect-timeout 3 --max-time 20 -X POST "${AUTH_HEADERS[@]}" "${BASE_URL}/Library/Refresh" >/dev/null; then
      return 0
    fi
    sleep 2
  done
  return 1
}

show_audit() {
  local info libs
  info="$(get_public_info)"
  printf 'Jellyfin URL: %s\n' "$BASE_URL"
  printf 'Version: %s\n' "$(jq -r '.Version // "unknown"' <<<"$info")"
  printf 'Startup wizard complete: %s\n' "$(jq -r '.StartupWizardCompleted // "unknown"' <<<"$info")"
  echo
  echo 'Container mounts:'
  docker inspect jellyfin --format '{{range .Mounts}}{{println .Destination "<-" .Source}}{{end}}' 2>/dev/null || true
  echo
  authenticate_if_needed
  libs="$(get_libraries)"
  echo 'Jellyfin libraries:'
  jq -r '.[] | "- \(.Name // "unnamed") [\(.CollectionType // "unknown")]: \((.Locations // []) | join(", "))"' <<<"$libs"
}

if [[ $RESET_FRESH -eq 1 ]]; then
  reset_fresh_instance
else
  wait_for_jellyfin || die "Jellyfin did not become reachable at $BASE_URL"
fi

if [[ $REPAIR_ADMIN -eq 1 ]]; then
  repair_admin_account
fi

if [[ $AUDIT_ONLY -eq 1 ]]; then
  show_audit
  exit 0
fi

provision_fresh_server
authenticate_if_needed

# Verify the compose mounts exist inside the running container before touching
# Jellyfin's library definitions. This catches host/container path mismatches.
for spec in "${LIBRARIES[@]}"; do
  IFS=$'\t' read -r name ctype path <<<"$spec"
  docker exec jellyfin test -d "$path" \
    || die "Jellyfin container cannot see $path. Fix the Docker volume mount before changing the library database."
done

changed=0
for spec in "${LIBRARIES[@]}"; do
  IFS=$'\t' read -r name ctype target <<<"$spec"
  libs="$(get_libraries)"
  obj="$(jq -c --arg n "$name" '[.[] | select(.Name == $n)][0] // empty' <<<"$libs")"

  if [[ -z "$obj" ]]; then
    add_library "$name" "$ctype" "$target"
    changed=1
    continue
  fi

  existing_type="$(jq -r '.CollectionType // empty' <<<"$obj")"
  if [[ -n "$existing_type" && "$existing_type" != "$ctype" ]]; then
    warn "Library '$name' has type '$existing_type' (expected '$ctype'); preserving its type and only managing its paths."
  fi

  if ! jq -e --arg p "$target" '(.Locations // []) | index($p) != null' <<<"$obj" >/dev/null; then
    add_media_path "$name" "$target"
    changed=1
  fi

  if [[ $EXACT_PATHS -eq 1 ]]; then
    while IFS= read -r old; do
      [[ -n "$old" && "$old" != "$target" ]] || continue
      remove_media_path "$name" "$old"
      changed=1
    done < <(jq -r '.Locations[]? // empty' <<<"$obj")
  fi
done

if [[ $RESTART_JELLYFIN -eq 1 ]]; then
  log "Restarting Jellyfin"
  docker restart jellyfin >/dev/null
  wait_for_jellyfin || die "Jellyfin did not become healthy after restart"
  wait_for_authenticated_jellyfin || die "Jellyfin became healthy, but its authenticated library API did not become ready after restart"
  log "Jellyfin is healthy and its authenticated library API is ready"
fi

# Refresh after the restart so the scan is not interrupted by the restart.
if refresh_library; then
  log "Requested a Jellyfin library refresh"
else
  warn "Could not request the post-restart library refresh; paths were still applied."
fi

libs="$(get_libraries)"
echo
log "Managed library paths now are:"
for spec in "${LIBRARIES[@]}"; do
  IFS=$'\t' read -r name ctype target <<<"$spec"
  actual="$(jq -r --arg n "$name" '[.[] | select(.Name == $n)][0].Locations // [] | join(", ")' <<<"$libs")"
  printf '  %-12s %s\n' "$name:" "$actual"
done

if [[ $changed -eq 0 ]]; then
  log "No path changes were necessary; Jellyfin was still restarted/refreshed as requested."
fi
JELLYFIN_HELPER
chmod 0755 /usr/local/sbin/pcga-jellyfin-configure

# ----- Manual media review --------------------------------------------------
cat > /usr/local/sbin/pcga-manual-review <<'PCGA_MANUAL_REVIEW'
#!/usr/bin/env python3
"""PC Game Archive manual media review and promotion service.

Queues:
  <root>/media/metadata-pending
  <root>/media/quarantine/unidentified

Destinations:
  <root>/media/library/{movies,tv,music,home-videos}

The service deliberately never touches ARM raw/transcode/completed staging.
"""
from __future__ import annotations

import argparse
import base64
import datetime as dt
import html
import http.cookies
import json
import os
import re
import secrets
import shutil
import subprocess
import sys
import urllib.parse
import urllib.request
from dataclasses import dataclass
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Iterable

VERSION = "0.17.53"
ROOT_FILE = Path("/etc/pc-game-archive/archive-root")
TOKEN_FILE = Path("/etc/pc-game-archive/manual-review-token")
CONF_FILE = Path("/etc/pc-game-archive/manual-review.conf")
JELLYFIN_TOKEN_FILE = Path("/etc/pc-game-archive/jellyfin-api-key")
STACK_ENV = Path("/opt/pc-game-archive/.env")
MEDIA_EXTS = {
    ".mkv", ".mp4", ".m4v", ".avi", ".mov", ".webm", ".ts", ".m2ts", ".mpg", ".mpeg", ".vob",
    ".mp3", ".flac", ".wav", ".m4a", ".aac", ".ogg", ".opus", ".wma",
}
VIDEO_EXTS = {".mkv", ".mp4", ".m4v", ".avi", ".mov", ".webm", ".ts", ".m2ts", ".mpg", ".mpeg", ".vob"}
AUDIO_EXTS = MEDIA_EXTS - VIDEO_EXTS
IMAGE_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.bmp', '.gif'}
PREVIEW_CLIP_SECONDS = 20
TIMESTAMP_PREFIX = re.compile(r"^\d{8}-\d{6}-")
ARM_SUFFIX = re.compile(r"_\d{9,}$")
YEAR_RE = re.compile(r"\((19\d{2}|20\d{2})\)")
EPISODE_TOKEN_PATTERNS = [
    re.compile(r"(?i)(?:^|[ ._\-])s(?P<season>\d{1,2})e(?P<episode>\d{1,3})(?:[ ._\-]*e(?P<episode_end>\d{1,3}))?(?=$|[ ._\-])"),
    re.compile(r"(?i)(?:^|[ ._\-])(?P<season>\d{1,2})x(?P<episode>\d{1,3})(?=$|[ ._\-])"),
]


def log(message: str) -> None:
    print(f"[manual-review] {message}")
    try:
        subprocess.run(["logger", "-t", "PCGA-REVIEW", "--", message], check=False,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def archive_root() -> Path:
    override = os.environ.get("PCGA_ROOT_OVERRIDE")
    if override:
        root = Path(override)
    elif ROOT_FILE.is_file():
        root = Path(ROOT_FILE.read_text(encoding="utf-8").strip())
    else:
        root = Path("/srv/pc-game-archive")
    if not root.is_absolute():
        raise RuntimeError(f"archive root must be absolute: {root}")
    return root.resolve()


def queue_roots(root: Path) -> list[tuple[str, Path]]:
    return [
        ("metadata-pending", root / "media/metadata-pending"),
        ("quarantine", root / "media/quarantine/unidentified"),
        ("duplicates", root / "media/quarantine/duplicates"),
    ]


def library_root(root: Path, kind: str) -> Path:
    mapping = {
        "movie": root / "media/library/movies",
        "tv": root / "media/library/tv",
        "music": root / "media/library/music",
        "home": root / "media/library/home-videos",
    }
    try:
        return mapping[kind]
    except KeyError as exc:
        raise ValueError(f"unknown media type: {kind}") from exc


def media_files(path: Path) -> list[Path]:
    if path.is_file():
        return [path] if path.suffix.lower() in MEDIA_EXTS and path.stat().st_size > 0 else []
    if not path.is_dir():
        return []
    files: list[Path] = []
    try:
        for p in path.rglob("*"):
            if p.is_file() and p.suffix.lower() in MEDIA_EXTS and p.stat().st_size > 0:
                files.append(p)
    except (OSError, PermissionError):
        return []
    return sorted(files)


def all_regular_files(path: Path) -> list[Path]:
    if path.is_file():
        if path.name.endswith(".pcga-classification.json"):
            return []
        return [path] if path.stat().st_size >= 0 else []
    if not path.is_dir():
        return []
    files: list[Path] = []
    try:
        for p in path.rglob("*"):
            if p.is_file() and p.name != ".pcga-classification.json" and not p.name.endswith(".pcga-classification.json"):
                files.append(p)
    except (OSError, PermissionError):
        return []
    return sorted(files)


def classification_manifest(path: Path) -> dict:
    manifest = path / ".pcga-classification.json" if path.is_dir() else path.with_name(path.name + ".pcga-classification.json")
    try:
        return json.loads(manifest.read_text(encoding="utf-8")) if manifest.is_file() else {}
    except Exception:
        return {}


def optical_media_manifest(path: Path) -> dict:
    if not path.is_dir():
        return {}
    manifest=path/'.pcga-media.json'
    try:
        data=json.loads(manifest.read_text(encoding='utf-8')) if manifest.is_file() else {}
        return data if isinstance(data,dict) else {}
    except Exception:
        return {}


def unwrap_single_media_dir(path: Path) -> Path:
    """Peel legacy wrapper dirs when exactly one child directory contains all media."""
    current = path
    for _ in range(4):
        if not current.is_dir():
            break
        direct_media = [p for p in current.iterdir() if p.is_file() and p.suffix.lower() in MEDIA_EXTS and p.stat().st_size > 0]
        if direct_media:
            break
        child_dirs = [p for p in current.iterdir() if p.is_dir() and media_files(p)]
        # Only unwrap an unambiguous single nested media directory.
        if len(child_dirs) != 1:
            break
        current = child_dirs[0]
    return current


def total_size(files: Iterable[Path]) -> int:
    size = 0
    for p in files:
        try:
            size += p.stat().st_size
        except OSError:
            pass
    return size


def human_size(value: int) -> str:
    size = float(value)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024.0 or unit == "TB":
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024.0
    return f"{value} B"


def safe_component(value: str, field: str) -> str:
    value = value.strip().replace("\x00", "")
    value = re.sub(r"[\\/]", "-", value)
    value = re.sub(r"\s+", " ", value).strip(" .")
    if not value or value in {".", ".."}:
        raise ValueError(f"{field} is required")
    if len(value) > 180:
        value = value[:180].rstrip()
    return value


def normalize_year(value: str) -> str:
    value = value.strip()
    if not value:
        return ""
    if not re.fullmatch(r"(?:19|20)\d{2}", value):
        raise ValueError("year must be a four-digit year or blank")
    return value


def infer_title_year(name: str) -> tuple[str, str]:
    n = TIMESTAMP_PREFIX.sub("", name)
    n = ARM_SUFFIX.sub("", n)
    if n.lower().endswith(tuple(MEDIA_EXTS)):
        n = Path(n).stem
    year = ""
    m = YEAR_RE.search(n)
    if m:
        year = m.group(1)
        n = (n[:m.start()] + n[m.end():]).strip()
    n = n.rstrip("-_ ")
    n = n.replace("_", " ")
    n = re.sub(r"\s+", " ", n).strip()
    return n or "Untitled", year


def parse_episode_identity(name: str) -> dict | None:
    raw = TIMESTAMP_PREFIX.sub('', Path(name).stem)
    match = next((rx.search(raw) for rx in EPISODE_TOKEN_PATTERNS if rx.search(raw)), None)
    if not match:
        return None
    prefix = raw[:match.start()].strip(' ._-')
    suffix = raw[match.end():].strip(' ._-')
    series, year = infer_title_year(prefix)
    if not series or series == 'Untitled':
        return None
    try:
        season = int(match.group('season')); episode = int(match.group('episode'))
        end_raw = match.groupdict().get('episode_end')
        episode_end = int(end_raw) if end_raw else None
    except (TypeError, ValueError):
        return None
    episode_title, _ = infer_title_year(suffix) if suffix else ('', '')
    return {'series':series,'year':year,'season':season,'episode':episode,
            'episode_end':episode_end,'episode_title':episode_title if episode_title != 'Untitled' else ''}


def video_sequence_key(path: Path) -> tuple:
    """Sort MakeMKV/ARM tracks by numeric title/track number when present."""
    stem = TIMESTAMP_PREFIX.sub('', path.stem)
    match = re.search(r'(?i)(?:^|[._ -])(?:title|track)?[_ -]*t?(\d{1,4})(?=$|[._ -])', stem)
    if not match:
        match = re.search(r'(?i)(?:title|track)[_ -]*(\d{1,4})', stem)
    if match:
        try:
            return (0, int(match.group(1)), stem.lower())
        except (TypeError, ValueError):
            pass
    parts = re.split(r'(\d+)', stem.lower())
    natural = tuple(int(x) if x.isdigit() else x for x in parts)
    return (1, natural, stem.lower())


def provider_folder_tag(provider: str, provider_id: str) -> str:
    p=(provider or '').strip().lower(); pid=(provider_id or '').strip()
    if not pid:
        return ''
    if p == 'tmdb' and re.fullmatch(r'\d+', pid): return f'[tmdbid-{pid}]'
    if p == 'tvdb' and re.fullmatch(r'\d+', pid): return f'[tvdbid-{pid}]'
    if (p in {'omdb','imdb'} or pid.startswith('tt')) and re.fullmatch(r'tt\d+', pid): return f'[imdbid-{pid}]'
    return ''


def provider_from_ids(ids: dict) -> tuple[str,str]:
    normalized={str(k).lower():str(v) for k,v in (ids or {}).items() if v is not None}
    for key,provider in (('tmdb','tmdb'),('imdb','imdb'),('tvdb','tvdb')):
        if normalized.get(key): return provider, normalized[key]
    return '', ''


def jellyfin_port() -> int:
    env=os.environ.get('PCGA_JELLYFIN_PORT','').strip()
    if env.isdigit(): return int(env)
    try:
        for line in STACK_ENV.read_text(encoding='utf-8').splitlines():
            if line.startswith('JELLYFIN_PORT='):
                value=line.split('=',1)[1].strip().strip('"\\\'')
                if value.isdigit(): return int(value)
    except OSError:
        pass
    return 8096


def jellyfin_token() -> str:
    try: return JELLYFIN_TOKEN_FILE.read_text(encoding='utf-8').strip()
    except OSError: return ''


def http_json(url: str, payload: dict | None = None, token: str = '', timeout: float = 8.0):
    data=None if payload is None else json.dumps(payload).encode('utf-8')
    headers={'User-Agent':f'PCGameArchive/{VERSION}','Accept':'application/json'}
    if data is not None: headers['Content-Type']='application/json'
    if token: headers['X-Emby-Token']=token
    req=urllib.request.Request(url,data=data,headers=headers,method='POST' if data is not None else 'GET')
    with urllib.request.urlopen(req,timeout=timeout) as resp:
        return json.loads(resp.read().decode('utf-8'))


def jellyfin_metadata_search(query: str, kind: str, year: str='') -> list[dict]:
    token=jellyfin_token()
    if not token:
        return []
    base=os.environ.get('PCGA_JELLYFIN_BASE_URL',f'http://127.0.0.1:{jellyfin_port()}').rstrip('/')
    kinds=['movie','tv'] if kind == 'all' else [kind]
    out=[]
    for media_kind in kinds:
        endpoint='Movie' if media_kind == 'movie' else 'Series'
        info={'Name':query}
        if year.isdigit(): info['Year']=int(year)
        payload={'SearchInfo':info,'IncludeDisabledProviders':False}
        try:
            rows=http_json(f'{base}/Items/RemoteSearch/{endpoint}',payload,token)
        except Exception as exc:
            log(f'Jellyfin remote metadata search {endpoint} failed: {type(exc).__name__}')
            continue
        for row in (rows if isinstance(rows,list) else [])[:12]:
            ids=row.get('ProviderIds') or {}
            provider,pid=provider_from_ids(ids)
            out.append({
                'kind':media_kind,'title':str(row.get('Name') or '').strip(),
                'year':str(row.get('ProductionYear') or '')[:4],
                'provider':provider,'provider_id':pid,'provider_ids':ids,
                'source':str(row.get('SearchProviderName') or 'Jellyfin provider'),
                'overview':str(row.get('Overview') or '').strip(),
            })
    return [r for r in out if r['title']]


def direct_metadata_search(query: str, kind: str, year: str='') -> list[dict]:
    pf=Path('/etc/pc-game-archive/arm-metadata-provider')
    provider=(pf.read_text().strip().lower() if pf.exists() else 'omdb')
    if provider not in ('omdb','tmdb'): provider='omdb'
    keyfile=Path('/etc/pc-game-archive/arm-omdb-key' if provider=='omdb' else '/etc/pc-game-archive/arm-tmdb-key')
    try: key=keyfile.read_text().strip()
    except OSError: key=''
    if not key: return []
    out=[]
    if provider == 'omdb':
        params={'apikey':key,'s':query}
        if kind == 'movie': params['type']='movie'
        elif kind == 'tv': params['type']='series'
        data=http_json(os.environ.get('PCGA_OMDB_ENDPOINT','https://www.omdbapi.com/')+'?'+urllib.parse.urlencode(params))
        for row in data.get('Search',[])[:12]:
            typ=str(row.get('Type') or '')
            mk='tv' if typ=='series' else 'movie' if typ=='movie' else ''
            if not mk: continue
            out.append({'kind':mk,'title':str(row.get('Title') or ''),'year':str(row.get('Year') or '')[:4],
                        'provider':'imdb','provider_id':str(row.get('imdbID') or ''),'provider_ids':{'Imdb':row.get('imdbID')},
                        'source':'OMDb','overview':''})
    else:
        endpoints=[]
        if kind in ('all','movie'): endpoints.append(('movie','https://api.themoviedb.org/3/search/movie'))
        if kind in ('all','tv'): endpoints.append(('tv','https://api.themoviedb.org/3/search/tv'))
        for mk,endpoint in endpoints:
            params={'api_key':key,'query':query}
            if year.isdigit(): params['year' if mk=='tv' else 'primary_release_year']=year
            data=http_json(os.environ.get('PCGA_TMDB_ENDPOINT',endpoint)+'?'+urllib.parse.urlencode(params))
            for row in data.get('results',[])[:12]:
                title=str(row.get('name') or row.get('title') or '')
                date=str(row.get('first_air_date') or row.get('release_date') or '')
                out.append({'kind':mk,'title':title,'year':date[:4],'provider':'tmdb','provider_id':str(row.get('id') or ''),
                            'provider_ids':{'Tmdb':row.get('id')},'source':'TMDb','overview':str(row.get('overview') or '')})
    return [r for r in out if r['title']]


def metadata_search(query: str, kind: str, year: str='') -> tuple[list[dict],str]:
    query=query.strip()
    if not query: raise ValueError('metadata search requires a title or series name')
    if kind not in {'all','movie','tv'}: kind='all'
    rows=jellyfin_metadata_search(query,kind,year)
    if rows: return rows,'Jellyfin metadata providers'
    rows=direct_metadata_search(query,kind,year)
    if rows: return rows,'PCGA configured metadata provider'
    raise ValueError('No metadata results. Check Jellyfin metadata providers/network access or configure a PCGA OMDb/TMDb key.')


def update_selected_metadata(source: Path, selection: dict[str,str]) -> str:
    manifest_path = source/'.pcga-classification.json' if source.is_dir() else source.with_name(source.name+'.pcga-classification.json')
    try: data=json.loads(manifest_path.read_text(encoding='utf-8')) if manifest_path.exists() else {}
    except Exception: data={}
    kind=selection.get('kind','')
    title=safe_component(selection.get('title',''),'metadata title')
    year=normalize_year(selection.get('year',''))
    provider=selection.get('provider','').strip().lower()[:20]
    provider_id=selection.get('provider_id','').strip()[:80]
    data.update({'classification':'tv' if kind=='tv' else 'movie','title':title,'year':year,
                 'provider':provider,'provider_id':provider_id,'action':'review','confidence':1.0})
    assignment_note=''
    if kind == 'tv':
        data['series']=title
        videos=sorted([f for f in media_files(source) if f.suffix.lower() in VIDEO_EXTS], key=video_sequence_key)
        parsed=[parse_episode_identity(v.name) for v in videos]
        if videos and not any(parsed):
            # Metadata identifies the series, not the episode numbers. Prepare a visible,
            # editable sequential plan instead of failing later at promotion time.
            try: season_num=int(str(data.get('season') or '1'))
            except ValueError: season_num=1
            try: episode_num=int(str(data.get('episode') or '1'))
            except ValueError: episode_num=1
            if season_num < 0 or season_num > 999: season_num=1
            if episode_num < 0 or episode_num > 9999: episode_num=1
            data['season']=str(season_num); data['episode']=str(episode_num)
            data['episode_assignment']='sequential'
            data['episode_assignment_count']=len(videos)
            assignment_note=(f' Prepared {len(videos)} unnumbered video track(s) for sequential assignment '
                             f'starting S{season_num:02d}E{episode_num:02d}; review the episode plan before routing.')
        elif videos and all(parsed):
            data['episode_assignment']='filename'
            data.pop('episode_assignment_count',None)
            assignment_note=' Episode numbers will be taken from the SxxEyy/1x02 filenames.'
        elif videos:
            data['episode_assignment']='mixed'
            data.pop('episode_assignment_count',None)
            assignment_note=' This item mixes numbered and unnumbered episode filenames; review the assignment before routing.'
    evidence=[str(x) for x in (data.get('evidence') or [])]
    evidence.append(f'Manual metadata selection: {title}' + (f' ({year})' if year else '') + (f' [{provider}:{provider_id}]' if provider_id else ''))
    data['evidence']=evidence[-8:]
    tmp=manifest_path.with_suffix(manifest_path.suffix+'.tmp')
    tmp.write_text(json.dumps(data,indent=2,sort_keys=True)+'\n',encoding='utf-8'); tmp.replace(manifest_path)
    return f'Selected metadata: {title}.' + assignment_note


def item_id(root: Path, path: Path) -> str:
    rel = path.resolve().relative_to(root.resolve()).as_posix().encode("utf-8")
    return base64.urlsafe_b64encode(rel).decode("ascii").rstrip("=")


def path_from_id(root: Path, encoded: str) -> Path:
    try:
        raw = encoded + "=" * (-len(encoded) % 4)
        rel = base64.urlsafe_b64decode(raw.encode("ascii")).decode("utf-8")
    except Exception as exc:
        raise ValueError("invalid item id") from exc
    candidate = (root / rel).resolve()
    allowed = [q.resolve() for _, q in queue_roots(root)]
    if not any(candidate == q or q in candidate.parents for q in allowed):
        raise ValueError("item is outside manual-review queues")
    if candidate in allowed:
        raise ValueError("queue root itself is not an item")
    return candidate


@dataclass
class ReviewItem:
    id: str
    source: str
    path: Path
    files: list[Path]
    size: int
    title: str
    year: str
    media_kind: str
    confidence: float | None
    evidence: list[str]
    provider: str = ""
    provider_id: str = ""
    series: str = ""
    season: str = ""
    episode: str = ""
    episode_title: str = ""

    @property
    def display_path(self) -> str:
        return str(self.path)

    @property
    def sample_names(self) -> list[str]:
        return [p.name for p in self.files[:5]]


def scan_items(root: Path) -> list[ReviewItem]:
    items: list[ReviewItem] = []
    for source_name, queue in queue_roots(root):
        queue.mkdir(parents=True, exist_ok=True)
        for child in sorted(queue.iterdir(), key=lambda p: p.name.lower()):
            if child.name.endswith(".pcga-classification.json"):
                continue
            candidate = unwrap_single_media_dir(child)
            media = media_files(candidate)
            files = media or all_regular_files(candidate)
            if not files:
                continue
            manifest = classification_manifest(candidate)
            title, year = infer_title_year(candidate.name)
            title = str(manifest.get("title") or title)
            year = str(manifest.get("year") or year or "")[:4]
            exts = {p.suffix.lower() for p in files}
            detected = str(manifest.get("classification") or "")
            if not detected:
                if media and exts and exts <= AUDIO_EXTS:
                    detected = "audio"
                elif media and exts & VIDEO_EXTS:
                    detected = "video"
                else:
                    detected = "data"
            conf = manifest.get("confidence")
            try: conf = float(conf) if conf is not None else None
            except (TypeError, ValueError): conf = None
            evidence = [str(x) for x in (manifest.get("evidence") or [])[:4]]
            items.append(ReviewItem(
                id=item_id(root, candidate), source=source_name, path=candidate,
                files=files, size=total_size(files), title=title, year=year, media_kind=detected,
                confidence=conf, evidence=evidence,
                provider=str(manifest.get("provider") or ""),
                provider_id=str(manifest.get("provider_id") or ""),
                series=str(manifest.get("series") or (title if detected == "tv" else "")),
                season=str(manifest.get("season") or ""),
                episode=str(manifest.get("episode") or ""),
                episode_title=str(manifest.get("episode_title") or ""),
            ))
    return items


def _safe_stat_size(path: Path) -> int:
    try:
        return int(path.stat().st_size)
    except OSError:
        return 0


def preview_source(item: ReviewItem) -> tuple[str, Path] | tuple[None, None]:
    """Choose a deterministic, representative file for portal Manual Review.

    Prefer the largest video so DVD/BD extras and tiny menu tracks do not become
    the only useful clue. Images and audio are used when no video exists.
    """
    videos=[p for p in item.files if p.suffix.lower() in VIDEO_EXTS and p.exists()]
    if videos:
        return 'video', max(videos, key=_safe_stat_size)
    regular=all_regular_files(item.path)
    images=[p for p in regular if p.suffix.lower() in IMAGE_EXTS and p.exists()]
    if images:
        return 'image', max(images, key=_safe_stat_size)
    audio=[p for p in item.files if p.suffix.lower() in AUDIO_EXTS and p.exists()]
    if audio:
        return 'audio', max(audio, key=_safe_stat_size)
    return None, None


def media_duration_seconds(path: Path) -> float:
    try:
        proc=subprocess.run([
            'ffprobe','-v','error','-show_entries','format=duration',
            '-of','default=noprint_wrappers=1:nokey=1',str(path)
        ],check=False,capture_output=True,text=True,timeout=12)
        value=float((proc.stdout or '').strip() or 0)
        return value if value > 0 else 0.0
    except Exception:
        return 0.0


def review_preview_payload(item: ReviewItem) -> dict:
    kind,path=preview_source(item)
    if not path or not kind:
        return {'available':False}
    return {
        'available':True,
        'kind':kind,
        'name':path.name,
        'size':_safe_stat_size(path),
        'size_human':human_size(_safe_stat_size(path)),
        # Keep queue enumeration cheap. Duration is probed only when a preview
        # is actually opened rather than once per item on every portal refresh.
        'duration_seconds':0,
        'clip_seconds':PREVIEW_CLIP_SECONDS if kind in {'video','audio'} else 0,
    }


def review_item_payload(item: ReviewItem) -> dict:
    videos = sorted([f for f in item.files if f.suffix.lower() in VIDEO_EXTS], key=video_sequence_key)
    episode_plan = {"mode": "none", "rows": []}
    if videos and (item.media_kind == "tv" or item.series):
        parsed = [parse_episode_identity(v.name) for v in videos]
        if all(parsed):
            episode_plan["mode"] = "filename"
            for video, ep in zip(videos, parsed):
                token = f"S{int(ep['season']):02d}E{int(ep['episode']):02d}"
                if ep.get("episode_end") is not None and int(ep["episode_end"]) != int(ep["episode"]):
                    token += f"-E{int(ep['episode_end']):02d}"
                episode_plan["rows"].append({"file": video.name, "target": token})
        elif any(parsed):
            episode_plan["mode"] = "mixed"
            for video, ep in zip(videos, parsed):
                token = f"S{int(ep['season']):02d}E{int(ep['episode']):02d}" if ep else "Needs assignment"
                episode_plan["rows"].append({"file": video.name, "target": token})
        else:
            episode_plan["mode"] = "sequential"
            episode_plan["rows"] = [{"file": video.name, "offset": index} for index, video in enumerate(videos)]
    return {
        "id": item.id, "source": item.source, "path": item.display_path, "title": item.title,
        "year": item.year, "media_kind": item.media_kind, "confidence": item.confidence,
        "evidence": item.evidence, "provider": item.provider, "provider_id": item.provider_id,
        "series": item.series, "season": item.season, "episode": item.episode,
        "episode_title": item.episode_title, "size": item.size, "size_human": human_size(item.size),
        "file_count": len(item.files), "files": [x.name for x in item.files[:24]],
        "files_truncated": max(0, len(item.files) - 24), "episode_plan": episode_plan,
        "preview": review_preview_payload(item),
    }


def find_review_item(root: Path, encoded: str) -> ReviewItem:
    for item in scan_items(root):
        if secrets.compare_digest(item.id, encoded):
            return item
    path_from_id(root, encoded)
    raise FileNotFoundError("review item is no longer queued")


def tv_assignment_preview(item: ReviewItem) -> str:
    videos=sorted([f for f in item.files if f.suffix.lower() in VIDEO_EXTS], key=video_sequence_key)
    if not videos or not (item.media_kind == 'tv' or item.series):
        return ''
    parsed=[parse_episode_identity(v.name) for v in videos]
    if all(parsed):
        rows=[]
        for video,ep in zip(videos,parsed):
            token=f"S{int(ep['season']):02d}E{int(ep['episode']):02d}"
            if ep.get('episode_end') is not None and int(ep['episode_end']) != int(ep['episode']):
                token += f"-E{int(ep['episode_end']):02d}"
            rows.append(f'<tr><td>{html.escape(video.name)}</td><td><strong>{html.escape(token)}</strong></td></tr>')
        return '<section class="episode-plan"><strong>Episode assignment</strong><div class="muted">Episode numbers are already encoded in the filenames.</div><table><thead><tr><th>Source track</th><th>Jellyfin episode</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></section>'
    if any(parsed):
        rows=[]
        for video,ep in zip(videos,parsed):
            token=(f"S{int(ep['season']):02d}E{int(ep['episode']):02d}" if ep else 'Needs assignment')
            rows.append(f'<tr><td>{html.escape(video.name)}</td><td><strong>{html.escape(token)}</strong></td></tr>')
        return '<section class="episode-plan warning"><strong>Episode assignment needs review</strong><div class="muted">This folder mixes numbered and unnumbered tracks. PCGA will not guess a mixed mapping.</div><table><tbody>'+''.join(rows)+'</tbody></table></section>'
    season=item.season if item.season.isdigit() else '1'
    start=item.episode if item.episode.isdigit() else '1'
    rows=[]
    for offset,video in enumerate(videos):
        target=f'S{int(season):02d}E{int(start)+offset:02d}'
        rows.append(f'<tr><td>{html.escape(video.name)}</td><td><strong class="episode-target" data-offset="{offset}">{target}</strong></td></tr>')
    return '<section class="episode-plan sequential"><strong>Episode assignment</strong><div class="muted">These tracks have no episode tokens. PCGA will number them sequentially in the order below. Edit Season or Starting episode before routing if this disc begins later in the season.</div><table><thead><tr><th>Source track</th><th>Will become</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></section>'


def ensure_source_valid(root: Path, source: Path) -> list[Path]:
    source = source.resolve()
    # Revalidate immediately before every move.
    _ = path_from_id(root, item_id(root, source))
    files = all_regular_files(source)
    if not files:
        raise ValueError("item contains no reviewable files")
    return files


def merge_move_directory(source: Path, destination: Path) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    children = list(source.iterdir())
    collisions = [destination / child.name for child in children if (destination / child.name).exists()]
    if collisions:
        names = ", ".join(p.name for p in collisions[:5])
        raise FileExistsError(f"destination already contains: {names}")
    for child in children:
        shutil.move(str(child), str(destination / child.name))
    try:
        source.rmdir()
    except OSError:
        pass


def move_source(source: Path, destination_dir: Path, rename_file_to: str | None = None) -> None:
    destination_dir.mkdir(parents=True, exist_ok=True)
    if source.is_file():
        name = source.name
        if rename_file_to:
            name = rename_file_to + source.suffix.lower()
        target = destination_dir / name
        if target.exists():
            raise FileExistsError(f"destination already exists: {target}")
        sidecar = source.with_name(source.name + ".pcga-classification.json")
        shutil.move(str(source), str(target))
        if sidecar.exists():
            shutil.move(str(sidecar), str(target.with_name(target.name + ".pcga-classification.json")))
    elif source.is_dir():
        merge_move_directory(source, destination_dir)
    else:
        raise FileNotFoundError(source)


def write_manifest(destination: Path, payload: dict) -> None:
    manifest = destination / ".pcga-manual-review.json"
    data = dict(payload)
    data["promoted_at"] = dt.datetime.now(dt.timezone.utc).isoformat()
    tmp = manifest.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    tmp.replace(manifest)


def refresh_jellyfin() -> None:
    if os.environ.get("PCGA_DISABLE_JELLYFIN_REFRESH") == "1":
        return
    helper = Path("/usr/local/sbin/pcga-jellyfin-refresh")
    if helper.exists():
        subprocess.run([str(helper)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def series_folder_name(series: str, year: str, provider: str, provider_id: str) -> tuple[str,str]:
    base = f"{series} ({year})" if year else series
    tag = provider_folder_tag(provider, provider_id)
    return base + (f" {tag}" if tag else ""), base


def find_existing_series_root(root: Path, series: str, year: str, provider: str, provider_id: str) -> Path:
    tvroot=library_root(root,'tv'); tvroot.mkdir(parents=True,exist_ok=True)
    preferred_name, base_name=series_folder_name(series,year,provider,provider_id)
    preferred=tvroot/preferred_name; base=tvroot/base_name
    # Provider identity is the strongest join key across separately reviewed episodes.
    if provider_id:
        for child in tvroot.iterdir():
            if not child.is_dir(): continue
            identity=child/'.pcga-series.json'
            try: data=json.loads(identity.read_text(encoding='utf-8')) if identity.exists() else {}
            except Exception: data={}
            if str(data.get('provider_id') or '') == provider_id and str(data.get('provider') or '').lower() == provider.lower():
                return child
    if preferred.exists(): return preferred
    if provider_id and base.exists() and base != preferred:
        # Upgrade an existing untagged series folder to the provider-qualified name.
        try:
            base.rename(preferred)
            return preferred
        except OSError:
            return base
    if base.exists(): return base
    return preferred


def write_series_manifest(series_root: Path, series: str, year: str, provider: str, provider_id: str) -> None:
    series_root.mkdir(parents=True,exist_ok=True)
    payload={'pcga_manual_review_version':VERSION,'series':series,'year':year,
             'provider':provider,'provider_id':provider_id,
             'updated_at':dt.datetime.now(dt.timezone.utc).isoformat()}
    tmp=series_root/'.pcga-series.json.tmp'
    tmp.write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n',encoding='utf-8')
    tmp.replace(series_root/'.pcga-series.json')


def canonical_episode_stem(series: str, season: int, episode: int, episode_end: int | None = None,
                           episode_title: str = '') -> str:
    token=f'S{season:02d}E{episode:02d}'
    if episode_end is not None and episode_end != episode:
        token += f'-E{episode_end:02d}'
    name=f'{series} - {token}'
    if episode_title:
        name += ' - ' + safe_component(episode_title,'episode title')
    return safe_component(name,'episode filename')


def promote_tv_item(root: Path, source: Path, fields: dict[str,str], files: list[Path]) -> tuple[Path,dict]:
    series=safe_component(fields.get('series',fields.get('title','')),'series')
    year=normalize_year(fields.get('year',''))
    provider=fields.get('provider','').strip().lower()[:20]
    provider_id=fields.get('provider_id','').strip()[:80]
    try: default_season=int(fields.get('season','1') or '1')
    except ValueError as exc: raise ValueError('season must be a number') from exc
    if default_season < 0 or default_season > 999: raise ValueError('season must be between 0 and 999')
    start_raw=(fields.get('episode') or '').strip()
    start_episode=None
    if start_raw:
        try: start_episode=int(start_raw)
        except ValueError as exc: raise ValueError('episode/start episode must be a number') from exc
        if start_episode < 0 or start_episode > 9999: raise ValueError('episode must be between 0 and 9999')
    ep_title=(fields.get('episode_title') or '').strip()
    series_root=find_existing_series_root(root,series,year,provider,provider_id)
    videos=sorted([f for f in files if f.suffix.lower() in VIDEO_EXTS], key=video_sequence_key)
    if not videos: raise ValueError('TV routing requires at least one video file')
    parsed_flags=[parse_episode_identity(video.name) is not None for video in videos]
    if source.is_dir() and any(parsed_flags) and not all(parsed_flags):
        raise ValueError('TV folder mixes numbered and unnumbered tracks. Rename the unnumbered files with SxxEyy/1x02 tokens or separate them into a sequential-only review item before routing.')
    plan=[]
    for index,video in enumerate(videos):
        parsed=parse_episode_identity(video.name)
        if source.is_file():
            season=default_season
            episode=start_episode if start_episode is not None else (parsed['episode'] if parsed else None)
            episode_end=parsed.get('episode_end') if parsed else None
            title=ep_title or (parsed.get('episode_title','') if parsed else '')
        elif parsed:
            season=int(parsed['season']); episode=int(parsed['episode']); episode_end=parsed.get('episode_end'); title=parsed.get('episode_title','')
        elif start_episode is not None:
            season=default_season; episode=start_episode+index; episode_end=None; title=''
        else:
            raise ValueError('TV item has unnumbered video tracks. Set a Starting episode in the Episode Assignment section (for example 1), or rename every episode with an SxxEyy/1x02 token.')
        if episode is None: raise ValueError('episode number is required for TV promotion')
        season_dir=series_root/f'Season {season:02d}'
        final=season_dir/(canonical_episode_stem(series,season,episode,episode_end,title)+video.suffix.lower())
        plan.append((video,final,season,episode,title))
    collisions=[final for _,final,_,_,_ in plan if final.exists()]
    if collisions: raise FileExistsError('destination already contains: '+', '.join(x.name for x in collisions[:5]))
    for video,final,_,_,_ in plan:
        final.parent.mkdir(parents=True,exist_ok=True)
        shutil.move(str(video),str(final))
    # Preserve non-video files without letting them disrupt Jellyfin's episode parser.
    if source.is_dir():
        media_source=source/'.pcga-media.json'
        if media_source.is_file():
            try:
                data=json.loads(media_source.read_text(encoding='utf-8'));finger=str(data.get('fingerprint') or '')[:16] or dt.datetime.now().strftime('%Y%m%d%H%M%S')
                shutil.copy2(media_source,series_root/f'.pcga-optical-source-{finger}.json')
            except Exception:
                pass
        internal={'.pcga-classification.json','.pcga-source-hint','.pcga-media.json'}
        leftovers=[]
        for f in list(source.rglob('*')):
            if f.is_file() and f.name not in internal:
                leftovers.append(f)
        if leftovers:
            extras=series_root/'extras'/safe_component(source.name,'source folder')
            extras.mkdir(parents=True,exist_ok=True)
            for f in leftovers:
                target=extras/f.name
                if target.exists():
                    target=extras/(dt.datetime.now().strftime('%Y%m%d-%H%M%S')+'-'+f.name)
                shutil.move(str(f),str(target))
        for internal_name in internal:
            try: (source/internal_name).unlink()
            except OSError: pass
        for d in sorted([x for x in source.rglob('*') if x.is_dir()],key=lambda x:len(x.parts),reverse=True):
            try:d.rmdir()
            except OSError:pass
        try:source.rmdir()
        except OSError:pass
    else:
        sidecar=source.with_name(source.name+'.pcga-classification.json')
        try: sidecar.unlink()
        except OSError: pass
    write_series_manifest(series_root,series,year,provider,provider_id)
    metadata={'type':'tv','series':series,'year':year,'provider':provider,'provider_id':provider_id,
              'season':default_season,'episode':start_raw,'episode_title':ep_title,
              'episodes_promoted':[{'file':str(final),'season':season,'episode':episode,'title':title} for _,final,season,episode,title in plan]}
    return series_root,metadata


def promote(root: Path, source: Path, kind: str, fields: dict[str, str]) -> Path:
    files = ensure_source_valid(root, source)
    original = str(source)
    kind = kind.strip().lower()
    media_source=optical_media_manifest(source)
    if media_source and kind in {"movie","tv"}:
        layout=str(media_source.get('layout') or '').strip().lower()
        contents=media_source.get('contents') if isinstance(media_source.get('contents'),list) else []
        if layout in {'multi-title','multi-title-candidate','collection'} or len(contents)>1:
            raise ValueError('This optical source contains multiple logical titles. Map its MakeMKV title indices with `game-archive media-intake` before Jellyfin promotion; PCGA will not merge the anthology into one library item.')
        if kind=='movie' and layout=='multi-disc-title':
            raise ValueError('This movie is part of a multi-disc source. Confirm its disc/part role before Jellyfin promotion; PCGA will not collapse separate movie discs into one unstacked folder.')
    year = normalize_year(fields.get("year", ""))
    provider=fields.get('provider','').strip().lower()[:20]
    provider_id=fields.get('provider_id','').strip()[:80]

    if kind == "movie":
        title = safe_component(fields.get("title", ""), "title")
        base=f"{title} ({year})" if year else title
        tag=provider_folder_tag(provider,provider_id)
        folder=base+(f" {tag}" if tag else "")
        destination = library_root(root, kind) / folder
        rename = folder if source.is_file() else None
        move_source(source, destination, rename)
        metadata = {"type": "movie", "title": title, "year": year, "provider":provider,"provider_id":provider_id}

    elif kind == "tv":
        destination,metadata=promote_tv_item(root,source,fields,files)

    elif kind == "music":
        artist = safe_component(fields.get("artist", ""), "artist")
        album = safe_component(fields.get("album", fields.get("title", "")), "album")
        album_folder = f"{album} ({year})" if year else album
        destination = library_root(root, kind) / artist / album_folder
        move_source(source, destination, None)
        metadata = {"type": "music", "artist": artist, "album": album, "year": year}

    elif kind == "home":
        title = safe_component(fields.get("title", ""), "title")
        folder = f"{title} ({year})" if year else title
        destination = library_root(root, kind) / folder
        rename = folder if source.is_file() else None
        move_source(source, destination, rename)
        metadata = {"type": "home", "title": title, "year": year}

    elif kind in {"game", "software", "disc"}:
        title = safe_component(fields.get("title", ""), "title")
        folder = f"{title} ({year})" if year else title
        base = {
            "game": root / "ingest/inbox/pc-games",
            "software": root / "ingest/inbox/software",
            "disc": root / "ingest/inbox/disc-images",
        }[kind]
        destination = base / folder
        move_source(source, destination, None)
        metadata = {"type": kind, "title": title, "year": year}

    else:
        raise ValueError("type must be movie, tv, music, home, game, software, or disc")

    write_manifest(destination, {
        "pcga_manual_review_version": VERSION,
        "source": original,
        "files_before_move": [str(p) for p in files],
        **metadata,
    })
    log(f"Promoted {original} -> {destination} ({kind})")
    if kind in {"movie", "tv", "music", "home"}:
        refresh_jellyfin()
    return destination

def move_to_quarantine(root: Path, source: Path) -> Path:
    ensure_source_valid(root, source)
    quarantine = root / "media/quarantine/unidentified"
    quarantine.mkdir(parents=True, exist_ok=True)
    if quarantine.resolve() in source.resolve().parents:
        return source
    target = quarantine / source.name
    if target.exists():
        stamp = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
        target = quarantine / f"{stamp}-{source.name}"
    sidecar = source.with_name(source.name + ".pcga-classification.json") if source.is_file() else None
    shutil.move(str(source), str(target))
    if sidecar is not None and sidecar.exists():
        shutil.move(str(sidecar), str(target.with_name(target.name + ".pcga-classification.json")))
    log(f"Moved manual-review item to quarantine: {target}")
    return target


def delete_review_item(root: Path, source: Path) -> dict:
    """Permanently delete one explicitly selected manual-review item.

    The source is revalidated against the review queues immediately before
    deletion.  A small audit receipt is retained outside the archive so an
    operator can tell what was intentionally removed without retaining another
    copy of the media itself.
    """
    files=ensure_source_valid(root,source)
    source=source.resolve()
    rel=str(source.relative_to(root.resolve()))
    manifest=classification_manifest(source)
    size=total_size(files)
    count=len(files)
    sidecars=[]
    if source.is_file():
        for suffix in ('.pcga-classification.json','.pcga-source-hint'):
            q=source.with_name(source.name+suffix)
            if q.exists(): sidecars.append(q)
        source.unlink()
        for q in sidecars:
            try:q.unlink()
            except OSError:pass
    elif source.is_dir():
        shutil.rmtree(source)
    else:
        raise FileNotFoundError(source)
    audit_dir=Path('/var/lib/pc-game-archive/review-deletions')
    audit_dir.mkdir(parents=True,exist_ok=True)
    stamp=dt.datetime.now(dt.timezone.utc)
    payload={
        'schema':1,'pcga_version':VERSION,'deleted_at':stamp.isoformat(),
        'path':rel,'bytes':size,'files':count,
        'classification':manifest.get('classification'),
        'title':manifest.get('title'),
        'reason':'manual-review-delete',
    }
    receipt=audit_dir/(stamp.strftime('%Y%m%d-%H%M%S-%f')+'.json')
    receipt.write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n',encoding='utf-8')
    log(f"Deleted manual-review item: {rel} ({count} file(s), {human_size(size)})")
    return payload


def load_token(create: bool = False) -> str:
    env = os.environ.get("PCGA_REVIEW_TOKEN")
    if env:
        return env.strip()
    if TOKEN_FILE.is_file():
        return TOKEN_FILE.read_text(encoding="utf-8").strip()
    if create:
        TOKEN_FILE.parent.mkdir(parents=True, exist_ok=True)
        token = secrets.token_urlsafe(32)
        TOKEN_FILE.write_text(token + "\n", encoding="utf-8")
        os.chmod(TOKEN_FILE, 0o600)
        return token
    raise RuntimeError(f"missing review token: {TOKEN_FILE}")


def parse_conf() -> dict[str, str]:
    result = {"BIND": "0.0.0.0", "PORT": "8097"}
    if CONF_FILE.is_file():
        for raw in CONF_FILE.read_text(encoding="utf-8").splitlines():
            raw = raw.strip()
            if not raw or raw.startswith("#") or "=" not in raw:
                continue
            k, v = raw.split("=", 1)
            result[k.strip()] = v.strip().strip('"\'')
    return result


