    'saturn': {'name':'Sega Saturn','exts':{'.chd','.iso'},'terms':['Sega Saturn']},
    'segacd': {'name':'Sega CD','exts':{'.chd','.iso'},'terms':['Sega CD','Mega CD']},
    '3do': {'name':'3DO','exts':{'.chd','.iso'},'terms':['3DO']},
    'pc-fx': {'name':'PC-FX','exts':{'.chd'},'terms':['PC-FX']},
    'turbografx-cd': {'name':'TurboGrafx-CD','exts':{'.chd'},'terms':['TurboGrafx-CD','PC Engine CD']},
    'philips-cd-i': {'name':'Philips CD-i','exts':{'.chd'},'terms':['CD-i','CDI']},
}
ROM_EXT_PLATFORMS={}
for _slug,_info in ROM_PLATFORMS.items():
    for _ext in _info['exts']:
        ROM_EXT_PLATFORMS.setdefault(_ext,[]).append(_slug)
ROM_SEARCH_BASE='mediatype:software AND (subject:(homebrew OR freeware OR abandonware OR "public domain" OR "creative commons") OR description:(homebrew OR freeware OR abandonware OR "public domain" OR "creative commons") OR licenseurl:creativecommons.org*)' 


# Browser uploads land here first, then the intake worker routes them through the
# same canonical libraries used by optical ingest and the public-media importer.
UPLOAD_HINTS={'auto','movie','tv','music','home-video','photos','pc-game','software','disc-image','rom'}
IMAGE_EXT={'.jpg','.jpeg','.png','.webp','.gif','.avif','.bmp','.tif','.tiff','.heic','.heif','.dng'}
AUDIO_EXT={'.flac','.mp3','.m4a','.aac','.ogg','.opus','.wav','.wma','.alac','.ape'}
LOCAL_VIDEO_EXT={'.mkv','.mp4','.m4v','.avi','.mov','.mpg','.mpeg','.ts','.m2ts','.vob','.webm','.ogv'}
UPLOAD_SESSION_RE=re.compile(r'^[a-f0-9]{20,64}$')
MAX_UPLOAD_BYTES=max(1024*1024,int(os.environ.get('PCGA_MAX_UPLOAD_BYTES',str(128*1024**3))))
UPLOAD_SIDECAR_EXT={'.txt','.nfo','.xml','.json','.jpg','.jpeg','.png','.webp','.cue','.m3u'}

class State:
    def __init__(self, root: Path):
        self.root=root
        self.jobs_dir=Path('/var/lib/pc-game-archive/public-media')
        self.jobs_dir.mkdir(parents=True, exist_ok=True)
        self.upload_root=self.root/'ingest/user-uploads'
        self.upload_staging=self.upload_root/'staging'
        self.upload_staging.mkdir(parents=True, exist_ok=True)
        self.lock=threading.Lock()
        self.jobs={}
        for job_file in sorted(self.jobs_dir.glob('*.json'), key=lambda x:x.stat().st_mtime, reverse=True)[:80]:
            try:
                job=json.loads(job_file.read_text(encoding='utf-8'))
                if isinstance(job,dict) and job.get('id'): self.jobs[str(job['id'])]=job
            except Exception:
                pass

    def save_job(self,j):
        p=self.jobs_dir/f"{j['id']}.json"
        tmp=p.with_suffix('.tmp')
        tmp.write_text(json.dumps(j,indent=2,sort_keys=True),encoding='utf-8')
        os.replace(tmp,p)

STATE=None

def http_json(url, timeout=12):
    req=urllib.request.Request(url,headers={'User-Agent':UA,'Accept':'application/json'})
    with urllib.request.urlopen(req,timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8','replace'))

def search_archive(source, q, page=1, rows=20):
    src=SOURCES[source]
    terms=src['query']
    q=(q or '').strip()
    if q:
        safe=' '.join(re.findall(r'[\w\-\.]{2,}',q,flags=re.UNICODE)[:8])
        if safe:
            terms=f'({terms}) AND (title:({safe}) OR description:({safe}) OR creator:({safe}))'
    params=[('q',terms),('fl[]','identifier'),('fl[]','title'),('fl[]','creator'),('fl[]','date'),('fl[]','year'),('fl[]','description'),('fl[]','licenseurl'),('fl[]','rights'),('fl[]','collection'),('fl[]','downloads'),('rows',str(rows)),('page',str(max(1,page))),('output','json'),('sort[]','downloads desc')]
    data=http_json('https://archive.org/advancedsearch.php?'+urllib.parse.urlencode(params))
    docs=((data.get('response') or {}).get('docs') or [])
    out=[]
    for d in docs:
        ident=str(d.get('identifier') or '')
        if not SAFE_ID.fullmatch(ident):
            continue
        out.append({
            'identifier':ident,'title':str(d.get('title') or ident)[:240],
            'creator':flatten(d.get('creator'))[:200], 'date':str(d.get('date') or d.get('year') or '')[:32],
            'description':flatten(d.get('description'))[:420], 'downloads':intish(d.get('downloads')),
            'rights_hint':rights_hint(d), 'source':source,
        })
    return {'source':source,'source_name':src['name'],'page':page,'num_found':intish((data.get('response') or {}).get('numFound')),'items':out}

def flatten(v):
    if isinstance(v,list): return '; '.join(str(x) for x in v if x is not None)
    if isinstance(v,dict): return ' '.join(str(x) for x in v.values())
    return str(v or '')

def intish(v):
    try:return int(v or 0)
    except:return 0

def metadata(identifier):
    if not SAFE_ID.fullmatch(identifier): raise ValueError('invalid identifier')
    return http_json('https://archive.org/metadata/'+urllib.parse.quote(identifier,safe=''))

def rights_hint(meta):
    text=' '.join([flatten(meta.get('licenseurl')),flatten(meta.get('rights')),flatten(meta.get('description'))]).lower()
    if 'creativecommons.org/publicdomain' in text or 'public domain' in text or 'cc0' in text:
        return 'public-domain'
    if 'creativecommons.org/licenses/' in text or 'creative commons' in text:
        return 'creative-commons'
    return 'collection-policy'

def item_collections(m):
    c=m.get('collection')
    if isinstance(c,list): return {str(x) for x in c}
    if c: return {str(c)}
    return set()

def rights_status(meta,source):
    m=meta.get('metadata') or {}
    hint=rights_hint(m)
    cols=item_collections(m)
    if hint in {'public-domain','creative-commons'}:
        return {'allowed':True,'basis':hint,'detail':flatten(m.get('licenseurl') or m.get('rights'))[:500]}
    if source in {'feature_films','classic_tv'} and source in cols:
        return {'allowed':True,'basis':'collection-policy','detail':'Imported from an Internet Archive collection intended for public-domain submissions. Verify item rights if you plan to redistribute it.'}
    return {'allowed':False,'basis':'unverified','detail':'No explicit Creative Commons/Public Domain signal was found for this item.'}

def choose_video(meta,quality='balanced'):
    files=meta.get('files') or []
    cand=[]
    for f in files:
        name=str(f.get('name') or '')
        ext=Path(name).suffix.lower()
        if ext not in VIDEO_EXT: continue
        low=name.lower()
        if any(x in low for x in ('thumb','sample','clip','trailer')): continue
        size=intish(f.get('size'))
        fmt=str(f.get('format') or '')
        score=0
        if ext=='.mp4': score+=100
        if any(x in fmt.lower() for x in ('h.264','h264','mpeg4','mpeg-4','avc')): score+=45
        if str(f.get('source') or '').lower()=='original': score+=10
        if size>20_000_000: score+=20
        cand.append((score,size,name,fmt))
    if not cand: raise ValueError('No downloadable video derivative was found for this item.')
    if quality=='compact':
        cand.sort(key=lambda x: (x[0], -(x[1] if x[1] else 10**18)), reverse=True)
        plausible=[x for x in cand if x[1]>=30_000_000]
        if plausible: return min(plausible,key=lambda x:x[1])
    elif quality=='best':
        cand.sort(key=lambda x:(x[0],x[1]),reverse=True); return cand[0]
    # balanced: prefer high-scoring mp4 <= 4 GiB, then best overall
    plausible=[x for x in cand if x[1] and x[1] <= 4*1024**3]
    if plausible:
        plausible.sort(key=lambda x:(x[0],x[1]),reverse=True); return plausible[0]
    cand.sort(key=lambda x:(x[0],x[1]),reverse=True); return cand[0]

def rom_rights_hint(meta):
    text=' '.join([flatten(meta.get('licenseurl')),flatten(meta.get('rights')),flatten(meta.get('description')),flatten(meta.get('subject'))]).lower()
    if 'creativecommons.org/publicdomain' in text or 'public domain' in text or 'cc0' in text:
        return 'public-domain'
    if 'creativecommons.org/licenses/' in text or 'creative commons' in text:
        return 'creative-commons'
    if any(x in text for x in ('permission granted to distribute','freely distributable','may be distributed freely','redistribution permitted')):
        return 'permission-stated'
    if 'homebrew' in text:
        return 'homebrew-review'
    if 'freeware' in text:
        return 'freeware-review'
    if 'abandonware' in text:
        return 'abandonware-review'
    return 'unverified'

def rom_rights_status(meta):
    m=meta.get('metadata') or {}
    hint=rom_rights_hint(m)
    detail=flatten(m.get('licenseurl') or m.get('rights'))[:700]
    if hint in {'public-domain','creative-commons','permission-stated'}:
        return {'allowed':True,'basis':hint,'detail':detail or 'Archive.org item metadata contains an explicit reuse/distribution signal.'}
    return {'allowed':False,'basis':hint,'detail':detail or 'No explicit public-domain, Creative Commons, or redistribution permission was found in the item metadata.'}

def _rom_search_terms(platform):
    info=ROM_PLATFORMS.get(platform) or {}
    terms=info.get('terms') or []
    if not terms: return ''
    parts=[]
    for t in terms[:4]:
        t=str(t).replace('"',' ').strip()
        if not t: continue
        parts.append(f'"{t}"' if ' ' in t else t)
    if not parts:return ''
    joined=' OR '.join(parts)
    return f' AND (subject:({joined}) OR title:({joined}) OR description:({joined}))'

def search_archive_roms(q, platform='', page=1, rows=24):
    if platform and platform not in ROM_PLATFORMS: raise ValueError('unsupported platform')
    terms=ROM_SEARCH_BASE+_rom_search_terms(platform)
    q=(q or '').strip(); safe=''
    if q:
        safe=' '.join(re.findall(r'[\w\-\.]{2,}',q,flags=re.UNICODE)[:8])
        if safe: terms=f'({terms}) AND (title:({safe}) OR description:({safe}) OR subject:({safe}) OR creator:({safe}))'
    params=[('q',terms),('fl[]','identifier'),('fl[]','title'),('fl[]','creator'),('fl[]','date'),('fl[]','year'),('fl[]','description'),('fl[]','licenseurl'),('fl[]','rights'),('fl[]','subject'),('fl[]','downloads'),('rows',str(max(1,min(rows,40)))),('page',str(max(1,page))),('output','json'),('sort[]','downloads desc')]
    try:
        data=http_json('https://archive.org/advancedsearch.php?'+urllib.parse.urlencode(params))
    except Exception:
        fallback='mediatype:software AND (subject:homebrew OR subject:freeware OR subject:abandonware OR subject:"public domain")'+_rom_search_terms(platform)
        if q and safe: fallback+=f' AND (title:({safe}) OR description:({safe}) OR subject:({safe}))'
        params=[('q',fallback),('fl[]','identifier'),('fl[]','title'),('fl[]','creator'),('fl[]','date'),('fl[]','year'),('fl[]','description'),('fl[]','licenseurl'),('fl[]','rights'),('fl[]','subject'),('fl[]','downloads'),('rows',str(max(1,min(rows,40)))),('page',str(max(1,page))),('output','json'),('sort[]','downloads desc')]
        data=http_json('https://archive.org/advancedsearch.php?'+urllib.parse.urlencode(params))
    docs=((data.get('response') or {}).get('docs') or [])
    out=[]
    for d in docs:
        ident=str(d.get('identifier') or '')
        if not SAFE_ID.fullmatch(ident): continue
        hint=rom_rights_hint(d)
        out.append({'identifier':ident,'title':str(d.get('title') or ident)[:240],'creator':flatten(d.get('creator'))[:200],'date':str(d.get('date') or d.get('year') or '')[:32],'description':flatten(d.get('description'))[:420],'downloads':intish(d.get('downloads')),'rights_hint':hint,'verified_rights':hint in {'public-domain','creative-commons','permission-stated'},'platform':platform})
    return {'page':page,'platform':platform,'num_found':intish((data.get('response') or {}).get('numFound')),'items':out,'rights_policy':'One-click import requires explicit public-domain, Creative Commons, or redistribution permission in Archive.org item metadata.'}

def rom_candidates(meta, platform=''):
    if platform and platform not in ROM_PLATFORMS: raise ValueError('unsupported platform')
    out=[]; allowed=ROM_PLATFORMS.get(platform,{}).get('exts') if platform else None
    for f in meta.get('files') or []:
        name=str(f.get('name') or '')
        if not name or name.endswith('/') or len(name)>420: continue
        ext=Path(name).suffix.lower()
        if allowed is not None:
            if ext not in allowed: continue
            platforms=[platform]
        else:
            platforms=list(ROM_EXT_PLATFORMS.get(ext,[]))
            if not platforms: continue
        low=name.lower()
        if any(x in low for x in ('__macosx/','/._','thumb','screenshot','manual')): continue
        if str(f.get('private') or '').lower() in {'true','1'}: continue
        out.append({'name':name,'basename':Path(name).name,'ext':ext,'size':intish(f.get('size')),'format':str(f.get('format') or '')[:120],'platforms':platforms})
    out.sort(key=lambda x:(len(x['platforms'])!=1,-x['size'],x['name'].lower()))
    return out[:120]

def rom_item(identifier, platform=''):
    meta=metadata(identifier); m=meta.get('metadata') or {}; rights=rom_rights_status(meta)
    return {'identifier':identifier,'title':str(m.get('title') or identifier)[:240],'creator':flatten(m.get('creator'))[:200],'description':flatten(m.get('description'))[:700],'rights':rights,'platform':platform,'files':rom_candidates(meta,platform),'archive_url':'https://archive.org/details/'+identifier}

def write_rom_provenance(dest, meta, identifier, source_name, rights, platform):
    prov_root=STATE.root/'media/library/console-games/.pcga-source'/platform; prov_root.mkdir(parents=True,exist_ok=True)
    key=re.sub(r'[^A-Za-z0-9._-]+','_',dest.name)[:180]+'.json'
    record={'source':'archive.org','identifier':identifier,'file':source_name,'platform':platform,'destination':str(dest),'rights':rights,'imported_at':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())}
    (prov_root/key).write_text(json.dumps(record,indent=2,sort_keys=True)+'\n',encoding='utf-8')

def start_rom_import(payload):
    identifier=str(payload.get('identifier') or ''); source_name=str(payload.get('file') or ''); platform=str(payload.get('platform') or '').strip().lower()
    if not SAFE_ID.fullmatch(identifier) or platform not in ROM_PLATFORMS: raise ValueError('invalid identifier or platform')
    if not source_name or len(source_name)>420 or source_name.startswith('/') or '..' in Path(source_name).parts: raise ValueError('invalid ROM file')
    jid=uuid.uuid4().hex[:16]
    job={'id':jid,'kind':'rom','identifier':identifier,'file':source_name,'platform':platform,'state':'queued','progress':0,'bytes_done':0,'bytes_total':0,'title':Path(source_name).stem,'message':'Queued for ROM collection','created_at':time.time()}
    with STATE.lock: STATE.jobs[jid]=job; STATE.save_job(job)
    threading.Thread(target=run_rom_import,args=(jid,),daemon=True).start(); return job

def request_romm_rescan():
    req=urllib.request.Request('http://127.0.0.1:8098/api/games/rescan',data=b'{}',headers={'Content-Type':'application/json','User-Agent':UA},method='POST')
    try:
        with urllib.request.urlopen(req,timeout=8) as r:
            data=json.loads(r.read().decode('utf-8','replace') or '{}')
            return bool(data.get('ok')), str(data.get('detail') or data.get('state') or '')[:240]
    except Exception as exc:
        return False, type(exc).__name__

def run_rom_import(jid):
    j=STATE.jobs[jid]; tmp=None
    try:
        update_job(jid,state='metadata',message='Validating Archive.org ROM metadata and rights')
        meta=metadata(j['identifier']); rights=rom_rights_status(meta)
        if not rights['allowed']: raise RuntimeError('Rights review required: '+rights['detail'])
        candidates={x['name']:x for x in rom_candidates(meta,j['platform'])}; cand=candidates.get(j['file'])
        if not cand: raise RuntimeError('The selected file is not a supported ROM for this platform.')
        folder=STATE.root/'media/library/console-games/roms'/j['platform']; folder.mkdir(parents=True,exist_ok=True)
        dest=folder/safe_name(Path(j['file']).name)
        prov=STATE.root/'media/library/console-games/.pcga-source'/j['platform']/(re.sub(r'[^A-Za-z0-9._-]+','_',dest.name)[:180]+'.json')
        if dest.exists() and prov.exists():
            try:
                prior=json.loads(prov.read_text(encoding='utf-8'))
                if prior.get('identifier')==j['identifier'] and prior.get('file')==j['file']:
                    update_job(jid,state='complete',progress=100,bytes_done=dest.stat().st_size,bytes_total=dest.stat().st_size,message='Already present in the RomM library',destination=str(dest),rights=rights); return
            except Exception: pass
        if dest.exists(): raise RuntimeError(f'Destination already exists: {dest.name}')
        tmp=dest.with_name(dest.name+'.part')
        url='https://archive.org/download/'+urllib.parse.quote(j['identifier'],safe='')+'/'+urllib.parse.quote(j['file'],safe='/')
        req=urllib.request.Request(url,headers={'User-Agent':UA})
        update_job(jid,state='downloading',message=f'Downloading {Path(j["file"]).name}',bytes_total=cand['size'] or 0)
        with urllib.request.urlopen(req,timeout=30) as r, open(tmp,'wb') as out:
            total=intish(r.headers.get('Content-Length')) or cand['size']; done=0; last=0
            while True:
                chunk=r.read(1024*1024)
                if not chunk: break
                out.write(chunk); done+=len(chunk); now=time.time()
                if now-last>.6:
                    update_job(jid,bytes_done=done,bytes_total=total,progress=round(done*100/total,1) if total else 0); last=now
            out.flush(); os.fsync(out.fileno())
        os.replace(tmp,dest); tmp=None
        try:
            st=folder.stat(); os.chown(dest,st.st_uid,st.st_gid); os.chmod(dest,0o644)
        except OSError: pass
        write_rom_provenance(dest,meta,j['identifier'],j['file'],rights,j['platform'])
        scan_ok,scan_detail=request_romm_rescan()
        msg='Imported and queued for RomM indexing' if scan_ok else 'Imported; RomM filesystem watcher will index it automatically'
        update_job(jid,state='complete',progress=100,bytes_done=dest.stat().st_size,bytes_total=dest.stat().st_size,message=msg,destination=str(dest),rights=rights,rescan_requested=scan_ok,rescan_detail=scan_detail)
    except Exception as e:
        if tmp:
            try: tmp.unlink(missing_ok=True)
            except Exception: pass
        try:update_job(jid,state='error',message=str(e)[:700])
        except Exception:pass

def safe_name(s):
    s=re.sub(r'[<>:"/\\|?*\x00-\x1f]',' ',str(s or 'Untitled'))
    s=re.sub(r'\s+',' ',s).strip(' .')
    return (s or 'Untitled')[:180]

def year_from(meta):
    m=meta.get('metadata') or {}
    for v in (m.get('year'),m.get('date')):
        mm=re.search(r'\b(18|19|20)\d{2}\b',str(v or ''))
        if mm:return mm.group(0)
    return ''

def write_nfo(dest: Path, meta, identifier, rights):
    m=meta.get('metadata') or {}
    title=safe_name(m.get('title') or identifier); year=year_from(meta); plot=flatten(m.get('description'))[:3000]
    creator=flatten(m.get('creator'))[:500]
    xml=['<?xml version="1.0" encoding="UTF-8"?>','<movie>',f'  <title>{xesc(title)}</title>']
    if year: xml.append(f'  <year>{year}</year>')
    if plot: xml.append(f'  <plot>{xesc(plot)}</plot>')
    if creator: xml.append(f'  <studio>{xesc(creator)}</studio>')
    xml += ['  <tag>Internet Archive</tag>',f'  <tag>{xesc(rights.get("basis","rights-unknown"))}</tag>',f'  <uniqueid type="archiveorg">{xesc(identifier)}</uniqueid>','</movie>']
    dest.with_suffix('.nfo').write_text('\n'.join(xml)+'\n',encoding='utf-8')
    dest.with_suffix('.pcga-source.json').write_text(json.dumps({'source':'archive.org','identifier':identifier,'rights':rights,'imported_at':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())},indent=2),encoding='utf-8')

def start_import(payload):
    identifier=str(payload.get('identifier') or '')
    source=str(payload.get('source') or '')
    library=str(payload.get('library') or '')
    quality=str(payload.get('quality') or 'balanced')
    if source not in SOURCES or not SAFE_ID.fullmatch(identifier): raise ValueError('invalid source or identifier')
    if library not in {'movies','home-videos'}: library=SOURCES[source]['default']
    if quality not in {'compact','balanced','best'}: quality='balanced'
    jid=uuid.uuid4().hex[:16]
    job={'id':jid,'identifier':identifier,'source':source,'library':library,'quality':quality,'state':'queued','progress':0,'bytes_done':0,'bytes_total':0,'title':identifier,'message':'Queued','created_at':time.time()}
    with STATE.lock: STATE.jobs[jid]=job; STATE.save_job(job)
    t=threading.Thread(target=run_import,args=(jid,),daemon=True); t.start()
    return job

def update_job(jid,**kw):
    with STATE.lock:
        j=STATE.jobs[jid]; j.update(kw); STATE.save_job(j); return dict(j)

def run_import(jid):
    j=STATE.jobs[jid]
    try:
        update_job(jid,state='metadata',message='Reading Internet Archive metadata')
        meta=metadata(j['identifier']); m=meta.get('metadata') or {}
        title=safe_name(m.get('title') or j['identifier']); year=year_from(meta)
        rights=rights_status(meta,j['source'])
        if not rights['allowed']: raise RuntimeError(rights['detail'])
        score,size,name,fmt=choose_video(meta,j['quality'])
        final_base=title+(f' ({year})' if year else '')
        if j['library']=='movies':
            folder=STATE.root/'media/library/movies'/final_base; folder.mkdir(parents=True,exist_ok=True)
            dest=folder/(final_base+Path(name).suffix.lower())
        else:
            folder=STATE.root/'media/library/home-videos'/'Internet Archive'; folder.mkdir(parents=True,exist_ok=True)
            dest=folder/(final_base+Path(name).suffix.lower())
        if dest.exists(): raise RuntimeError(f'Destination already exists: {dest.name}')
        tmp=dest.with_name(dest.name+'.part')
        url='https://archive.org/download/'+urllib.parse.quote(j['identifier'],safe='')+'/'+urllib.parse.quote(name,safe='')
        req=urllib.request.Request(url,headers={'User-Agent':UA})
        update_job(jid,state='downloading',title=title,filename=name,format=fmt,message=f'Downloading {name}',bytes_total=size or 0)
        with urllib.request.urlopen(req,timeout=30) as r, open(tmp,'wb') as out:
            total=intish(r.headers.get('Content-Length')) or size
            done=0; last=0
            while True:
                chunk=r.read(1024*1024)
                if not chunk: break
                out.write(chunk); done+=len(chunk)
                now=time.time()
                if now-last>.6:
                    update_job(jid,bytes_done=done,bytes_total=total,progress=round(done*100/total,1) if total else 0); last=now
            out.flush(); os.fsync(out.fileno())
        os.replace(tmp,dest)
        write_nfo(dest,meta,j['identifier'],rights)
        helper=Path('/usr/local/sbin/pcga-jellyfin-refresh')
        if helper.exists(): subprocess.run([str(helper)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=False)
        update_job(jid,state='complete',progress=100,bytes_done=dest.stat().st_size,bytes_total=dest.stat().st_size,message=f'Imported to {j["library"]}',destination=str(dest),rights=rights)
    except Exception as e:
        try:
            update_job(jid,state='error',message=str(e)[:700])
        except Exception: pass


def _session_dir(session_id):
    if not UPLOAD_SESSION_RE.fullmatch(str(session_id or '')): raise ValueError('invalid upload session')
    return STATE.upload_staging/str(session_id)

def _session_meta_path(session_id): return _session_dir(session_id)/'session.json'

def _read_session(session_id):
    p=_session_meta_path(session_id)
    try: data=json.loads(p.read_text(encoding='utf-8'))
    except Exception as exc: raise ValueError('unknown upload session') from exc
    if not isinstance(data,dict) or data.get('id')!=session_id: raise ValueError('invalid upload session')
    return data

def _write_session(data):
    d=_session_dir(data['id']); d.mkdir(parents=True,exist_ok=True)
    p=d/'session.json'; tmp=p.with_suffix('.tmp')
    tmp.write_text(json.dumps(data,indent=2,sort_keys=True)+'\n',encoding='utf-8'); os.replace(tmp,p)

def _clean_relative_path(value):
    raw=str(value or '').replace('\\','/').strip('/')
    parts=[x for x in raw.split('/') if x not in {'','.'}]
    if not parts or len(parts)>24 or any(x=='..' for x in parts): raise ValueError('invalid upload path')
    cleaned=[]
    for part in parts:
        name=safe_name(part)
        if name in {'','.','..'}: raise ValueError('invalid upload filename')
        cleaned.append(name)
    rel=Path(*cleaned)
    if len(str(rel))>900: raise ValueError('upload path is too long')
    return rel

def start_user_upload_session(payload):
    hint=str(payload.get('hint') or 'auto').strip().lower()
    platform=str(payload.get('platform') or '').strip().lower()
    if hint not in UPLOAD_HINTS: raise ValueError('invalid content type')
    if hint=='rom' and platform and platform not in ROM_PLATFORMS: raise ValueError('invalid ROM platform')
    session_id=uuid.uuid4().hex
    data={'id':session_id,'kind':'user-upload','hint':hint,'platform':platform,'state':'open','created_at':time.time(),'files':[],'bytes_total':0}
    d=_session_dir(session_id); (d/'files').mkdir(parents=True,exist_ok=False); _write_session(data)
    return {'ok':True,'session':session_id,'hint':hint,'platform':platform,'max_file_bytes':MAX_UPLOAD_BYTES}

def receive_user_upload(handler, session_id, relative_path, length):
    if length<=0 or length>MAX_UPLOAD_BYTES: raise ValueError(f'file size must be between 1 and {MAX_UPLOAD_BYTES} bytes')
    with STATE.lock:
        session=_read_session(session_id)
        if session.get('state')!='open': raise ValueError('upload session is not open')
    rel=_clean_relative_path(relative_path)
    base=(_session_dir(session_id)/'files').resolve()
    dest=(base/rel).resolve()
    if base not in dest.parents: raise ValueError('invalid upload destination')
    dest.parent.mkdir(parents=True,exist_ok=True)
    if dest.exists() or dest.with_name(dest.name+'.part').exists(): raise ValueError('a file with this path is already in the upload session')
    tmp=dest.with_name(dest.name+'.part'); h=hashlib.sha256(); remaining=length; written=0
    try:
        with tmp.open('xb') as out:
            while remaining:
                chunk=handler.rfile.read(min(1024*1024,remaining))
                if not chunk: raise ConnectionError('upload ended before Content-Length bytes were received')
                out.write(chunk); h.update(chunk); remaining-=len(chunk); written+=len(chunk)
            out.flush(); os.fsync(out.fileno())
        os.replace(tmp,dest)
    except Exception:
        try: tmp.unlink(missing_ok=True)
        except Exception: pass
        raise
    record={'path':rel.as_posix(),'size':written,'sha256':h.hexdigest()}
    with STATE.lock:
        session=_read_session(session_id)
        if session.get('state')!='open':
            dest.unlink(missing_ok=True); raise ValueError('upload session was closed during transfer')
        session.setdefault('files',[]).append(record); session['bytes_total']=int(session.get('bytes_total') or 0)+written; _write_session(session)
    return {'ok':True,'session':session_id,'file':record,'received':written}

def _unit_files(path):
    if path.is_file(): return [path]
    return [x for x in path.rglob('*') if x.is_file() and not x.name.startswith('.pcga-')]

def _rom_candidates_for_unit(path):
    files=_unit_files(path); payload=[]; candidates=None
    for f in files:
        ext=f.suffix.lower()
        plats=set(ROM_EXT_PLATFORMS.get(ext,[]))
        if plats:
            payload.append(f); candidates=plats if candidates is None else candidates & plats
        elif ext in UPLOAD_SIDECAR_EXT:
            continue
        else:
            return set()
    return set(candidates or ()) if payload else set()

def infer_rom_platform(path):
    files=_unit_files(path)
    exts={f.suffix.lower() for f in files}
    # .bin is far too overloaded to identify Genesis safely: it is also common
    # in cue/bin optical dumps. Require an explicit platform or folder-name hint.
    candidates=set() if '.bin' in exts else _rom_candidates_for_unit(path)
    if len(candidates)==1: return next(iter(candidates))
    # A top-level folder named for a known platform is a useful local hint for
    # ambiguous CD images without relying on Internet metadata.
    low=path.stem.lower().replace('_','-').replace(' ','-')
    for slug,info in ROM_PLATFORMS.items():
        aliases={slug,*(str(x).lower().replace(' ','-') for x in info.get('terms',[]))}
        if any(a and (low==a or low.startswith(a+'-') or low.endswith('-'+a)) for a in aliases): return slug
    return ''

def _unique_destination(dest):
    if not dest.exists(): return dest
    stamp=time.strftime('%Y%m%d-%H%M%S')
    base=dest.with_name(f'{dest.stem}-upload-{stamp}{dest.suffix}' if dest.is_file() or dest.suffix else f'{dest.name}-upload-{stamp}')
    candidate=base; i=1
    while candidate.exists():
        i+=1; candidate=base.with_name(f'{base.stem}-{i}{base.suffix}') if base.suffix else base.with_name(f'{base.name}-{i}')
    return candidate

def _move_unit(src,dest):
    dest.parent.mkdir(parents=True,exist_ok=True); dest=_unique_destination(dest)
    shutil.move(str(src),str(dest)); return dest

def route_rom_unit(src,platform):
    if platform not in ROM_PLATFORMS: raise ValueError('ROM platform is required for this upload')
    root=STATE.root/'media/library/console-games/roms'/platform; root.mkdir(parents=True,exist_ok=True)
    dest=root/safe_name(src.name); dest=_move_unit(src,dest)
    try:
        for p in [dest,*list(dest.rglob('*'))] if dest.is_dir() else [dest]:
            os.chmod(p,0o755 if p.is_dir() else 0o644)
    except OSError: pass
    return dest

def route_photo_unit(src):
    root=STATE.root/'media/library/photos'/'Uploads'; root.mkdir(parents=True,exist_ok=True)
    if src.is_file():
        folder=root/time.strftime('%Y-%m',time.localtime())
        dest=folder/safe_name(src.name)
    else:
        dest=root/safe_name(src.name)
    return _move_unit(src,dest)

def route_explicit_unit(src,hint):
    mapping={'pc-game':'ingest/inbox/pc-games','software':'ingest/inbox/software','disc-image':'ingest/inbox/disc-images','home-video':'media/library/home-videos/Uploads'}
    rel=mapping[hint]; root=STATE.root/rel; root.mkdir(parents=True,exist_ok=True)
    return _move_unit(src,root/safe_name(src.name))

def queue_for_classifier(src,hint='auto'):
    pending=STATE.root/'media/metadata-pending'; pending.mkdir(parents=True,exist_ok=True)
    stamp=time.strftime('%Y%m%d-%H%M%S'); dest=_unique_destination(pending/f'{stamp}-upload-{safe_name(src.name)}')
    shutil.move(str(src),str(dest))
    source_hint={'movie':'movie','tv':'tv','music':'music','home-video':'home-video','photos':'photos'}.get(hint,'user-upload')
    hp=dest/'.pcga-source-hint' if dest.is_dir() else dest.with_name(dest.name+'.pcga-source-hint')
    hp.write_text(source_hint+'\n',encoding='utf-8')
    env=os.environ.copy(); env['PCGA_ROOT_OVERRIDE']=str(STATE.root); env['PCGA_CLASSIFY_SETTLE_SECONDS']='0'
    proc=subprocess.run(['/usr/local/sbin/pcga-classify',str(dest)],env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=90,check=False)
    return dest,proc.returncode,(proc.stdout or '')[-1400:]

def _classify_upload_unit(src,hint,platform):
    files=_unit_files(src); exts={f.suffix.lower() for f in files}
    if not files: return {'state':'review','category':'empty','message':'No regular files were found'}
    if hint=='rom':
        plat=platform or infer_rom_platform(src)
        if not plat: return {'state':'review','category':'console-game','message':'Console game platform could not be inferred; choose a platform and upload again'}
        dest=route_rom_unit(src,plat); return {'state':'imported','category':'console-game','platform':plat,'destination':str(dest)}
    if hint=='photos':
        if all(x in IMAGE_EXT for x in exts):
            dest=route_photo_unit(src); return {'state':'imported','category':'photos','destination':str(dest)}
        return {'state':'review','category':'photos','message':'Photo override contained non-image files; retained for review'}
    if hint in {'pc-game','software','disc-image','home-video'}:
        dest=route_explicit_unit(src,hint); return {'state':'imported','category':hint,'destination':str(dest)}
    if hint=='auto':
        plat=infer_rom_platform(src)
        if plat:
            dest=route_rom_unit(src,plat); return {'state':'imported','category':'console-game','platform':plat,'destination':str(dest)}
        if exts and all(x in IMAGE_EXT for x in exts):
            dest=route_photo_unit(src); return {'state':'imported','category':'photos','destination':str(dest)}
    pending,rc,output=queue_for_classifier(src,hint)
    if rc!=0: return {'state':'review','category':'classifier','message':'Classifier returned an error','detail':output}
    if pending.exists(): return {'state':'review','category':'classifier','message':'Queued for Manual Review','destination':str(pending)}
    return {'state':'imported','category':'classifier','message':'Classified and routed automatically'}

def start_user_upload_commit(payload):
    sid=str(payload.get('session') or '')
    with STATE.lock:
        session=_read_session(sid)
        if session.get('state')!='open': raise ValueError('upload session is already committed')
        if not session.get('files'): raise ValueError('upload session has no files')
        if session.get('hint')=='rom' and not session.get('platform'):
            # Auto inference remains allowed; ambiguous images become review rather
            # than being guessed into the wrong console library.
            pass
        session['state']='committed'; session['committed_at']=time.time(); _write_session(session)
        jid='upload-'+sid[:20]
        job={'id':jid,'kind':'user-upload','session':sid,'title':f"User upload ({len(session.get('files') or [])} file(s))",'state':'queued','progress':100,'bytes_done':int(session.get('bytes_total') or 0),'bytes_total':int(session.get('bytes_total') or 0),'message':'Upload complete; sorting and categorizing','created_at':time.time(),'hint':session.get('hint'),'platform':session.get('platform'),'results':[]}
        STATE.jobs[jid]=job; STATE.save_job(job)
    threading.Thread(target=run_user_upload_import,args=(jid,),daemon=True).start(); return dict(job)

def run_user_upload_import(jid):
    j=STATE.jobs[jid]; sid=j['session']; session=_read_session(sid); files_root=_session_dir(sid)/'files'
    try:
        units=sorted(list(files_root.iterdir()),key=lambda p:p.name.lower())
        if not units: raise RuntimeError('Upload session contained no files')
        results=[]; imported=0; review=0; rom_changed=False; media_changed=False; pc_game_changed=False
        update_job(jid,state='sorting',progress=100,message=f'Sorting {len(units)} uploaded item(s)')
        for idx,src in enumerate(units,1):
            if not src.exists(): continue
            try: result=_classify_upload_unit(src,str(session.get('hint') or 'auto'),str(session.get('platform') or ''))
            except Exception as exc: result={'state':'review','category':'error','message':str(exc)[:500]}
            # A result marked for review may intentionally have left the source
            # in staging (for example a Photos override containing non-images).
            # Move that source exactly once into the normal classifier/review
            # queue before recording the result.
            if result.get('state')!='imported' and src.exists():
                try:
                    pending,_,_ = queue_for_classifier(src,'auto')
                    result['destination']=str(pending)
                    result['message']=result.get('message') or 'Queued for Manual Review'
                except Exception as exc:
                    result={'state':'error','category':'unrouted','message':str(exc)[:500]}
            result['name']=src.name; results.append(result)
            if result.get('state')=='imported': imported+=1
            else: review+=1
            if result.get('category')=='console-game' and result.get('state')=='imported': rom_changed=True
            if result.get('category')=='pc-game' and result.get('state')=='imported': pc_game_changed=True
            if result.get('category') in {'photos','classifier','home-video'} and result.get('state')=='imported': media_changed=True
            update_job(jid,results=results,message=f'Sorted {idx}/{len(units)} item(s)')
        # Safety net for a unit left behind by an unexpected classifier failure.
        for src in list(files_root.iterdir()) if files_root.exists() else []:
            if not src.exists(): continue
            try:
                pending,_,_ = queue_for_classifier(src,'auto'); review+=1
                results.append({'name':src.name,'state':'review','category':'classifier','message':'Queued for Manual Review','destination':str(pending)})
            except Exception as exc:
                review+=1
                results.append({'name':src.name,'state':'error','category':'unrouted','message':str(exc)[:500]})
        if rom_changed: request_romm_rescan()
        if pc_game_changed:
            subprocess.run(['systemctl','--no-block','start','pcga-game-orchestrator.service'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=False)
        if media_changed:
            helper=Path('/usr/local/sbin/pcga-jellyfin-refresh')
            if helper.exists(): subprocess.run([str(helper)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=False)
        try: shutil.rmtree(_session_dir(sid))
        except OSError: pass
        state='complete' if review==0 else 'review'
        msg=f'Imported {imported} item(s)' + (f'; {review} item(s) need review' if review else '')
        update_job(jid,state=state,progress=100,message=msg,results=results,imported=imported,review=review,completed_at=time.time())
    except Exception as exc:
        update_job(jid,state='error',message=str(exc)[:700])

def theme_script():
    # Same storage contract as the main portal; keep intentionally compact.
    return r"""(()=>{const KEY='pcga-portal-customization-v1';const S={ember:{bg:'#1a110b',deep:'#090604',panel:'#2a190e',accent:'#e8a15e',text:'#fff4e6'},midnight:{bg:'#0b1320',deep:'#04070d',panel:'#111f31',accent:'#62b5ff',text:'#edf7ff'},forest:{bg:'#0d1813',deep:'#050a07',panel:'#13251c',accent:'#78c58f',text:'#edf9f0'},plum:{bg:'#180f1e',deep:'#08050b',panel:'#28152f',accent:'#d291ff',text:'#fbf1ff'},graphite:{bg:'#151719',deep:'#08090a',panel:'#22262b',accent:'#c3ced8',text:'#f3f6f8'},ocean:{bg:'#071a1d',deep:'#031012',panel:'#0d2a2d',accent:'#4fd1c5',text:'#e9fffd'},burgundy:{bg:'#1c0b10',deep:'#0b0406',panel:'#2b1119',accent:'#ef7d9a',text:'#fff0f4'},terminal:{bg:'#07110a',deep:'#020503',panel:'#0d1e12',accent:'#72e68f',text:'#eaffef'}};let r={};try{r=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(_){}const t=S[r.scheme]||S.ember;const root=document.documentElement;root.style.setProperty('--bg',t.bg);root.style.setProperty('--deep',t.deep);root.style.setProperty('--panel',t.panel);root.style.setProperty('--accent',t.accent);root.style.setProperty('--text',t.text);root.style.setProperty('--radius',Math.max(0,Math.min(30,Number(r.radius??26)))+'px');document.body.dataset.pattern=['ambient','solid','grid','dots','diagonal'].includes(r.pattern)?r.pattern:'ambient'})();"""

def page_html():
    opts=''.join(f'<option value="{html.escape(k)}">{html.escape(v["name"])}</option>' for k,v in SOURCES.items())
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Public Media</title><style>
:root{{--bg:#1a110b;--deep:#090604;--panel:#2a190e;--accent:#e8a15e;--text:#fff4e6;--radius:26px}}*{{box-sizing:border-box}}body{{margin:0;min-height:100vh;color:var(--text);background:linear-gradient(180deg,var(--bg),var(--deep));font:18px/1.45 system-ui,sans-serif}}body:before{{content:"";position:fixed;inset:0;pointer-events:none;opacity:.35;background:radial-gradient(circle at 20% 20%,var(--accent),transparent 28%)}}body[data-pattern="grid"]:before{{background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:32px 32px}}body[data-pattern="dots"]:before{{background-image:radial-gradient(rgba(255,255,255,.12) 1.5px,transparent 1.5px);background-size:28px 28px}}body[data-pattern="diagonal"]:before{{background-image:repeating-linear-gradient(135deg,rgba(255,255,255,.055) 0 2px,transparent 2px 26px)}}main{{position:relative;z-index:1;max-width:1180px;margin:auto;padding:32px}}header{{display:flex;gap:18px;align-items:center;justify-content:space-between;flex-wrap:wrap}}h1{{margin:0;font-size:clamp(30px,5vw,54px)}}a{{color:inherit}}.panel,.card{{border:1px solid color-mix(in srgb,var(--accent) 30%,transparent);background:color-mix(in srgb,var(--panel) 88%,transparent);border-radius:var(--radius);backdrop-filter:blur(15px)}}.panel{{padding:18px;margin-top:22px}}.controls{{display:grid;grid-template-columns:180px 1fr auto;gap:10px}}select,input,button{{min-height:48px;border-radius:calc(var(--radius)*.55);border:1px solid color-mix(in srgb,var(--accent) 34%,transparent);background:rgba(255,255,255,.06);color:var(--text);padding:0 14px;font:inherit}}button{{font-weight:800;cursor:pointer}}button.primary{{background:color-mix(in srgb,var(--accent) 25%,transparent)}}#results{{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px;margin-top:18px}}.card{{padding:16px;display:flex;flex-direction:column;gap:9px}}.title{{font-size:1.18em;font-weight:900}}.meta,.desc,.rights{{opacity:.76;font-size:.86em}}.desc{{max-height:6em;overflow:hidden}}.actions{{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto}}.badge{{display:inline-block;padding:4px 8px;border-radius:999px;background:rgba(255,255,255,.07);font-size:.74em}}#jobs{{display:grid;gap:9px}}.job{{padding:12px 14px;border-radius:calc(var(--radius)*.65);background:rgba(255,255,255,.05)}}progress{{width:100%}}@media(max-width:680px){{main{{padding:20px}}.controls{{grid-template-columns:1fr}}}}
</style></head><body><main><header><div><h1>Public Media</h1><div>Rights-aware Internet Archive imports for Jellyfin.</div></div><a href="/">← Media Hub</a></header><section class="panel"><div class="controls"><select id="source">{opts}</select><input id="q" placeholder="Search titles, creators, descriptions"><button id="search" class="primary">Search</button></div><p class="meta">PCGA downloads a local copy into Jellyfin. Feature Films defaults to Movies; Classic TV and Prelinger default to Home Videos until episode metadata can be mapped safely.</p></section><section id="results"></section><section class="panel"><h2>Imports</h2><div id="jobs"><div class="meta">No imports started in this session.</div></div></section></main><script>{theme_script()}</script><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));let items=[];
async function search(){{const s=document.getElementById('source').value,q=document.getElementById('q').value;const r=await fetch(`/public-media/api/search?source=${{encodeURIComponent(s)}}&q=${{encodeURIComponent(q)}}`);const d=await r.json();if(!r.ok)throw Error(d.error||r.status);items=d.items||[];render()}}
function render(){{const box=document.getElementById('results');if(!items.length){{box.innerHTML='<div class="panel">No matching items.</div>';return}}box.innerHTML=items.map((x,i)=>`<article class="card"><div><span class="badge">${{esc(x.rights_hint)}}</span></div><div class="title">${{esc(x.title)}}</div><div class="meta">${{esc(x.creator)}} ${{x.date?'• '+esc(x.date):''}}</div><div class="desc">${{esc(x.description)}}</div><div class="actions"><button data-import="${{i}}" data-lib="movies">Movies</button><button data-import="${{i}}" data-lib="home-videos">Home Videos</button><a href="https://archive.org/details/${{encodeURIComponent(x.identifier)}}" target="_blank" rel="noopener">Archive page</a></div></article>`).join('')}}
async function doImport(i,lib){{const x=items[i];if(!x)return;const r=await fetch('/public-media/api/import',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{identifier:x.identifier,source:x.source,library:lib,quality:'balanced'}})}});const d=await r.json();if(!r.ok)alert(d.error||r.status);pollJobs()}}
async function pollJobs(){{try{{const r=await fetch('/public-media/api/jobs',{{cache:'no-store'}}),d=await r.json();const js=d.jobs||[];document.getElementById('jobs').innerHTML=js.length?js.map(j=>`<div class="job"><b>${{esc(j.title||j.identifier)}}</b> — ${{esc(j.state)}}<div class="meta">${{esc(j.message||'')}}</div><progress max="100" value="${{Number(j.progress||0)}}"></progress></div>`).join(''):'<div class="meta">No imports started in this session.</div>'}}catch(_){{}}}}
document.getElementById('search').onclick=()=>search().catch(e=>alert(e.message));document.getElementById('q').addEventListener('keydown',e=>{{if(e.key==='Enter')search().catch(x=>alert(x.message))}});document.addEventListener('click',e=>{{const b=e.target.closest('[data-import]');if(b)doImport(Number(b.dataset.import),b.dataset.lib)}});setInterval(pollJobs,1500);pollJobs();search().catch(()=>{{}});
</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
    server_version=f'PCGAPublicMedia/{VERSION}'
    def log_message(self,fmt,*args):
        if urllib.parse.urlparse(self.path).path not in {'/health','/api/rom/jobs'}: super().log_message(fmt,*args)
    def send_json(self,status,obj):
        body=json.dumps(obj,separators=(',',':')).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.send_header('Cache-Control','no-store'); self.end_headers(); self.wfile.write(body)
    def do_GET(self):
        u=urllib.parse.urlparse(self.path); p=u.path
        if p=='/health': return self.send_json(200,{'ok':True,'version':VERSION})
        if p in {'/','/index.html'}:
            b=page_html().encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.send_header('Content-Security-Policy',"default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data: https://archive.org; media-src 'self'"); self.end_headers(); self.wfile.write(b); return
        if p=='/api/search':
            q=urllib.parse.parse_qs(u.query); source=(q.get('source') or ['feature_films'])[0]; term=(q.get('q') or [''])[0]
            if source not in SOURCES:return self.send_json(400,{'error':'unknown source'})
            try:return self.send_json(200,search_archive(source,term))
            except Exception as e:return self.send_json(502,{'error':str(e)})
        if p=='/api/jobs':
            with STATE.lock: jobs=sorted((dict(x) for x in STATE.jobs.values()),key=lambda x:x.get('created_at',0),reverse=True)[:40]
            return self.send_json(200,{'jobs':jobs})
        if p in {'/api/rom/platforms','/api/user-upload/platforms'}:
            return self.send_json(200,{'items':[{'slug':k,'name':v['name'],'extensions':sorted(v['exts'])} for k,v in ROM_PLATFORMS.items()]})
        if p=='/api/user-upload/jobs':
            with STATE.lock: jobs=sorted((dict(x) for x in STATE.jobs.values() if x.get('kind')=='user-upload'),key=lambda x:x.get('created_at',0),reverse=True)[:24]
            return self.send_json(200,{'jobs':jobs})
        if p=='/api/rom/jobs':
            with STATE.lock: jobs=sorted((dict(x) for x in STATE.jobs.values() if x.get('kind')=='rom'),key=lambda x:x.get('created_at',0),reverse=True)[:24]
            return self.send_json(200,{'jobs':jobs})
        if p=='/api/rom/search':
            q=urllib.parse.parse_qs(u.query); term=(q.get('q') or [''])[0]; platform=(q.get('platform') or [''])[0]; page=intish((q.get('page') or ['1'])[0]) or 1
            try:return self.send_json(200,search_archive_roms(term,platform,page))
            except Exception as e:return self.send_json(502,{'error':str(e)})
        if p=='/api/rom/item':
            q=urllib.parse.parse_qs(u.query); ident=(q.get('identifier') or [''])[0]; platform=(q.get('platform') or [''])[0]
            try:return self.send_json(200,rom_item(ident,platform))
            except Exception as e:return self.send_json(400,{'error':str(e)})
        return self.send_json(404,{'error':'not found'})
    def do_POST(self):
        u=urllib.parse.urlparse(self.path); post_path=u.path
        if post_path=='/api/user-upload/file':
            try:
                n=int(self.headers.get('Content-Length','0'))
                q=urllib.parse.parse_qs(u.query); sid=(q.get('session') or [''])[0]; rel=(q.get('path') or [''])[0]
                result=receive_user_upload(self,sid,rel,n); return self.send_json(201,result)
            except Exception as e:
                # A rejected raw-body upload may still have unread bytes on the
                # connection. Do not allow those bytes to be parsed as a second
                # HTTP request on this socket.
                self.close_connection=True
                return self.send_json(400,{'error':str(e)})
        if post_path not in {'/api/import','/api/rom/import','/api/user-upload/session','/api/user-upload/commit'}: return self.send_json(404,{'error':'not found'})
        try:
            n=int(self.headers.get('Content-Length','0')); assert 0<n<=65536
            payload=json.loads(self.rfile.read(n))
            if post_path=='/api/rom/import': job=start_rom_import(payload)
            elif post_path=='/api/user-upload/session': return self.send_json(201,start_user_upload_session(payload))
            elif post_path=='/api/user-upload/commit': job=start_user_upload_commit(payload)
            else: job=start_import(payload)
            return self.send_json(202,job)
        except Exception as e:return self.send_json(400,{'error':str(e)})

def main():
    global STATE
    ap=argparse.ArgumentParser(); ap.add_argument('command',nargs='?',default='serve'); ap.add_argument('--root',default=os.environ.get('PCGA_ARCHIVE_ROOT') or (Path('/etc/pc-game-archive/archive-root').read_text().strip() if Path('/etc/pc-game-archive/archive-root').exists() else '')); ap.add_argument('--bind',default='127.0.0.1'); ap.add_argument('--port',type=int,default=8099)
    a=ap.parse_args(); root=Path(a.root)
    if not root.is_absolute(): raise SystemExit('archive root must be absolute')
    STATE=State(root)
    if a.command=='serve': ThreadingHTTPServer((a.bind,a.port),Handler).serve_forever()
    elif a.command=='search': print(json.dumps(search_archive('feature_films',''),indent=2))
    else: raise SystemExit('unknown command')
if __name__=='__main__': main()
PCGA_PUBLIC_MEDIA
chmod 0755 /usr/local/sbin/pcga-public-media
install -d -m 0755 /var/lib/pc-game-archive/public-media
PUBLIC_MEDIA_BIND="$(docker network inspect bridge --format '{{(index .IPAM.Config 0).Gateway}}' 2>/dev/null || true)"
[[ -n "$PUBLIC_MEDIA_BIND" ]] || PUBLIC_MEDIA_BIND="127.0.0.1"
cat > /etc/systemd/system/pcga-public-media.service <<EOF
[Unit]
Description=PC Game Archive content intake and public media importer
After=network-online.target docker.service
Wants=network-online.target

[Service]
Type=simple
Environment=PCGA_ARCHIVE_ROOT=$ARCHIVE_ROOT
ExecStart=/usr/local/sbin/pcga-public-media serve --root $ARCHIVE_ROOT --bind $PUBLIC_MEDIA_BIND --port 8099
Restart=on-failure
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ReadWritePaths=$ARCHIVE_ROOT /var/lib/pc-game-archive/public-media

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable pcga-game-stack.service >/dev/null 2>&1 || warn "PCGA game-stack startup service could not be enabled"
systemctl enable pcga-service-auth.timer >/dev/null 2>&1 || warn "PCGA service-auth timer could not be enabled"
# Keep reconciliation quiescent until the installer's initial Compose/bootstrap
# transaction is complete. This prevents first-install races with the timer or an
# already-enabled game-stack unit from a previous partial installation.
systemctl stop pcga-service-auth.timer pcga-service-auth.service pcga-game-stack.service >/dev/null 2>&1 || true
systemctl enable pcga-public-media.service >/dev/null 2>&1 || warn "Public media importer could not be enabled"
systemctl restart pcga-public-media.service >/dev/null 2>&1 || warn "Public media importer did not restart with the rendered Docker gateway bind; inspect with: systemctl status pcga-public-media.service"

# ----- Management helper ----------------------------------------------------
cat > /usr/local/bin/game-archive <<'HELPER'
#!/usr/bin/env bash
set -Eeuo pipefail
STACK_DIR=/opt/pc-game-archive
cd "$STACK_DIR"
FILES=(-f compose.yml)
[[ -f compose.jellyfin-gpu.yml ]] && FILES+=(-f compose.jellyfin-gpu.yml)
[[ -f compose.immich.yml ]] && FILES+=(-f compose.immich.yml)
[[ -f compose.romm.yml ]] && FILES+=(-f compose.romm.yml)
[[ -f compose.arm.yml ]] && FILES+=(-f compose.arm.yml)
[[ -f compose.status.yml ]] && FILES+=(-f compose.status.yml)
[[ -f compose.wolf.yml ]] && FILES+=(-f compose.wolf.yml)
[[ -f compose.moonlight-web.yml ]] && FILES+=(-f compose.moonlight-web.yml)
DC=(docker compose "${FILES[@]}")

arm_rip_active() {
  systemctl list-units --all --state=active,activating --plain --no-legend \
    'pcga-arm-rip@*.service' 'pcga-pc-disc-rip@*.service' 2>/dev/null | grep -Eq 'pcga-(arm-rip|pc-disc-rip)@' && return 0
  if docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null | grep -qx true; then
    docker exec arm-rippers sh -lc "ps -eo args | grep -q '[p]ython3 /opt/arm/arm/ripper/main.py'" 2>/dev/null && return 0
  fi
  return 1
}

refuse_if_ripping() {
  if arm_rip_active; then
    echo "Refusing '$1': an optical ingest is active. Let the per-drive ingest service finish first." >&2
    exit 75
  fi
}

case "${1:-status}" in
  up|start)
    refuse_if_ripping "${1:-up}"
    "${DC[@]}" up -d
    ;;
  down|stop)
    refuse_if_ripping "${1:-down}"
    "${DC[@]}" down
    ;;
  restart)
    refuse_if_ripping restart
    "${DC[@]}" restart
    ;;
  status|ps)
    "${DC[@]}" ps
    ;;
  logs)
    shift || true
    if (($#)); then
      "${DC[@]}" logs --tail=200 "$@"
    else
      "${DC[@]}" logs --tail=200
    fi
    ;;
  pull)
    "${DC[@]}" pull
    ;;
  update)
    refuse_if_ripping update
    "${DC[@]}" pull
    "${DC[@]}" up -d --remove-orphans
    ;;
  sort-media|sort)
    sudo /usr/local/sbin/pcga-media-sort
    ;;
  sorter-status)
    systemctl --no-pager --full status pcga-media-sort.path pcga-media-sort.timer pcga-media-sort.service || true
    ;;
  media-audit)
    sudo /usr/local/sbin/pcga-media-audit
    ;;
  media-test)
    sudo /usr/local/sbin/pcga-media-test
    ;;
  manual-sort)
    sudo /usr/local/sbin/pcga-manual-review interactive
    ;;
  manual-review-list)
    sudo /usr/local/sbin/pcga-manual-review list
    ;;
  manual-review-status)
    systemctl --no-pager --full status pcga-manual-review.service || true
    ;;
  manual-review-token)
    sudo /usr/local/sbin/pcga-manual-review token
    ;;
  manual-review-url)
    token="$(sudo /usr/local/sbin/pcga-manual-review token)"
    port="$(awk -F= '$1=="PCGA_STATUS_PORT" {print $2}' .env 2>/dev/null | tail -n1)"
    port="${port:-8098}"
    ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
    host="${ip:-$(hostname)}"
    printf 'http://%s:%s/?review_token=%s#review\n' "$host" "$port" "$token"
    ;;
  manual-review-test)
    sudo /usr/local/sbin/pcga-manual-review-test
    ;;
  classify|metadata-classify)
    sudo /usr/local/sbin/pcga-classify
    ;;
  classification-status|metadata-status)
    systemctl --no-pager --full status pcga-metadata-classify.path pcga-metadata-classify.timer pcga-metadata-classify.service || true
    sudo /usr/local/sbin/pcga-classify --status || true
    journalctl -t PCGA-CLASSIFY -n 40 --no-pager 2>/dev/null || true
    ;;
  tv-reconcile)
    sudo /usr/local/sbin/pcga-classify --repair-tv-layout
    ;;
  tv-reconcile-apply)
    sudo /usr/local/sbin/pcga-classify --repair-tv-layout --apply
    ;;
  jellyfin-configure)
    sudo /usr/local/sbin/pcga-jellyfin-configure
    ;;
  jellyfin-refresh)
    sudo /usr/local/sbin/pcga-jellyfin-refresh
    echo "Jellyfin library refresh requested."
    ;;
  jellyfin-audit)
    sudo /usr/local/sbin/pcga-jellyfin-configure --audit
    ;;
  jellyfin-repair-admin)
    echo "The v0.7.2 startup-mode repair path is disabled. Use: game-archive jellyfin-reset-fresh" >&2
    exit 2
    ;;
  jellyfin-reset-fresh)
    sudo /usr/local/sbin/pcga-jellyfin-configure --reset-fresh
    ;;
  jellyfin-forget-token)
    sudo rm -f /etc/pc-game-archive/jellyfin-api-key
    echo "Removed the saved PC Game Archive Jellyfin API token."
    ;;
  credentials)
    sudo /usr/local/sbin/pcga-appliance-credentials >/dev/null
    sudo cat /etc/pc-game-archive/secrets/appliance-admin.env
    ;;
  immich-status)
    "${DC[@]}" ps immich-server immich-machine-learning immich-redis immich-database
    port="$(awk -F= '$1=="IMMICH_PORT"{print $2}' .env | tail -n1)"; port="${port:-2283}"
    curl -fsS --max-time 3 "http://127.0.0.1:${port}/api/server/ping" || true
    echo
    ;;
  immich-logs)
    "${DC[@]}" logs --tail=200 immich-server immich-machine-learning immich-redis immich-database
    ;;
  immich-restart)
    "${DC[@]}" restart immich-server immich-machine-learning immich-redis immich-database
    ;;
  romm-status)
    "${DC[@]}" ps romm romm-db
    port="$(awk -F= '$1=="ROMM_PORT"{print $2}' .env | tail -n1)"; port="${port:-8082}"
    status_port="$(awk -F= '$1=="PCGA_STATUS_PORT"{print $2}' .env | tail -n1)"; status_port="${status_port:-8098}"
    echo "RomM heartbeat:"
    curl -fsS --max-time 3 "http://127.0.0.1:${port}/api/heartbeat" 2>/dev/null | python3 -m json.tool 2>/dev/null || true
    echo "Portal emulator pipeline:"
    curl -sS --max-time 8 "http://127.0.0.1:${status_port}/api/games/health?refresh=1" 2>/dev/null | python3 -m json.tool 2>/dev/null || true
    ;;
  romm-logs)
    "${DC[@]}" logs --tail=200 romm romm-db
    ;;
  romm-restart)
    "${DC[@]}" restart romm-db romm
    ;;
  arm-metadata-configure)
    shift || true
    sudo /usr/local/sbin/pcga-arm-metadata-configure "$@"
    ;;
  arm-configure)
    sudo /usr/local/sbin/pcga-arm-configure
    echo "ARM unattended archival profile applied. No container restart was performed."
    ;;
  arm-stop)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-arm-stop "${dev#/dev/}"
    ;;
  arm-reconcile)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-arm-reconcile "${dev#/dev/}"
    ;;
  makemkv-sdf-sync)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-makemkv-sdf-sync "${dev#/dev/}"
    ;;
  makemkv-preflight)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-makemkv-preflight "${dev#/dev/}"
    ;;
  pipeline-status)
    port="$(awk -F= '$1=="PCGA_STATUS_PORT" {print $2}' .env 2>/dev/null | tail -n1)"
    port="${port:-8098}"
    curl -fsS "http://127.0.0.1:${port}/api/status" | python3 -m json.tool
    ;;
  pipeline-status-url)
    port="$(awk -F= '$1=="PCGA_STATUS_PORT" {print $2}' .env 2>/dev/null | tail -n1)"
    port="${port:-8098}"
    ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
    printf 'http://%s:%s/\n' "${ip:-$(hostname)}" "$port"
    ;;
  pipeline-status-logs)
    docker logs --tail 100 pcga-status
    ;;
  dedupe-audit)
    shift || true
    sudo /usr/local/sbin/pcga-dedupe audit "$@"
    ;;
  dedupe-run)
    shift || true
    sudo /usr/local/sbin/pcga-dedupe run "$@"
    ;;
  dedupe-library)
    shift || true
    sudo /usr/local/sbin/pcga-dedupe run --include-library-duplicates "$@"
    ;;
  dedupe-status)
    systemctl --no-pager --full status pcga-dedupe.timer pcga-dedupe.service || true
    systemctl list-timers --all pcga-dedupe.timer --no-pager || true
    ;;
  control-status)
    systemctl --no-pager --full status pcga-control.service || true
    ;;
  control-config)
    cat /etc/pc-game-archive/appliance.json
    ;;
  ingest-audit)
    sudo /usr/local/sbin/pcga-ingest-reconcile audit
    ;;
  ingest-reconcile)
    sudo /usr/local/sbin/pcga-ingest-reconcile reconcile
    sudo /usr/local/sbin/pcga-media-sort
    ;;
  raw-review)
    shift || true
    sudo /usr/local/sbin/pcga-raw-recover list "$@"
    ;;
  recover-raw)
    shift || true
    sudo /usr/local/sbin/pcga-raw-recover interactive "$@"
    ;;
  optical-identify)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No optical media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-optical-identify "$dev"
    ;;
  optical-dispatch)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No optical media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-optical-dispatch "${dev#/dev/}"
    ;;
  pc-disc-rip)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No optical media drive assigned" >&2; exit 1; }
    sudo /usr/local/sbin/pcga-pc-disc-rip "${dev#/dev/}"
    ;;
  arm-test)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    echo "Testing ARM trigger for $dev"
    sudo /usr/local/sbin/pcga-arm-rip "${dev#/dev/}"
    ;;
  arm-audit)
    echo "== ARM backend =="
    docker inspect -f 'running={{.State.Running}} image={{.Config.Image}}' arm-rippers 2>/dev/null || true
    echo
    echo "== Assigned drives =="
    while read -r dev; do
      [[ -n "$dev" ]] || continue
      echo "-- $dev --"
      ls -l "$dev" 2>/dev/null || true
      udevadm info --query=property --name="$dev" 2>/dev/null | grep -E '^ID_CDROM(_MEDIA)?|^ID_FS_' || true
      sg="$(lsscsi -g 2>/dev/null | awk -v d="$dev" '$0 ~ d {print $NF; exit}')"
      [[ -n "$sg" ]] && echo "sg device: $sg"
      docker exec arm-rippers test -e "$dev" 2>/dev/null && echo "container sees $dev: yes" || echo "container sees $dev: NO"
    done < /etc/pc-game-archive/media-drives 2>/dev/null
    echo
    echo "== ARM config =="
    if [[ -r .env ]]; then
      ROOT="$(awk -F= '$1=="ARCHIVE_ROOT" {print substr($0,index($0,"=")+1)}' .env)"
      CFG="$ROOT/media/arm/config/arm.yaml"
      if [[ -r "$CFG" ]]; then
        grep -E '^(ARM_CHECK_UDF|GET_VIDEO_TITLE|VIDEOTYPE|METADATA_PROVIDER|GET_AUDIO_TITLE|MANUAL_WAIT|AUTO_EJECT|MAINFEATURE|SKIP_TRANSCODE|DELRAWFILES|MINLENGTH|MAXLENGTH|RIPMETHOD|RIPMETHOD_DVD|RIPMETHOD_BR|ALLOW_DUPLICATES|PREVENT_99|EXTRAS_SUB|RAW_PATH|TRANSCODE_PATH|COMPLETED_PATH):' "$CFG" || true
        sync_provider="$(awk -F': *' '$1=="METADATA_PROVIDER" {gsub(/["[:space:]]/,"",$2); print tolower($2); exit}' "$CFG")"
        echo "ARM synchronous video metadata: ${sync_provider:-unset} (expected none)"
        provider="$(cat /etc/pc-game-archive/arm-metadata-provider 2>/dev/null | tr -d '\r\n[:space:]' | tr '[:upper:]' '[:lower:]')"
        provider="${provider:-omdb}"
        case "$provider" in
          omdb) [[ -s /etc/pc-game-archive/arm-omdb-key ]] && echo 'async OMDb key: configured' || echo 'async OMDb key: MISSING (run game-archive arm-metadata-configure)' ;;
          tmdb) [[ -s /etc/pc-game-archive/arm-tmdb-key ]] && echo 'async TMDb key: configured' || echo 'async TMDb key: MISSING (run game-archive arm-metadata-configure tmdb)' ;;
        esac
      else
        echo "ARM config not created yet: $CFG"
      fi
      echo
      echo "MakeMKV SDF/preflight state:"
      grep -E '^sdf_Stop[[:space:]]*=' "$ROOT/media/arm/home/.MakeMKV/settings.conf" 2>/dev/null || echo 'sdf_Stop: not set'
      for state in /var/lib/pc-game-archive/makemkv-preflight/*.state; do [[ -e "$state" ]] && { echo "-- $state"; cat "$state"; }; done
      echo
      echo "Raw recovery candidates:"
      sudo /usr/local/sbin/pcga-raw-recover list 2>/dev/null | head -n 12 || true
      echo
      echo "Staging usage:"
      du -sh "$ROOT/media/arm/work" "$ROOT/media/arm/music" 2>/dev/null || true
    fi
    echo
    echo "== Recent ARM trigger logs =="
    journalctl -t PCGA-ARM -n 40 --no-pager 2>/dev/null || true
    ;;
  pipeline-audit)
    ROOT="$(cat /etc/pc-game-archive/archive-root 2>/dev/null || true)"
    echo "== Pipeline stage 1: optical assignment =="
    mapfile -t PDRIVES < <(grep -E '^/dev/sr[0-9]+$' /etc/pc-game-archive/media-drives 2>/dev/null || true)
    if (( ${#PDRIVES[@]} == 0 )); then
      echo "FAIL: no optical drive is assigned to PCGA ingest"
      echo "Detected optical drives:"
      lsscsi -g 2>/dev/null | grep -Ei 'cd|dvd|rom' || true
    else
      printf 'assigned: %s\n' "${PDRIVES[@]}"
    fi
    echo
    echo "== Pipeline stage 2: trigger wiring =="
    systemctl is-enabled pcga-optical-watch.service 2>/dev/null || true
    systemctl is-active pcga-optical-watch.service 2>/dev/null || true
    grep -v '^#' /etc/udev/rules.d/52-pcga-media-rip.rules 2>/dev/null || true
    for dev in "${PDRIVES[@]:-}"; do
      [[ -n "$dev" ]] || continue
      name="${dev#/dev/}"
      echo "-- $dev --"
      udevadm info --query=property --name="$dev" 2>/dev/null | grep -E '^ID_CDROM_MEDIA|^ID_FS_|^ID_CDROM_' || true
      systemctl --no-pager --full status "pcga-optical-dispatch@${name}.service" "pcga-arm-rip@${name}.service" "pcga-pc-disc-rip@${name}.service" 2>/dev/null | sed -n '1,24p' || true
    done
    echo
    echo "== Pipeline stage 3: ARM container / drive access =="
    docker inspect -f 'running={{.State.Running}} image={{.Config.Image}}' arm-rippers 2>/dev/null || echo 'FAIL: ARM container missing'
    docker exec arm-rippers sh -lc 'id arm; test -w /home/arm && echo "write /home/arm: yes" || echo "write /home/arm: NO"; test -w /home/arm/media && echo "write /home/arm/media: yes" || echo "write /home/arm/media: NO"; test -w /home/arm/music && echo "write /home/arm/music: yes" || echo "write /home/arm/music: NO"; test -d /home/arm/db && echo "db directory: yes" || echo "db directory: NO"; test -s /home/arm/db/arm.db && echo "arm.db: present" || echo "arm.db: MISSING/EMPTY"' 2>/dev/null || true
    if docker exec arm-rippers sh -lc 'grep -qs "docker_arm_wrapper" /lib/udev/rules.d/51-docker-arm.rules /opt/arm/setup/51-docker-arm.rules 2>/dev/null' 2>/dev/null; then
      echo 'FAIL: ARM internal udev auto-rip rule is still enabled (duplicate trigger path)'
    else
      echo 'ARM internal udev auto-rip rule: disabled (host PCGA trigger is authoritative)'
    fi
    for dev in "${PDRIVES[@]:-}"; do
      [[ -n "$dev" ]] || continue
      docker exec arm-rippers test -b "$dev" 2>/dev/null && echo "container sees $dev: yes" || echo "container sees $dev: NO"
      sg="$(lsscsi -g 2>/dev/null | awk -v d="$dev" '$0 ~ d {print $NF; exit}')"
      if [[ -n "$sg" ]]; then docker exec arm-rippers test -c "$sg" 2>/dev/null && echo "container sees $sg: yes" || echo "container sees $sg: NO"; fi
    done
    echo
    echo "== Pipeline stage 4: ARM staging =="
    if [[ -n "$ROOT" ]]; then
      find "$ROOT/media/arm/work" -maxdepth 3 -type f -printf '%TY-%Tm-%Td %TH:%TM %s %p\n' 2>/dev/null | tail -n 20 || true
      find "$ROOT/media/arm/music" -maxdepth 3 -type f -printf '%TY-%Tm-%Td %TH:%TM %s %p\n' 2>/dev/null | tail -n 20 || true
    fi
    echo
    echo "== Pipeline stage 5: sorter =="
    systemctl is-active pcga-media-sort.path pcga-media-sort.timer 2>/dev/null || true
    journalctl -t PCGA-SORT -n 30 --no-pager 2>/dev/null || true
    echo
    echo "== Pipeline stage 5b: asynchronous metadata =="
systemctl is-active pcga-metadata-classify.path pcga-metadata-classify.timer 2>/dev/null || true
[[ -n "$ROOT" ]] && echo "metadata pending: $(find "$ROOT/media/metadata-pending" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l)"
journalctl -t PCGA-META -n 20 --no-pager 2>/dev/null || true
echo
echo "== Pipeline stage 5c: manual review =="
systemctl is-active pcga-manual-review.service 2>/dev/null || true
if [[ -n "$ROOT" ]]; then
  echo "reviewable pending/quarantine items: $(/usr/local/sbin/pcga-manual-review list 2>/dev/null | wc -l)"
fi
echo
echo "== Pipeline stage 6: Jellyfin destinations =="
    if [[ -n "$ROOT" ]]; then
      for d in movies tv music home-videos; do printf '%-12s ' "$d"; find "$ROOT/media/library/$d" -type f 2>/dev/null | wc -l; done
    fi
    echo
    echo "== Recent optical/ARM logs =="
    journalctl -t PCGA-ARM -n 80 --no-pager 2>/dev/null || true
    docker logs --tail 80 arm-rippers 2>&1 || true
    ;;
  optical-health)
    dev="${2:-}"
    if [[ -n "$dev" ]]; then sudo /usr/local/sbin/pcga-optical-health "$dev"; else sudo /usr/local/sbin/pcga-optical-health --all; fi
    ;;
  optical-health-deep)
    dev="${2:-}"
    [[ -n "$dev" ]] || { echo "Usage: game-archive optical-health-deep DEV" >&2; exit 64; }
    sudo /usr/local/sbin/pcga-optical-health --deep "$dev"
    ;;
  media-status)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    [[ "$dev" == /dev/* ]] || dev="/dev/${dev#/dev/}"
    name="${dev#/dev/}"
    echo "device: $dev"
    echo "allowed: $(grep -Fxq "$dev" /etc/pc-game-archive/media-drives 2>/dev/null && echo yes || echo no)"
    bytes="$(sudo blockdev --getsize64 "$dev" 2>/dev/null || echo 0)"
    echo "size_bytes: $bytes"
    if sudo /usr/local/sbin/pcga-optical-media-present "$dev"; then echo "medium_present: yes"; else echo "medium_present: no"; fi
    echo "udev:"
    udevadm info --query=property --name="$dev" 2>/dev/null | grep -E '^ID_CDROM|^ID_FS_' || true
    echo "rip_unit: $(systemctl is-active "pcga-arm-rip@${name}.service" 2>/dev/null || true)"
    ;;
  media-kick)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    [[ "$dev" == /dev/* ]] || dev="/dev/${dev#/dev/}"
    name="${dev#/dev/}"
    grep -Fxq "$dev" /etc/pc-game-archive/media-drives 2>/dev/null || { echo "$dev is not assigned to ARM" >&2; exit 2; }
    sudo /usr/local/sbin/pcga-optical-media-present "$dev" || { echo "No readable medium detected in $dev" >&2; exit 3; }
    if systemctl is-active --quiet "pcga-arm-rip@${name}.service"; then
      echo "pcga-arm-rip@${name}.service is already active"
      exit 0
    fi
    echo "Starting guarded ARM ingest for $dev"
    sudo systemctl start --no-block "pcga-arm-rip@${name}.service"
    echo "Follow: journalctl -fu pcga-arm-rip@${name}.service"
    ;;
  pipeline-kick)
    dev="${2:-$(head -n1 /etc/pc-game-archive/media-drives 2>/dev/null || true)}"
    [[ -n "$dev" ]] || { echo "No ARM media drive assigned" >&2; exit 1; }
    name="${dev#/dev/}"
    echo "Triggering the real ARM systemd path for $dev"
    sudo systemctl start --no-block "pcga-arm-rip@${name}.service"
    echo "Follow it with: journalctl -fu pcga-arm-rip@${name}.service"
    echo "ARM trigger messages: journalctl -t PCGA-ARM -f"
    ;;
  doctor)
    echo "== Docker =="
    docker --version
    docker compose version
    echo
    echo "== Containers =="
    "${DC[@]}" ps
    echo
    echo "== GPU =="
    lspci | grep -Ei 'VGA compatible controller|3D controller|Display controller' || true
    [[ -d /dev/dri ]] && ls -l /dev/dri || true
    echo "Render-node drivers:"
    for n in /sys/class/drm/renderD*/device/driver; do [[ -e "$n" ]] && echo "$n -> $(readlink -f "$n")"; done
    command -v nvidia-smi >/dev/null 2>&1 && nvidia-smi || true
    echo
    echo "== Wolf input =="
    ls -l /dev/uinput /dev/uhid 2>/dev/null || true
    echo
    echo "== Optical drives =="
    lsscsi -g | grep -Ei 'cd|dvd|rom' || true
    echo "ARM media-drive assignment:"
    cat /etc/pc-game-archive/media-drives 2>/dev/null || true
    echo
    echo "== Jellyfin =="
    if [[ -r .env ]]; then
      JFPORT="$(awk -F= '$1=="JELLYFIN_PORT" {print substr($0,index($0,"=")+1)}' .env | tail -n1)"
    else
      JFPORT=8096
    fi
    curl -fsS --max-time 5 "http://127.0.0.1:${JFPORT:-8096}/System/Info/Public" 2>/dev/null | jq '{Version,StartupWizardCompleted,ServerName}' 2>/dev/null || true
    docker inspect jellyfin --format '{{range .Mounts}}{{println .Destination "<-" .Source}}{{end}}' 2>/dev/null || true
    echo
    echo "== Media library =="
    if [[ -r .env ]]; then
      ROOT="$(awk -F= '$1=="ARCHIVE_ROOT" {print substr($0,index($0,"=")+1)}' .env)"
      if [[ -n "$ROOT" ]]; then
        find "$ROOT/media/library" -maxdepth 2 -type d -print 2>/dev/null || true
        echo "ARM video staging: $(find "$ROOT/media/arm/work/completed" -mindepth 1 -maxdepth 2 2>/dev/null | wc -l) entries"
        echo "ARM audio staging: $(find "$ROOT/media/arm/music" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l) entries"
        echo "Metadata pending:  $(find "$ROOT/media/metadata-pending" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l) entries"
echo "Quarantine:        $(find "$ROOT/media/quarantine" -type f 2>/dev/null | wc -l) files"
      fi
    fi
    echo
    echo "== Manual media review =="
    systemctl is-active pcga-manual-review.service 2>/dev/null || true
    /usr/local/sbin/pcga-manual-review list 2>/dev/null | head -n 10 || true
    echo
    echo "== Media sorter =="
    systemctl is-enabled pcga-media-sort.path pcga-media-sort.timer 2>/dev/null || true
    systemctl is-active pcga-media-sort.path pcga-media-sort.timer 2>/dev/null || true
    echo
    echo "== Legacy game network =="
    docker network inspect legacy-games --format '{{json .IPAM.Config}}' 2>/dev/null || true
    ;;
  *)
    echo "Usage: game-archive {up|down|restart|status|logs [service]|pull|update|sort-media|sorter-status|media-audit|media-test|manual-sort|manual-review-list|manual-review-status|manual-review-token|manual-review-url|manual-review-test|classify|classification-status|metadata-classify|metadata-status|tv-reconcile|tv-reconcile-apply|jellyfin-configure|jellyfin-refresh|jellyfin-audit|jellyfin-reset-fresh|jellyfin-repair-admin|jellyfin-forget-token|credentials|immich-status|immich-logs|immich-restart|romm-status|romm-logs|romm-restart|arm-metadata-configure [omdb|tmdb|--clear]|arm-configure|arm-stop [DEV]|arm-reconcile [DEV]|makemkv-sdf-sync [DEV]|makemkv-preflight [DEV]|pipeline-status|pipeline-status-url|pipeline-status-logs|dedupe-audit|dedupe-run|dedupe-library|dedupe-status|control-status|control-config|ingest-audit|ingest-reconcile|raw-review [DISC]|recover-raw [DISC]|optical-identify [DEV]|optical-dispatch [DEV]|pc-disc-rip [DEV]|arm-test [DEV]|arm-audit|pipeline-audit|optical-health [DEV]|optical-health-deep DEV|media-status [DEV]|media-kick [DEV]|pipeline-kick [DEV]|doctor}" >&2
    exit 2
    ;;
esac
HELPER
chmod 0755 /usr/local/bin/game-archive

# ----- v0.17.53 release component overlay -----------------------------------
# Newer releases keep canonical component files beside the installer. Overlay
# the generated bootstrap copies here so clean installs and upgrades execute the
# exact same optical relationship code.
if [[ -d "$RELEASE_DIR/components" ]]; then
  install -m 0755 "$RELEASE_DIR/components/pcga-optical-dispatch" /usr/local/sbin/pcga-optical-dispatch
  install -m 0755 "$RELEASE_DIR/components/pcga-arm-rip" /usr/local/sbin/pcga-arm-rip
  install -m 0755 "$RELEASE_DIR/components/pcga-media-sort" /usr/local/sbin/pcga-media-sort
  install -m 0755 "$RELEASE_DIR/components/pcga-classify" /usr/local/sbin/pcga-classify
  install -m 0755 "$RELEASE_DIR/components/pcga-manual-review" /usr/local/sbin/pcga-manual-review
  install -m 0755 "$RELEASE_DIR/components/pcga-media-disc-metadata" /usr/local/sbin/pcga-media-disc-metadata
  install -m 0755 "$RELEASE_DIR/components/pcga-media-intake" /usr/local/sbin/pcga-media-intake
  install -m 0755 "$RELEASE_DIR/components/pcga-game-disc-metadata" /usr/local/sbin/pcga-game-disc-metadata
  install -m 0755 "$RELEASE_DIR/components/pcga-game-orchestrator" /usr/local/sbin/pcga-game-orchestrator
  [[ -x /usr/local/sbin/pcga-game-orchestrator ]] || die "PC game orchestrator did not install"
  install -m 0644 "$RELEASE_DIR/components/pcga-game-orchestrator.service" /etc/systemd/system/pcga-game-orchestrator.service
  install -m 0644 "$RELEASE_DIR/components/pcga-game-orchestrator.timer" /etc/systemd/system/pcga-game-orchestrator.timer
  install -m 0755 "$RELEASE_DIR/components/pcga-status-server.py" "$STACK_DIR/status/server.py"
  install -m 0755 "$RELEASE_DIR/components/pcga-game-stack-start" /usr/local/sbin/pcga-game-stack-start
  install -m 0755 "$RELEASE_DIR/components/pcga-service-auth" /usr/local/sbin/pcga-service-auth
  install -m 0755 "$RELEASE_DIR/components/pcga-control" /usr/local/sbin/pcga-control
  install -m 0755 "$RELEASE_DIR/components/pcga-secure-context-bootstrap" /usr/local/sbin/pcga-secure-context-bootstrap
  install -m 0755 "$RELEASE_DIR/components/pcga-moonlight-web-bootstrap" /usr/local/sbin/pcga-moonlight-web-bootstrap
  install -d -m 0755 /var/lib/pc-game-archive/media-intake/items /var/lib/pc-game-archive/media-intake/discs /var/lib/pc-game-archive/media-intake/collections /var/lib/pc-game-archive/game-intake/assets /var/lib/pc-game-archive/game-installs "$ARCHIVE_ROOT/games/installed"
  if [[ ! -e /etc/pc-game-archive/game-metadata.env ]]; then
    cat > /etc/pc-game-archive/game-metadata.env <<'PCGA_GAME_METADATA_ENV'
# PCGA game profile enrichment. Steam Store needs no key and is conservative.
PCGA_STEAM_STORE_METADATA=1
PCGA_METADATA_LANGUAGE=english
PCGA_METADATA_COUNTRY=US
# Interactive canonical PC-game profile lookup. RAWG requires a personal API key;
# the portal stores it only in this root-readable host environment file.
PCGA_GAME_DB_PROVIDER=rawg
RAWG_API_KEY=
# Additional provider credentials are reserved for future adapters.
IGDB_CLIENT_ID=
IGDB_CLIENT_SECRET=
STEAMGRIDDB_API_KEY=
PCGA_GAME_METADATA_ENV
    chmod 0600 /etc/pc-game-archive/game-metadata.env
  fi
  if [[ ! -e /etc/pc-game-archive/game-runtime.env ]]; then
    cat > /etc/pc-game-archive/game-runtime.env <<'PCGA_GAME_RUNTIME_ENV'
PCGA_GAME_RUNTIME_IMAGE=ghcr.io/games-on-whales/lutris:edge
PCGA_INSTALL_TIMEOUT_SECONDS=1800
PCGA_GAME_RUNTIME_ENV
    chmod 0600 /etc/pc-game-archive/game-runtime.env
  fi
  if [[ -f "$STACK_DIR/compose.status.yml" ]]; then
    python3 - "$STACK_DIR/compose.status.yml" <<'PY_PCGA_GAME_PORTAL'
from pathlib import Path
import sys
p=Path(sys.argv[1]); lines=p.read_text().splitlines()
for mount in ('/var/lib/pc-game-archive/game-intake:/pcga/game-intake:ro','/var/lib/pc-game-archive/game-installs:/pcga/game-installs:ro'):
    if any(mount in x for x in lines): continue
    out=[]; inserted=False
    for line in lines:
        out.append(line)
        if '/pcga/lancommander:ro' in line and not inserted:
            indent=line[:len(line)-len(line.lstrip())]; out.append(f'{indent}- "{mount}"'); inserted=True
    if not inserted: raise SystemExit('could not locate LANCommander status mount anchor')
    lines=out
p.write_text('\n'.join(lines)+'\n')
PY_PCGA_GAME_PORTAL
  fi
  systemctl daemon-reload
  systemctl enable pcga-game-orchestrator.timer >/dev/null 2>&1 || true
fi
if [[ -f /usr/local/bin/game-archive ]]; then
python3 - /usr/local/bin/game-archive <<'PY_MEDIA_WRAP'
from pathlib import Path
import sys
p=Path(sys.argv[1]);s=p.read_text()
if '  media-intake)' not in s and '  arm-test)' in s:
    block='  media-intake)\n    shift || true\n    sudo /usr/local/sbin/pcga-media-intake "$@"\n    ;;\n'
    s=s.replace('  arm-test)\n',block+'  arm-test)\n',1)
if '  game-install)' not in s and '  arm-test)' in s:
    block='  game-install)\n    shift || true\n    sudo /usr/local/sbin/pcga-game-orchestrator "$@"\n    ;;\n'
    s=s.replace('  arm-test)\n',block+'  arm-test)\n',1)
s=s.replace('|pc-disc-rip [DEV]|arm-test [DEV]|','|pc-disc-rip [DEV]|media-intake <command>|game-install [--status|--set-id ID|--force]|arm-test [DEV]|')
p.write_text(s)
PY_MEDIA_WRAP
chmod 0755 /usr/local/bin/game-archive
fi

# ----- Start services --------------------------------------------------------
arm_rip_active_host() {
  systemctl list-units --all --state=active,activating --plain --no-legend \
    'pcga-arm-rip@*.service' 2>/dev/null | grep -q 'pcga-arm-rip@' && return 0
  if docker inspect -f '{{.State.Running}}' arm-rippers 2>/dev/null | grep -qx true; then
    docker exec arm-rippers sh -lc "ps -eo args | grep -q '[p]ython3 /opt/arm/arm/ripper/main.py'" 2>/dev/null && return 0
  fi
  return 1
}

if [[ $START_SERVICES -eq 1 ]]; then
  if [[ $ENABLE_MEDIA_RIPPER -eq 1 ]] && arm_rip_active_host; then
    die "An ARM optical rip is active. Setup will not pull/recreate/restart containers during a rip. Wait for pcga-arm-rip@<drive>.service to finish, then rerun the installer."
  fi
  log "Pulling service images"
  (
    cd "$STACK_DIR"
    docker compose "${COMPOSE_FILES[@]}" pull
  )

  # Always bring up LANCommander. Only include Wolf when its compose file exists.
  # Hold the same game-stack lock used by boot/timer reconciliation so a rerun or
  # partially installed older release cannot mutate these containers concurrently.
  log "Starting configured services"
  (
    cd "$STACK_DIR"
    exec 8>/run/pcga-game-stack-start.lock
    flock -w 180 8 || die "Timed out waiting for another PCGA game-stack reconciliation to finish"
    export PCGA_GAME_STACK_LOCK_HELD=1
    compose_up_retry(){
      local out rc attempt
      for attempt in 1 2 3 4 5 6; do
        out="$(mktemp)"
        if docker compose "${COMPOSE_FILES[@]}" up "$@" >"$out" 2>&1; then
          rm -f "$out"
          return 0
        else
          rc=$?
        fi
        if grep -Fq 'removal of container' "$out" && grep -Fq 'already in progress' "$out"; then
          log "Docker is still finishing a prior container removal; retrying Compose (${attempt}/6)"
          rm -f "$out"
          sleep $((attempt * 2))
          continue
        fi
        cat "$out" >&2
        rm -f "$out"
        return "$rc"
      done
      die "Docker did not finish the prior container removal after bounded retries"
    }
    if [[ -f "$STACK_DIR/compose.moonlight-web.yml" ]]; then
      PCGA_STATUS_TLS_PORT=8443 PCGA_MOONLIGHT_WEB_PORT=8101 /usr/local/sbin/pcga-secure-context-bootstrap
    fi
    compose_up_retry -d
    log "Completing zero-touch game-library initialization"
    /usr/local/sbin/pcga-appliance-credentials
    if [[ -f "$STACK_DIR/compose.moonlight-web.yml" ]]; then
      /usr/local/sbin/pcga-moonlight-web-bootstrap || die "Moonlight Web appliance bootstrap failed; inspect: docker logs --tail 150 pcga-moonlight-web"
      ca=/etc/pc-game-archive/tls/pcga-ca.crt
      tls_ready=0
      for _ in $(seq 1 30); do
        if curl --cacert "$ca" -fsS --max-time 3 https://127.0.0.1:8101/api/authenticate >/dev/null 2>&1 && \
           curl --cacert "$ca" -fsS --max-time 3 https://127.0.0.1:8443/health >/dev/null 2>&1; then
          tls_ready=1; break
        fi
        sleep 1
      done
      [[ $tls_ready -eq 1 ]] || die "PCGA secure browser endpoints did not become ready on HTTPS ports 8101/8443"
    fi
    /usr/local/sbin/pcga-lancommander-bootstrap || die "LANCommander appliance bootstrap failed; PCGA will not leave PC Games in a half-configured state. Inspect: docker logs --tail 150 lancommander"
    if [[ $ENABLE_ROMM -eq 1 ]]; then
      if /usr/local/sbin/pcga-romm-bootstrap; then
        compose_up_retry -d --no-deps --force-recreate romm
      else
        warn "RomM bootstrap did not complete; primary Console Games tile will stay unavailable."
      fi
    fi
    unset PCGA_GAME_STACK_LOCK_HELD
    flock -u 8 || true
    exec 8>&-
  )

  if docker inspect -f '{{.State.Running}}' pcga-status 2>/dev/null | grep -qx true; then
    ACTUAL_STATUS_GATEWAY="$(docker inspect pcga-status --format '{{range .NetworkSettings.Networks}}{{println .Gateway}}{{end}}' 2>/dev/null | awk 'NF{print; exit}' || true)"
    if [[ -n "$ACTUAL_STATUS_GATEWAY" ]]; then
      log "Binding PCGA host control routes to pcga-status network gateway $ACTUAL_STATUS_GATEWAY"
      CONTROL_BIND="$ACTUAL_STATUS_GATEWAY"
      PUBLIC_MEDIA_BIND="$ACTUAL_STATUS_GATEWAY"
      sed -i -E "s/--bind [^ ]+ --port 8100/--bind ${CONTROL_BIND} --port 8100/" /etc/systemd/system/pcga-control.service
      sed -i -E "s/--bind [^ ]+ --port 8099/--bind ${PUBLIC_MEDIA_BIND} --port 8099/" /etc/systemd/system/pcga-public-media.service
      python3 - "$STACK_DIR/compose.status.yml" "$ACTUAL_STATUS_GATEWAY" <<'PYSTATUSGATEWAY'
from pathlib import Path
import re, sys
p=Path(sys.argv[1]); gateway=sys.argv[2]
text=p.read_text()
for key,value in {
    'PCGA_CONTROL_UPSTREAM': f'http://{gateway}:8100',
    'PCGA_PUBLIC_MEDIA_UPSTREAM': f'http://{gateway}:8099',
}.items():
    pat=rf'(^\s*{re.escape(key)}:\s*)["\']?[^"\'\n]+["\']?\s*$'
    text=re.sub(pat,lambda m:m.group(1)+f'"{value}"',text,flags=re.M)
p.write_text(text)
PYSTATUSGATEWAY
      systemctl daemon-reload
      systemctl restart pcga-control.service pcga-public-media.service
      ( cd "$STACK_DIR" && docker compose "${FILES[@]}" up -d --no-deps --force-recreate pcga-status )
    fi
  fi

  if [[ $ARM_CONFIG_CREATED -eq 1 ]]; then
    log "Waiting for ARM to create its default configuration"
    if /usr/local/sbin/pcga-arm-configure; then
      log "ARM unattended archival profile applied (no ARM restart required)"
      if /usr/local/sbin/pcga-media-test >/dev/null; then
        log "Media sorter self-test passed"
      else
        warn "Media sorter self-test failed; run 'game-archive media-test' for details."
      fi
    else
      warn "ARM config was not ready; run 'game-archive arm-configure' after the ARM container is healthy."
    fi
  fi

  log "Validating portal-native PC Games LANCommander bridge"
  portal_ok=0
  for _ in $(seq 1 30); do
    if curl -fsS --max-time 3 "http://127.0.0.1:${STATUS_PORT}/health" >/dev/null 2>&1; then
      portal_ok=1
      break
    fi
    sleep 2
  done
  [[ $portal_ok -eq 1 ]] || die "PCGA portal did not become healthy on port $STATUS_PORT; inspect: docker logs --tail 150 pcga-status"
  lc_health="$(mktemp)"
  lc_ok=0
  for _ in $(seq 1 20); do
    code="$(curl -sS --max-time 5 -o "$lc_health" -w '%{http_code}' "http://127.0.0.1:${STATUS_PORT}/api/pc-games/health" 2>/dev/null || true)"
    if [[ "$code" == "200" ]] && python3 - "$lc_health" <<'PYLCHEALTH' >/dev/null 2>&1
import json,sys
with open(sys.argv[1], encoding='utf-8') as fh: d=json.load(fh)
raise SystemExit(0 if d.get('service_ready') is True and d.get('catalog_db_readable') is True else 1)
PYLCHEALTH
    then
      lc_ok=1
      break
    fi
    sleep 1
  done
  if [[ $lc_ok -ne 1 ]]; then
    lc_detail="$(python3 - "$lc_health" <<'PYLCDETAIL' 2>/dev/null || true
import json,sys
try:
    with open(sys.argv[1], encoding='utf-8') as fh: d=json.load(fh)
    print(d.get('detail') or 'LANCommander portal health endpoint did not report a catalog')
    disc=d.get('discovery') or {}
    if disc.get('candidates'): print('candidates='+json.dumps(disc.get('candidates'), separators=(',',':')))
except Exception:
    print('LANCommander portal health endpoint did not return valid JSON')
PYLCDETAIL
)"
    rm -f "$lc_health"
    die "PC Games LANCommander bridge is not healthy: ${lc_detail}. Check: curl -sS http://127.0.0.1:${STATUS_PORT}/api/pc-games/health ; docker logs --tail 150 lancommander ; docker logs --tail 150 pcga-status"
  fi
  rm -f "$lc_health"
  log "PC Games LANCommander catalog bridge validated end-to-end"

  if [[ $ENABLE_ROMM -eq 1 ]]; then
    log "Waiting for RomM console library"
    romm_ok=0
    for _ in $(seq 1 60); do
      code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 3 "http://127.0.0.1:${ROMM_PORT}/" || true)"
      case "$code" in 200|301|302|303|307|308) romm_ok=1; break;; esac
      sleep 2
    done
    if [[ $romm_ok -eq 1 ]]; then
      log "RomM is reachable on port $ROMM_PORT"
    else
      warn "RomM did not become reachable; inspect: docker logs --tail 150 romm"
    fi

    # When PCGA successfully owns the RomM bootstrap identity, require the
    # complete portal-native emulator path as part of clean-install readiness.
    # This deliberately distinguishes an open RomM TCP port from a usable
    # EmulatorJS pipeline.
    ROMM_BOOTSTRAP_STATE="$(cat /var/lib/pc-game-archive/bootstrap/romm.state 2>/dev/null || true)"
    if [[ "$ROMM_BOOTSTRAP_STATE" == "ready" ]]; then
      log "Validating portal-native Console Games emulator pipeline"
      portal_ok=0
      for _ in $(seq 1 30); do
        if curl -fsS --max-time 3 "http://127.0.0.1:${STATUS_PORT}/health" >/dev/null 2>&1; then
          portal_ok=1
          break
        fi
        sleep 2
      done
      [[ $portal_ok -eq 1 ]] || die "PCGA portal did not become healthy on port $STATUS_PORT; inspect: docker logs --tail 150 pcga-status"

      emulator_health="$(mktemp)"
      emulator_ok=0
      for _ in $(seq 1 30); do
        code="$(curl -sS --max-time 6 -o "$emulator_health" -w '%{http_code}' "http://127.0.0.1:${STATUS_PORT}/api/games/health?refresh=1" 2>/dev/null || true)"
        if [[ "$code" == "200" ]] && python3 - "$emulator_health" <<'PYHEALTH' >/dev/null 2>&1
import json, sys
with open(sys.argv[1], encoding='utf-8') as fh:
    data=json.load(fh)
raise SystemExit(0 if data.get('available') is True else 1)
PYHEALTH
        then
          emulator_ok=1
          break
        fi
        sleep 2
      done
      if [[ $emulator_ok -ne 1 ]]; then
        emulator_detail="$(python3 - "$emulator_health" <<'PYDETAIL' 2>/dev/null || true
import json, sys
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data=json.load(fh)
    print(data.get('detail') or 'unknown emulator pipeline failure')
except Exception:
    print('portal emulator health endpoint did not return valid JSON')
PYDETAIL
)"
        rm -f "$emulator_health"
        die "Console Games emulator pipeline is not healthy: ${emulator_detail}. Check: curl -sS http://127.0.0.1:${STATUS_PORT}/api/games/health?refresh=1 ; docker logs --tail 150 romm ; docker logs --tail 150 pcga-status"
      fi
      rm -f "$emulator_health"
      log "Console Games emulator pipeline validated end-to-end"
    else
      die "RomM bootstrap state is '${ROMM_BOOTSTRAP_STATE:-missing}', expected 'ready'. PCGA must own a verified appliance identity before Console Games can be considered configured. Existing non-PCGA RomM administrators are preserved; inspect: journalctl -u pcga-game-stack.service -n 150 --no-pager ; docker logs --tail 150 romm"
    fi
  fi

  if [[ $ENABLE_ROMM -eq 1 ]]; then
    log "Validating portal-native ROM Collection bridge"
    collection_ok=0
    for _ in $(seq 1 20); do
      if curl -fsS --max-time 5 "http://127.0.0.1:${STATUS_PORT}/api/games/collection/platforms" | python3 -c 'import json,sys; d=json.load(sys.stdin); assert any(x.get("slug")=="nes" for x in d.get("items",[]))' >/dev/null 2>&1; then
        collection_ok=1
        break
      fi
      sleep 1
    done
    [[ $collection_ok -eq 1 ]] || die "ROM Collection bridge did not become healthy; inspect: systemctl status pcga-public-media.service ; docker logs --tail 100 pcga-status"
    log "ROM Collection bridge is ready"
  fi

  log "Validating portal-native Manual Review bridge"
  review_ok=0
  for _ in $(seq 1 20); do
    if curl -fsS --max-time 5 "http://127.0.0.1:${STATUS_PORT}/api/review/items" | python3 -c 'import json,sys; d=json.load(sys.stdin); assert d.get("ok") is True and isinstance(d.get("items"),list)' >/dev/null 2>&1; then
      review_ok=1
      break
    fi
    sleep 1
  done
  [[ $review_ok -eq 1 ]] || die "Portal-native Manual Review bridge did not become healthy; inspect: systemctl status pcga-manual-review.service ; docker logs --tail 100 pcga-status"
  log "Portal-native Manual Review bridge is ready"

  if [[ $ENABLE_JELLYFIN -eq 1 ]]; then
    log "Provisioning/synchronizing Jellyfin"
    if /usr/local/sbin/pcga-jellyfin-configure --non-interactive; then
      log "Jellyfin admin/media setup synchronized and Jellyfin restarted"
    else
      warn "Jellyfin is already initialized with credentials other than the managed default and no saved token is available."
      warn "Run: game-archive jellyfin-configure"
    fi
    /usr/local/sbin/pcga-jellyfin-appliance-user || warn "Jellyfin common PCGA account reconciliation will retry in the background."
  fi
  if [[ $ENABLE_IMMICH -eq 1 ]]; then
    /usr/local/sbin/pcga-immich-bootstrap || warn "Immich common PCGA account reconciliation will retry in the background."
  fi
fi

if [[ $START_SERVICES -eq 1 ]]; then
  # Initial provisioning is now complete. Hand ownership to the normal serialized
  # boot/timer reconciliation path only after the installer has stopped mutating
  # game-service containers directly.
  systemctl restart pcga-game-stack.service >/dev/null 2>&1 || warn "PCGA game-stack startup sequence is not healthy yet; inspect: journalctl -u pcga-game-stack.service -n 150 --no-pager"
  systemctl enable --now pcga-service-auth.timer >/dev/null 2>&1 || warn "PCGA service-auth timer could not be enabled"
  systemctl enable --now pcga-game-orchestrator.timer >/dev/null 2>&1 || warn "PCGA PC-game orchestrator timer could not be enabled"
  /usr/local/sbin/pcga-game-orchestrator --metadata-only --no-network --force >/dev/null 2>&1 || true
  systemctl --no-block start pcga-game-orchestrator.service >/dev/null 2>&1 || true
fi

# ----- Summary ---------------------------------------------------------------
SERVER_IP="$(hostname -I 2>/dev/null | awk '{print $1}')"
[[ -n "$SERVER_IP" ]] || SERVER_IP="<server-ip>"

printf '\n\033[1;32mPC Game Archive base setup complete.\033[0m\n\n'
printf 'PC Games:      https://%s:8443/#pc-games\n' "$SERVER_IP"
if [[ $ENABLE_JELLYFIN -eq 1 ]]; then printf 'Jellyfin:      http://%s:%s\n' "$SERVER_IP" "$JELLYFIN_PORT"; fi
if [[ $ENABLE_IMMICH -eq 1 ]]; then printf 'Photos (Immich): http://%s:%s\n' "$SERVER_IP" "$IMMICH_PORT"; fi
if [[ $ENABLE_ROMM -eq 1 ]]; then printf 'Console Games: http://%s:%s/#games\n' "$SERVER_IP" "$STATUS_PORT"; fi
if [[ $ARM_CONFIG_CREATED -eq 1 ]]; then printf 'ARM ripper:    http://%s:%s/setup\n' "$SERVER_IP" "$ARM_PORT"; fi
printf 'PCGA Portal:   http://%s:%s/\n' "$SERVER_IP" "$STATUS_PORT"
printf 'PCGA Secure:   https://%s:8443/\n' "$SERVER_IP"
printf 'PCGA Local CA: http://%s:%s/pcga-ca.crt\n' "$SERVER_IP" "$STATUS_PORT"
if [[ $WOLF_CONFIG_CREATED -eq 1 ]]; then
  printf 'Wolf Den:      http://%s:8080\n' "$SERVER_IP"
  printf 'Wolf pairing:  http://%s:47989\n' "$SERVER_IP"
else
  printf 'Wolf:          not started/configured yet (GPU not ready or disabled)\n'
fi
printf 'Storage:       %s\n' "$ARCHIVE_ROOT"
printf 'Media library: %s/media/library\n' "$ARCHIVE_ROOT"
printf 'Stack config:  %s\n' "$STACK_DIR"
[[ -n "$RENDER_NODE" && "$RENDER_NODE" != "auto" ]] && printf 'Render node:   %s\n' "$RENDER_NODE"
printf 'Management:    Portal Control Center is primary; common login: sudo game-archive credentials\n'
printf '\nOptical drives detected:\n'
lsscsi -g | grep -Ei 'cd|dvd|rom' || printf '  none detected\n'
if [[ $ARM_CONFIG_CREATED -eq 1 ]]; then
  printf 'ARM media drives: %s\n' "${MEDIA_DRIVES[*]}"
else
  printf 'ARM media drives: none assigned (use --media-drive /dev/srN)\n'
fi

cat <<'NEXT'

After setup:
  1. For browser PC-game streaming, first download http://<server>:<status-port>/pcga-ca.crt,
     trust it as a local certificate authority on the client, then use https://<server>:8443/.
     The HTTP portal remains available for this initial trust/bootstrap step and non-streaming admin.
  2. Open the PCGA Control Center. It is the primary appliance administration surface for libraries,
     ingest/review, console emulation, media/photos, automation, service health and maintenance.
     Routine service configuration belongs there.
  3. PCGA bootstraps service databases, storage paths, background jobs, generated credentials,
     Jellyfin libraries, RomM ROM/BIOS mappings and service lifecycle automatically. Native
     Jellyfin, Immich, RomM, ARM and Wolf interfaces are available under Control Center > Advanced
     for deep application-specific administration and troubleshooting.
  4. PCGA creates one common appliance administrator for user-facing services that require login.
     Run `sudo game-archive credentials` to display it when using an Advanced native interface.
     Database passwords, API keys and bearer/session tokens remain separate internal secrets.
  5. Put console games under media/library/console-games/roms/<platform>/ and firmware you legally
     possess under media/library/console-games/bios/<platform>/. PCGA manages discovery/rescans.
     Put shared photos under media/library/photos/; PCGA exposes that common archive to Jellyfin,
     Immich and the portal.
  6. The portal status strip is the normal starting point for health/review/storage issues. Use the
     Advanced section or CLI only when a native diagnostic is genuinely needed.

Security note: this is a LAN appliance. Keep service ports LAN-only and do not port-forward the
individual application ports to the public Internet.
NEXT

if [[ $REBOOT_REQUIRED -eq 1 ]]; then
  printf '\n\033[1;33mREBOOT REQUIRED.\033[0m Reboot the host, then run this same script again.\n'
fi
